	// Both the default fast path's precomputed keys and the explicit-key
	// comparator must distinguish punctuation without relying on installed
	// OS locales. Otherwise -u silently drops distinct file names.
	#[test]
	fn shifted_collation_retains_punctuation_in_comparisons_and_sort_keys() {
		let locale = icu_locale_core::Locale::try_from_str("en-US").unwrap();
		let collator = crate::locale::collator_for_locale(locale).unwrap();
		let inputs = ["src/a-b.ts", "src/ab.ts", "src/a_b.ts", "src/a.b.ts", "src/a b.ts"];
		let mut keys = Vec::new();
		for input in inputs {
			let mut key = Vec::new();
			collator.write_sort_key_utf8_to(input.as_bytes(), &mut key).unwrap();
			keys.push(key);
		}
		for (index, left) in inputs.iter().enumerate() {
			for (other, right) in inputs.iter().enumerate().skip(index + 1) {
				let compared = collator.compare_utf8(left.as_bytes(), right.as_bytes());
				assert_ne!(compared, Ordering::Equal);
				assert_eq!(keys[index].cmp(&keys[other]), compared);
			}
		}
		assert_eq!(collator.compare_utf8(b"same", b"same"), Ordering::Equal);
	}

	// Exercise repeated invocations and both sorting paths, while keeping
	// explicit key/filter equivalence instead of adding a whole-line tie-break.
	#[test]
	fn locale_unique_preserves_paths_and_respects_explicit_equivalence() {
		if !locale_installed("en_US.UTF-8") {
			eprintln!("skipping host-locale integration: en_US.UTF-8 not installed");
			return;
		}
		let input = "src/a-b.ts\nsrc/ab.ts\nsrc/a_b.ts\nsrc/a.b.ts\nsrc/a-b.ts\n";
		for _ in 0..2 {
			for args in [&["-u"][..], &["-k1,1", "-u"]] {
				let (code, out, err) = sort_in_locale("LC_ALL", "en_US.UTF-8", args, input);
				assert_eq!(code, 0, "{err}");
				let mut lines: Vec<_> = out.lines().collect();
				lines.sort_unstable();
				assert_eq!(lines, ["src/a-b.ts", "src/a.b.ts", "src/a_b.ts", "src/ab.ts"]);
			}
		}
		for (args, input, expected) in [
			(&["-k1,1", "-u"][..], "key first\nkey second\nother third\n", "key first\nother third\n"),
			(&["-d", "-u"][..], "a-b\na_b\na.b\nab\n", "a-b\n"),
			(&["-f", "-u"][..], "Alpha\nalpha\n", "Alpha\n"),
			(&["-n", "-u"][..], "2 first\n2 second\n10 third\n", "2 first\n10 third\n"),
			(&["-s", "-k1,1"][..], "key z\nkey a\nkey m\n", "key z\nkey a\nkey m\n"),
		] {
			let (code, out, err) = sort_in_locale("LC_ALL", "en_US.UTF-8", args, input);
			assert_eq!(code, 0, "{err}");
			assert_eq!(out, expected, "{args:?}");
		}
	}

	// Failure mode: collation used uucore's single collator, built from the
	// omp process's locale, so `LC_ALL=sv_SE.UTF-8 sort` ordered text by the
	// process locale (or by bytes) and `--debug` named the process locale.
	#[test]
	fn collation_follows_the_shell_locale() {
		// Swedish puts å and ä after z, å first; English keeps them beside a;
		// byte order would put ä (C3 A4) before å (C3 A5).
		let input = "z\nä\nå\na\n";
		for (locale, expected) in [("sv_SE.UTF-8", "a\nz\nå\nä\n"), ("en_US.UTF-8", "a\nå\nä\nz\n")] {
			if !locale_installed(locale) {
				eprintln!("skipping {locale}: not installed");
				continue;
			}
			for args in [&[][..], &["-k1,1"]] {
				let (code, out, err) = sort_in_locale("LC_ALL", locale, args, input);
				assert_eq!(code, 0, "{err}");
				assert_eq!(out, expected, "{locale} {args:?}");
			}
			let (_, _, err) = sort_in_locale("LC_ALL", locale, &["--debug"], input);
			let rules = format!("text ordering performed using ‘{locale}’ sorting rules");
			assert!(err.contains(&rules), "{err}");
		}
	}

	// Failure mode: shifted collation at tertiary strength treated distinct
	// punctuation-bearing paths as equal, so `sort -u` discarded records.
	#[test]
	fn locale_unique_preserves_punctuation_unless_the_key_ignores_it() {
		if !locale_installed("en_US.UTF-8") {
			eprintln!("skipping: en_US.UTF-8 not installed");
			return;
		}
		let input = "src/a-b.ts\nsrc/ab.ts\nsrc/a_b.ts\nsrc/a.b.ts\n";
		for args in [&["-u"][..], &["-u", "-k1,1"]] {
			for _ in 0..2 {
				let (code, out, err) = sort_in_locale("LANG", "en_US.UTF-8", args, input);
				assert_eq!(code, 0, "{err}");
				let mut lines: Vec<_> = out.lines().collect();
				lines.sort_unstable();
				assert_eq!(lines, ["src/a-b.ts", "src/a.b.ts", "src/a_b.ts", "src/ab.ts"], "{args:?}");
			}
		}
		let (code, out, err) = sort_in_locale(
			"LANG",
			"en_US.UTF-8",
			&["-u", "-k1,1"],
			"group src/a-b.ts\ngroup src/ab.ts\n",
		);
		assert_eq!(code, 0, "{err}");
		assert_eq!(out, "group src/a-b.ts\n");
		let (code, out, err) = sort_in_locale("LANG", "en_US.UTF-8", &["-d", "-u"], input);
		assert_eq!(code, 0, "{err}");
		assert_eq!(out, "src/a-b.ts\n");
	}

	// Failure mode: the decimal point and grouping came from the process
	// locale, so `LC_NUMERIC=de_DE.UTF-8 sort -n` read `2,5` as 2 (C process)
	// or 25 (en_US process, `,` grouping) instead of 2.5.
	#[test]
	fn numeric_sorts_read_the_shell_numeric_locale() {
		if !locale_installed("de_DE.UTF-8") {
			eprintln!("skipping: de_DE.UTF-8 not installed");
			return;
		}
		for mode in ["-n", "-g"] {
			let (code, out, err) = sort_in_locale("LC_NUMERIC", "de_DE.UTF-8", &["-s", mode], "2,5\n3\n2,1\n");
			assert_eq!(code, 0, "{err}");
			assert_eq!(out, "2,1\n2,5\n3\n", "{mode}");
		}
	}

	// Failure mode: `--parallel` was accepted and ignored, so invalid thread
	// counts sorted silently instead of failing as GNU sort does.
	#[test]
	fn parallel_validates_the_thread_count_like_gnu() {
		for (value, message) in [
			("0", "number in parallel must be nonzero"),
			("abc", "invalid --parallel argument 'abc'"),
			("", "invalid --parallel argument ''"),
			("-1", "invalid --parallel argument '-1'"),
			("4x", "invalid suffix in --parallel argument '4x'"),
		] {
			let (code, capture) = run_util::<Sort>(&[&format!("--parallel={value}")], "b\na\n", "/");
			assert_eq!(code, 2, "{value:?}");
			assert_eq!(capture.err(), format!("sort: {message}\n"), "{value:?}");
			assert_eq!(capture.out(), "", "{value:?}");
		}
	}

	#[test]
	fn parallel_sorts_on_its_own_pool() {
		let input: String = (0..5000).rev().map(|n| format!("{n:05}\n")).collect();
		let expected: String = (0..5000).map(|n| format!("{n:05}\n")).collect();
		for value in ["1", "2", " 4", "+4", "99999999999999999999999"] {
			for stable in [&[][..], &["-s"]] {
				let parallel = format!("--parallel={value}");
				let args: Vec<&str> = stable.iter().copied().chain([parallel.as_str()]).collect();
				let (code, capture) = run_util::<Sort>(&args, &input, "/");
				assert_eq!(code, 0, "{value:?}: {}", capture.err());
				assert!(capture.out() == expected, "{value:?} {stable:?}");
			}
		}
	}

	// Failure mode: `timeout 20 sort -z /dev/zero` returned after 55 s and
	// 25 GiB. Every input byte is a record, and the in-memory sort of a chunk
	// never looked at the cancellation; `-S 256M` held 6 GiB of records.
	// Without `-z`, /dev/zero is one line that never ends: reading it grew the
	// buffer until the host was killed, in sort, `-m` and `-c` alike.
	#[cfg(unix)]
	#[test]
	fn cancellation_stops_a_sort_of_endless_records() {
		for args in [&["-z", "-S", "256M"][..], &[], &["-m"], &["-c"]] {
			let (mut host, capture) = Host::for_test("sort", "", "/");
			let cancel = host.cancel_flag_for_test();
			let argv = std::iter::once("sort").chain(args.iter().copied()).chain(["/dev/zero"]);
			let sort = <Sort as clap::Parser>::try_parse_from(argv).expect("parse");
			let canceller = std::thread::spawn(move || {
				std::thread::sleep(std::time::Duration::from_millis(200));
				cancel.store(true, AtomicOrdering::Relaxed);
			});
			let started = std::time::Instant::now();
			let code = sort.run(&mut host);
			let elapsed = started.elapsed();
			canceller.join().expect("canceller");
			assert!(elapsed.as_secs() < 10, "{args:?}: sort ran {elapsed:?} after a cancel at 0.2 s");
			assert_ne!(code, 0, "{args:?}: a cancelled sort does not succeed");
			assert_eq!(
				(capture.out(), capture.err()),
				(String::new(), String::new()),
				"{args:?}: a cancelled sort prints nothing"
			);
		}
	}

	// Failure mode: chunks end where their records' memory reaches the
	// budget, mid-input. A record split or lost at a chunk edge, or chunks
	// merged out of order, changes the output.
	#[test]
	fn a_small_buffer_sorts_many_short_records_as_one_chunk_would() {
		// 60000 records over 997 keys: ties for -s, duplicates for -u.
		let records: Vec<(u32, u32)> = (0..60_000).map(|n| ((n * 7919) % 997, n)).collect();
		let input: String = records.iter().map(|(key, n)| format!("{key} {n}\n")).collect();
		let mut stable = records.clone();
		stable.sort_by_key(|(key, _)| key.to_string());
		let expected: String = stable.iter().map(|(key, n)| format!("{key} {n}\n")).collect();
		let (code, capture) = run_util::<Sort>(&["-S", "64K", "-s", "-k1,1"], &input, "/");
		assert_eq!(code, 0, "{}", capture.err());
		assert!(capture.out() == expected, "-s -k1,1 across chunks");

		let input: String = records.iter().map(|(key, _)| format!("{key}\n")).collect();
		let mut keys: Vec<String> = records.iter().map(|(key, _)| key.to_string()).collect();
		keys.sort();
		keys.dedup();
		let expected: String = keys.iter().map(|key| format!("{key}\n")).collect();
		let (code, capture) = run_util::<Sort>(&["-S", "64K", "-u"], &input, "/");
		assert_eq!(code, 0, "{}", capture.err());
		assert!(capture.out() == expected, "-u across chunks");
	}

	// Failure mode: a full buffer holding one separator was cut at an offset
	// counted from the wrong start, splitting a long line in two: `sort -m`
	// printed pieces of lines and `sort -c` reported disorder in sorted input.
	#[test]
	fn long_lines_survive_a_full_buffer() {
		let dir = tempfile::tempdir().expect("temp dir");
		let merged = ["a".repeat(5000), "b".repeat(5000), "c".repeat(70000)]
			.map(|line| line + "\n")
			.concat();
		std::fs::write(dir.path().join("merged"), &merged).expect("fixture");
		let (code, capture) = run_util::<Sort>(&["-m", "merged"], "", dir.path());
		assert_eq!(code, 0, "{}", capture.err());
		assert!(capture.out() == merged, "sort -m changed the lines");

		let checked = ["a".repeat(7), "b".repeat(100), "c".repeat(70000)]
			.map(|line| line + "\n")
			.concat();
		std::fs::write(dir.path().join("checked"), &checked).expect("fixture");
		let (code, capture) = run_util::<Sort>(&["-c", "-S", "10b", "checked"], "", dir.path());
		assert_eq!((code, capture.err()), (0, String::new()));
	}

	// Failure mode: when a file's unterminated last line was carried over to
	// the next chunk and the file then ended, the next file's first line was
	// appended to it.
	#[test]
	fn an_unterminated_last_line_stays_apart_from_the_next_file() {
		let dir = tempfile::tempdir().expect("temp dir");
		// 8 KiB, so a chunk filled at the end of `first`.
		let tail = "z".repeat(8 * 1024 - 4);
		std::fs::write(dir.path().join("first"), format!("x\ny\n{tail}")).expect("fixture");
		std::fs::write(dir.path().join("second"), "a\n").expect("fixture");
		let (code, capture) = run_util::<Sort>(&["-S", "8K", "first", "second"], "", dir.path());
		assert_eq!(code, 0, "{}", capture.err());
		assert!(capture.out() == format!("a\nx\ny\n{tail}\n"), "the files' lines ran together");
	}

	#[test]
	fn attached_equals_selects_equals_as_separator() {
		for args in [&["-t=", "-k2", "-nr"][..], &["-nrt=", "-k2"]] {
			let (code, capture) = run_util::<Sort>(args, "a=1\nb=3\n", "/");
			assert_eq!(code, 0, "{args:?}: {}", capture.err());
			assert_eq!(capture.out(), "b=3\na=1\n", "{args:?}");
		}
	}

	#[test]
	fn attached_separator_keeps_every_byte_after_t() {
		let (code, capture) = run_util::<Sort>(&["-t==", "-k2"], "a=1\n", "/");
		assert_eq!(code, 2);
		assert_eq!(capture.err(), "sort: separator must be exactly one character long: '=='\n");
	}

	#[test]
	fn separator_spelling_in_values_and_operands_is_left_alone() {
		let dir = tempfile::tempdir().expect("tempdir");
		std::fs::write(dir.path().join("-t="), "b\na\n").expect("fixture");
		let (code, capture) = run_util::<Sort>(&["--", "-t="], "", dir.path());
		assert_eq!(code, 0, "{}", capture.err());
		assert_eq!(capture.out(), "a\nb\n");

		std::fs::write(dir.path().join("in"), "d\nc\n").expect("fixture");
		let (code, capture) = run_util::<Sort>(&["-o", "-t=", "in"], "", dir.path());
		assert_eq!(code, 0, "{}", capture.err());
		assert_eq!(std::fs::read_to_string(dir.path().join("-t=")).expect("output"), "c\nd\n");
	}
}

import type { Api, AssistantMessage, Model } from "@oh-my-pi/pi-ai";
import { renderDemotedThinking } from "@oh-my-pi/pi-ai/dialect/demotion";
import { isFactoryDroidGeminiWire, keepsFactoryGeminiReasoning } from "@oh-my-pi/pi-ai/providers/factory-droid/gemini";
import { ollamaChatDropsOwnThinking } from "@oh-my-pi/pi-ai/providers/ollama";
import { completionsDropsOwnThinking, isLiteLLMThinkingSignature } from "@oh-my-pi/pi-ai/providers/openai-completions";
import {
	getNativeResponsesHistoryItems,
	getReplayableNativeResponsesHistoryItems,
	replaysNativeResponsesTurn,
} from "@oh-my-pi/pi-ai/providers/openai-shared";
import {
	dropsForeignReasoningPayload,
	isSameModelTurn,
	shouldDropTruncatedThinkingOnlyAssistant,
} from "@oh-my-pi/pi-ai/providers/transform-messages";
import { resolveThinkingReplayTokens, type ThinkingReplayTokens } from "@oh-my-pi/pi-catalog/compat/thinking-replay";
import type { ModelTokenizer } from "@oh-my-pi/pi-catalog/types";
import * as natives from "@oh-my-pi/pi-natives";
import { materializeString, stringifyJson } from "@oh-my-pi/pi-utils";
import { LRUCache } from "@oh-my-pi/pi-utils/lru";
import * as snapcompact from "@oh-my-pi/snapcompact";
import { isEstimateCacheable, messageEstimateVersion } from "./compaction/message-cache";
import { base64ImageSize, estimateImageTokens, type ImageDetail, type ImageSize } from "./image-tokens";
import type { AgentMessage } from "./types";

const testEnv = Bun.env.NODE_ENV === "test";

const NATIVE_ENCODING: Record<ModelTokenizer, natives.Encoding> = {
	"claude-v3": natives.Encoding.ClaudeV3,
	"claude-v47": natives.Encoding.ClaudeV47,
	"claude-v5": natives.Encoding.ClaudeV5,
	"claude-v5-sonnet": natives.Encoding.ClaudeV5Sonnet,
	qwen3: natives.Encoding.Qwen3,
	"deepseek-v3": natives.Encoding.DeepSeekV3,
	"kimi-k2": natives.Encoding.KimiK2,
	glm5: natives.Encoding.Glm5,
	cl100k: natives.Encoding.Cl100kBase,
	o200k: natives.Encoding.O200kBase,
};

/** Maps the catalog-resolved tokenizer family to its native implementation. */
export function tokenizerEncodingForModel(model: Pick<Model, "tokenizer"> | null | undefined): natives.Encoding | null {
	return model?.tokenizer ? NATIVE_ENCODING[model.tokenizer] : null;
}

type TokenizerModel = Pick<Model, "tokenizer"> &
	snapcompact.ShapeTarget & {
		compat?: Model["compat"];
		thinking?: Model["thinking"];
		reasoning?: boolean;
		requestModelId?: string;
	};

/** The api/provider/model a {@link Tokenizer} counts for. */
interface ModelIdentity {
	api: Api;
	provider: string;
	id: string;
}

function modelIdentity(model: TokenizerModel | null | undefined): ModelIdentity | undefined {
	if (!model?.api || !model.provider || !model.id) return undefined;
	return { api: model.api, provider: model.provider, id: model.id };
}

/**
 * Whether the reader's resolved compat strips native `type: "reasoning"` items
 * from replayed Responses history (`Model.compat.filterReasoningHistory`, a
 * resolved boolean the request builders read too).
 */
function filtersReasoningHistory(model: TokenizerModel | null | undefined): boolean {
	const compat = model?.compat;
	return compat !== undefined && "filterReasoningHistory" in compat && compat.filterReasoningHistory === true;
}

/** Which of a filtered reader's turns its encoder rebuilds thinking items for; `null` for none. */
type RebuiltThinkingTurns = "all-turns" | "tool-calls";

/**
 * Whether the reader's Responses encoder rebuilds a filtered turn's own thinking
 * into a synthetic reasoning item. `filterReasoningHistory` drops the native
 * item, but the `requiresReasoningContent*` safety net puts the turn's thinking
 * text back on the wire as the rebuilt item's `reasoning_text` — unless the
 * target rejects synthetic items (`allowsSyntheticReasoningContentForToolCalls`),
 * in which case reconstruction is off and the text is dropped with the item.
 * Mirrors `buildParams`' `canReconstructReasoningReplay` and
 * `convertResponsesAssistantMessage`' `carriedReasoningTexts`.
 */
function rebuiltThinkingTurns(model: TokenizerModel | null | undefined): RebuiltThinkingTurns | null {
	const compat = model?.compat;
	// `buildParams` gates both reconstructions on a requested reasoning effort,
	// which a per-message count cannot see; a model that cannot reason never
	// reconstructs, and one that can counts the text it may send.
	if (model?.reasoning !== true || !filtersReasoningHistory(model) || compat === undefined) return null;
	if (
		!("allowsSyntheticReasoningContentForToolCalls" in compat) ||
		compat.allowsSyntheticReasoningContentForToolCalls !== true
	) {
		return null;
	}
	if (
		"requiresReasoningContentForAllAssistantTurns" in compat &&
		compat.requiresReasoningContentForAllAssistantTurns === true
	) {
		return "all-turns";
	}
	if ("requiresReasoningContentForToolCalls" in compat && compat.requiresReasoningContentForToolCalls === true) {
		return "tool-calls";
	}
	return null;
}

/** The model an assistant turn's native reasoning (signed thinking, Responses history) is replayed to. */
function reasoningReplayReader(model: TokenizerModel | null | undefined): ModelIdentity | undefined {
	// Filtering targets strip native reasoning items before the request is encoded.
	return filtersReasoningHistory(model) ? undefined : modelIdentity(model);
}

/** Whether this reader keeps another Claude model's signature from the same deployment. */
function readsDeploymentSignatures(model: TokenizerModel | null | undefined): boolean {
	const compat = model?.compat;
	return (
		model?.api === "anthropic-messages" &&
		((compat !== undefined && "officialEndpoint" in compat && compat.officialEndpoint) ||
			model.thinking?.prefixBinding === true)
	);
}

/** Identity of the reader whose replayed reasoning a {@link Tokenizer} counts; equal keys count it alike. */
export function reasoningReplayKey(model: TokenizerModel | null | undefined): string {
	const reader = reasoningReplayReader(model);
	return reader ? `${reader.api}\0${reader.provider}\0${reader.id}` : "";
}

/** Request state a {@link Tokenizer} counts for, beyond its model. */
export interface TokenizerOptions {
	/**
	 * Whether the request replays native Responses history (pi-ai's
	 * `openAIResponsesReplaysNativeHistory`). A cold session rebuilds a turn
	 * holding encrypted reasoning from its text and tool calls, without the
	 * reasoning or its signature. Default: true.
	 */
	nativeHistoryReplay?: boolean;
}

/**
 * Every mode counts with the native tokenizer: the catalog-resolved family
 * when known, o200k_base otherwise. They differ only in the fallback when the
 * loaded addon does not recognize that encoding: `strict` and `upperbound`
 * the raw byte length (never undercounts), `approximate` a bytes/4 guess.
 * Tests (`NODE_ENV=test`) skip the native count outside `strict` and use that
 * fallback.
 */
export type TokenCountMode = "strict" | "approximate" | "upperbound";

/** Options for {@link Tokenizer.countMessage} / {@link Tokenizer.countMessages}. */
export interface MessageCountOptions {
	/**
	 * Drop opaque provider reasoning payloads (`thinkingSignature`,
	 * `redactedThinking`, native server-tool blocks) from the estimate. Those
	 * are billed by the provider on replay, so the default counts them (a reader
	 * billing replayed thinking at `output` size: the reasoning, at its turn's
	 * output size) — but their *local* byte size can diverge wildly from what
	 * the provider charges, so the compaction floor (which only needs the
	 * reliably-countable, on-wire-compressible content) excludes them to avoid
	 * false triggers on thinking-heavy turns.
	 * Native Responses reasoning that actually replays is not an opaque byte
	 * guess: it is charged at the turn's provider-reported reasoning tokens in
	 * both arms.
	 */
	excludeEncryptedReasoning?: boolean;
}

function byteEstimate(text: string): number {
	return (Buffer.byteLength(text, "utf-8") + 3) >> 2;
}

function byteLength(text: string): number {
	return Buffer.byteLength(text, "utf-8");
}

function sumFragments(text: string | string[], perFragment: (t: string) => number): number {
	return Array.isArray(text) ? text.reduce((sum, t) => sum + perFragment(t), 0) : perFragment(text);
}

interface NativeTokenCount {
	tokens: number;
	exact: boolean;
}

// Growing streamed text and large tool results must not evict the reusable
// short fragments. Account for UTF-16 key storage plus a per-entry allowance.
const NATIVE_CACHE_MAX_LENGTH = 16 * 1024;

function countNativeFragment(
	text: string,
	encoding: natives.Encoding | null | undefined,
	counts: LRUCache<string, number>,
): number {
	if (text.length > NATIVE_CACHE_MAX_LENGTH) return natives.countTokens(text, encoding);
	const cached = counts.get(text);
	if (cached !== undefined) return cached;
	const tokens = natives.countTokens(text, encoding);
	// Detach sliced strings so a small key cannot retain a much larger source.
	counts.set(materializeString(text), tokens);
	return tokens;
}

function countTokensNat(
	text: string | string[],
	encoding: natives.Encoding | null | undefined,
	mode: TokenCountMode,
	counts: LRUCache<string, number>,
): NativeTokenCount {
	try {
		let tokens: number;
		if (typeof text === "string") {
			tokens = countNativeFragment(text, encoding, counts);
		} else if (text.length > 0 && text.length < 16) {
			// The native API sums independent fragments, not their concatenation.
			// Keep its parallel batch path for arrays of 16 or more fragments.
			tokens = 0;
			for (const fragment of text) tokens += countNativeFragment(fragment, encoding, counts);
		} else {
			tokens = natives.countTokens(text, encoding);
		}
		return { tokens, exact: true };
	} catch (error) {
		if (
			!(error instanceof Error) ||
			(!error.message.includes("does not match any variant of enum") &&
				!error.message.includes("unknown enum variant"))
		) {
			throw error;
		}
		const tokens = sumFragments(text, mode === "approximate" ? byteEstimate : byteLength);
		return { tokens, exact: false };
	}
}

/** Verdict from {@link Tokenizer.checkTokenBudget}. */
export interface TokenBudgetCheck {
	/** Whether the text fits the budget. */
	fits: boolean;
	/**
	 * Token count behind the verdict: the exact native count when `exact` is
	 * set, otherwise the conservative byte upper bound.
	 */
	tokens: number;
	/** Whether `tokens` came from the exact native tokenizer. */
	exact: boolean;
}

/**
 * Memoized estimates for one message under this tokenizer's encoding, split by
 * the {@link MessageCountOptions.excludeEncryptedReasoning} option so the two
 * variants never collide. `version` snapshots {@link messageEstimateVersion} at
 * write time; an owner mutation (prune/shake/strip-images) bumps the version,
 * which invalidates the entry in every live Tokenizer at once.
 */
interface MessageEstimate {
	version: number;
	default?: number;
	floored?: number;
}

/**
 * Model-aware local token counter. Immutable: the catalog-resolved encoding
 * is fixed at construction, so a cached count can never straddle two
 * encodings. An `Agent` owns one for its active model (swapping the instance
 * when the model's encoding, image or thinking-replay pricing, replay
 * identity or native-history replay state changes); one-shot flows construct
 * their own for the model that will be billed. Known tokenizer families use
 * exact native counts; other models are counted in o200k_base, which bills
 * unknown readers closer than a bytes/4 guess.
 */
export class Tokenizer {
	readonly #encoding: natives.Encoding | null;
	readonly #frameBilling: snapcompact.FrameBilling;
	readonly frameBillingKey: string;
	readonly #reasoningReader: ModelIdentity | undefined;
	/** The counted model's identity, set even when filtering leaves no reasoning reader. */
	readonly #model: ModelIdentity | undefined;
	/** Whether the reader strips native reasoning items out of its Responses requests. */
	readonly #filtersReasoningHistory: boolean;
	/** Which turns the reader's encoder rebuilds a stripped reasoning item for, carrying the thinking text. */
	readonly #rebuiltThinkingTurns: RebuiltThinkingTurns | null;
	readonly #dropsOllamaThinking: boolean;
	readonly #dropsCompletionsThinking: boolean;
	/** Claude's own API and prefix-bound hosts keep another model's signature from their deployment. */
	readonly #readsDeploymentSignatures: boolean;
	/** Factory's Gemini generate wire, whose replay pass keeps only Google-origin reasoning. */
	readonly #factoryGeminiWire: boolean;
	readonly reasoningReplayKey: string;
	/** How the reader bills replayed signed thinking (catalog `thinking-replay-tokens`). */
	readonly thinkingReplayTokens: ThinkingReplayTokens;
	/** Whether the counted request replays native Responses history; see {@link TokenizerOptions}. */
	readonly nativeHistoryReplay: boolean;

	/** Exact counts only; byte fallbacks remain mode-dependent and uncached. */
	readonly #nativeCounts = new LRUCache<string, number>({
		max: 256,
		maxSize: 512 * 1024,
		sizeCalculation: (_tokens, text) => text.length * 2 + 64,
	});

	/**
	 * Per-message estimate memo. Keyed by message identity, deliberately not a
	 * symbol-tagged property: callers spread messages to derive throwaway
	 * variants for counting (`estimateBranchSummaryTokens` does
	 * `countMessage({ ...message, content: truncated })`), and a property-borne
	 * cache would ride along the spread. Identity keying gives clones a fresh
	 * count.
	 */
	#estimates = new WeakMap<AgentMessage, MessageEstimate>();

	/**
	 * Counts what `streamSimple` sends `model`. Its catalog compat decides
	 * whether Responses reasoning history is filtered: `streamOpenAIResponses`'
	 * per-request `filterReasoningHistory` override is a debugging hook
	 * `streamSimple` never forwards, so a caller using it passes `model` with
	 * that compat set.
	 */
	constructor(model?: TokenizerModel | null, options?: TokenizerOptions) {
		this.#encoding = tokenizerEncodingForModel(model);
		this.#frameBilling = snapcompact.frameBilling(model ?? undefined);
		this.frameBillingKey = snapcompact.frameBillingKey(this.#frameBilling);
		this.#reasoningReader = reasoningReplayReader(model);
		this.#model = modelIdentity(model);
		this.#filtersReasoningHistory = filtersReasoningHistory(model);
		this.#rebuiltThinkingTurns = rebuiltThinkingTurns(model);
		this.#dropsOllamaThinking = ollamaChatDropsOwnThinking(model);
		this.#dropsCompletionsThinking = completionsDropsOwnThinking(model);
		this.#readsDeploymentSignatures = readsDeploymentSignatures(model);
		this.#factoryGeminiWire =
			model?.api === "factory-droid-agent" &&
			model.id !== undefined &&
			isFactoryDroidGeminiWire({ id: model.id, requestModelId: model.requestModelId });
		this.reasoningReplayKey = reasoningReplayKey(model);
		this.thinkingReplayTokens = resolveThinkingReplayTokens(model ?? {});
		this.nativeHistoryReplay = options?.nativeHistoryReplay ?? true;
	}

	get encoding(): natives.Encoding | null {
		return this.#encoding;
	}

	countTokens(text: string | string[], mode: TokenCountMode = "approximate"): number {
		if (testEnv && mode !== "strict") return sumFragments(text, mode === "upperbound" ? byteLength : byteEstimate);
		return countTokensNat(text, this.#encoding, mode, this.#nativeCounts).tokens;
	}

	/**
	 * Cheap-first budget probe — the way to ask "does this fit in `budget`
	 * tokens?" without tokenizing the world.
	 *
	 * Byte length is a hard upper bound on token count (every token consumes at
	 * least one input byte), so text whose raw bytes already fit the budget
	 * cannot possibly exceed it — that verdict is returned without tokenizing at
	 * all. Only text that busts the bound is ambiguous, and only that case pays
	 * for the exact count. Since the bound overshoots ~4x on ordinary prose, the
	 * common "comfortably under budget" answer is free.
	 */
	checkTokenBudget(text: string | string[], budget: number): TokenBudgetCheck {
		const bound = sumFragments(text, byteLength);
		if (bound <= budget) return { fits: true, tokens: bound, exact: false };
		const result = countTokensNat(text, this.#encoding, "strict", this.#nativeCounts);
		return { fits: result.tokens <= budget, tokens: result.tokens, exact: result.exact };
	}

	/**
	 * Token estimate for one message under this tokenizer's encoding.
	 *
	 * Settled historical messages are counted once and reused until an owner
	 * (prune/shake/strip-images) calls `invalidateMessageCache`; streaming
	 * assistants bypass the memo entirely (see the message-cache settle-gate
	 * invariant). Image blocks charge {@link imageTokens}, the same estimate
	 * the native remote-compaction probe applies.
	 */
	countMessage(message: AgentMessage, options?: MessageCountOptions): number {
		const floored = options?.excludeEncryptedReasoning === true;
		if (!isEstimateCacheable(message)) return this.#measureMessage(message, floored, false);
		const version = messageEstimateVersion(message);
		let entry = this.#estimates.get(message);
		if (entry === undefined || entry.version !== version) {
			entry = { version };
			this.#estimates.set(message, entry);
		}
		const cached = floored ? entry.floored : entry.default;
		if (cached !== undefined) return cached;
		const result = this.#measureMessage(message, floored, false);
		if (floored) entry.floored = result;
		else entry.default = result;
		return result;
	}

	/**
	 * {@link countMessage} for the transcript's latest surviving assistant turn
	 * (`isSurvivingAssistant`), which an Anthropic Messages replay keeps
	 * byte-for-byte (`transformMessages`): a turn whose tool calls ended without
	 * a tool-use stop keeps its signatures then, so its reasoning is charged. A
	 * count of one message cannot see its position; a caller walking back from
	 * the end of the transcript counts that turn here. Not memoized: it differs
	 * from {@link countMessage} only for that one turn.
	 */
	countLatestTurn(message: AgentMessage, options?: MessageCountOptions): number {
		return this.#measureMessage(message, options?.excludeEncryptedReasoning === true, true);
	}

	/** Sum of {@link countMessage} over `messages`. */
	countMessages(messages: readonly AgentMessage[], options?: MessageCountOptions): number {
		let total = 0;
		for (const message of messages) total += this.countMessage(message, options);
		return total;
	}

	/**
	 * Input tokens for one image (not a snapcompact frame) under the reader's
	 * catalog image rule, or the generic estimate when it has none.
	 */
	imageTokens(size: ImageSize | null | undefined, detail?: ImageDetail): number {
		return estimateImageTokens(size, detail, this.#frameBilling.rule);
	}

	/**
	 * Whether `message`'s signed reasoning reaches this reader natively: from
	 * the same model, host and wire, or from another Claude model on the same
	 * Anthropic deployment, which keeps the signature (`transformMessages`).
	 * Claude bills that reasoning when the reader can read it and drops the
	 * block otherwise, so such a turn counts high rather than low.
	 */
	#replaysReasoningNatively(message: AssistantMessage): boolean {
		const reader = this.#reasoningReader;
		return (
			reader !== undefined &&
			message.api === reader.api &&
			message.provider === reader.provider &&
			(message.model === reader.id || this.#readsDeploymentSignatures)
		);
	}

	/**
	 * Whether `message`'s opaque reasoning payload (thinking signatures, redacted
	 * thinking) may reach this reader: everything except what `transformMessages`
	 * certainly strips from another model's turn, or what Factory's Gemini wire
	 * drops from a turn not of Google origin. Without a replay reader (no
	 * model, or a `filterReasoningHistory` target) every payload is charged,
	 * which overcounts a filtering reader's foreign turns.
	 */
	#receivesReasoningPayload(message: AssistantMessage): boolean {
		const reader = this.#reasoningReader;
		if (reader === undefined) return true;
		if (this.#factoryGeminiWire) return keepsFactoryGeminiReasoning(message);
		return !dropsForeignReasoningPayload(message, reader);
	}

	/**
	 * The replayed native Responses reasoning {@link countMessage} charges
	 * across `messages`: the part of a count that changes with the reading
	 * model. A replay whose backend reported no reasoning tokens counts at the
	 * signature price `countMessage` gives it.
	 */
	replayedReasoningTokens(messages: readonly AgentMessage[]): number {
		let total = 0;
		for (const message of messages) {
			if (message.role !== "assistant") continue;
			const replayed = this.#replayedReasoningTokens(message);
			total +=
				replayed === null
					? this.countMessage(message) - this.countMessage(message, { excludeEncryptedReasoning: true })
					: (replayed ?? 0);
		}
		return total;
	}

	#measureMessage(message: AgentMessage, excludeEncryptedReasoning: boolean, latestTurn: boolean): number {
		const fragments: string[] = [];
		let extra = 0;
		// Declaration-merged app roles (the coding-agent's bashExecution) are
		// invisible to this package's union, so the discriminant is read as data.
		const role: string = message.role;
		if (role === "bashExecution") {
			if ("command" in message && typeof message.command === "string") fragments.push(message.command);
			if ("output" in message && typeof message.output === "string") fragments.push(message.output);
			return fragments.length === 0 ? 0 : this.countTokens(fragments);
		}

		switch (message.role) {
			case "user":
			case "developer": {
				// Both roles carry `string | (TextContent | ImageContent)[]` and both are
				// sent to the provider -- convertMessageToLlm handles developer alongside
				// user -- so they are counted alike. Without the developer case the switch
				// fell through to `default: return 0`, and the old annotation narrowed the
				// blocks to text-only, hiding the image charge the toolResult arm applies.
				const content = message.content;
				if (typeof content === "string") {
					fragments.push(content);
				} else if (Array.isArray(content)) {
					for (const block of content) {
						if (block.type === "text" && block.text) {
							fragments.push(block.text);
						} else if (block.type === "image") {
							extra += this.imageTokens(base64ImageSize(block.data), block.detail);
						}
					}
				}
				break;
			}
			case "assistant": {
				// Replayed native Responses reasoning is billed as input at the turn's
				// reported reasoning tokens, not at its ~3x larger ciphertext size, so it
				// is a token price and counts in both arms. Its thinking signature never
				// reaches the wire then (the payload items replay instead); a turn whose
				// backend reported no reasoning tokens keeps the signature as its price.
				const replayedReasoning = this.#replayedReasoningTokens(message);
				const ollamaReader = this.#reasoningReader?.api === "ollama-chat" ? this.#reasoningReader : undefined;
				const ownOllamaTurn = ollamaReader !== undefined && isSameModelTurn(message, ollamaReader);
				const completionsReader = this.#dropsCompletionsThinking ? this.#reasoningReader : undefined;
				const ownDroppedCompletionsTurn =
					completionsReader !== undefined && isSameModelTurn(message, completionsReader);
				if (typeof replayedReasoning === "number") extra += replayedReasoning;
				const signaturesPriced = this.thinkingReplayTokens === "signature";
				// The replay's signature rule (`transformMessages`): an aborted or
				// errored turn's final block can hold a partial signature, and a turn
				// whose tool calls ended without a tool-use stop is abandoned, so all
				// its signatures are stripped. Every other block completed. On the
				// Anthropic Messages API the latest assistant turn keeps an abandoned
				// turn's signatures byte-for-byte (Bedrock's Converse replay strips
				// them too); a per-message count cannot see position, so it follows
				// the rule for older turns unless the caller says it is the latest
				// (`countLatestTurn`).
				const content = message.content;
				const invalidStop = message.stopReason === "aborted" || message.stopReason === "error";
				const keepsLatestSignatures = latestTurn && message.api === "anthropic-messages";
				const abandonedToolUse =
					!keepsLatestSignatures &&
					!invalidStop &&
					message.stopReason !== "toolUse" &&
					content.some(block => block.type === "toolCall");
				const untrustedIndex = invalidStop ? content.length - 1 : -1;
				// A filtering Responses reader replays no reasoning item and its encoder
				// drops the turn's own thinking blocks, so usually neither their text nor
				// their signature reaches the wire (the reconstruction below is the one
				// exception). Another model's thinking has no native slot there either;
				// the transform demotes it to visible text, which is sent.
				const ownThinkingFiltered =
					this.#filtersReasoningHistory && this.#model !== undefined && isSameModelTurn(message, this.#model);
				// A filtering reader drops the turn's own reasoning item, but its
				// encoder rebuilds one — carrying this turn's thinking text — for
				// targets that require reasoning content and accept a synthetic item.
				// The item is only attached to a turn that emits another item.
				const ownThinkingRebuilt =
					ownThinkingFiltered &&
					this.#rebuiltThinkingTurns !== null &&
					message.stopReason !== "error" &&
					(this.#rebuiltThinkingTurns === "all-turns" || content.some(block => block.type === "toolCall")) &&
					content.some(block => block.type === "text" || block.type === "toolCall");
				let signedReasoning = false;
				for (let index = 0; index < content.length; index++) {
					const block = content[index];
					if (block.type === "text") {
						fragments.push(block.text);
					} else if (block.type === "thinking") {
						if (ownThinkingFiltered) {
							// The rebuilt item carries the thinking text verbatim; the
							// signature stays off the wire either way.
							if (ownThinkingRebuilt) fragments.push(block.thinking);
							continue;
						}
						// `transformMessages` drops another model's empty thinking and demotes the
						// rest to visible text; only the reader's own thinking stays native.
						if (ollamaReader && !ownOllamaTurn) {
							if (block.thinking.trim()) fragments.push(renderDemotedThinking(ollamaReader.id, block.thinking));
							continue;
						}
						if (this.#dropsOllamaThinking && ownOllamaTurn) continue;
						// Chat-completions drops it unless LiteLLM replays it in `thinking_blocks`.
						if (ownDroppedCompletionsTurn && !isLiteLLMThinkingSignature(block.thinkingSignature)) continue;
						if (this.#filtersReasoningHistory && this.#model !== undefined) {
							// The demoted rendering is the visible text the request carries.
							if (block.thinking.trim()) fragments.push(renderDemotedThinking(this.#model.id, block.thinking));
							continue;
						}
						fragments.push(block.thinking);
						// Providers charge for the opaque signature/reasoning payload that
						// rides alongside the thinking text (OpenAI Responses encrypted
						// reasoning items, Gemini thought signatures) wherever it survives
						// replay; `transformMessages` strips another model's on most wires.
						// A reader billing at `output` size (Claude) charges the reasoning,
						// priced below, not these bytes. The compaction floor excludes it
						// (its local byte size diverges from provider billing).
						if (
							block.thinkingSignature &&
							!excludeEncryptedReasoning &&
							signaturesPriced &&
							typeof replayedReasoning !== "number" &&
							this.#receivesReasoningPayload(message)
						) {
							fragments.push(block.thinkingSignature);
						}
						if (block.thinkingSignature && !abandonedToolUse && index !== untrustedIndex) signedReasoning = true;
					} else if (block.type === "toolCall") {
						fragments.push(block.name);
						fragments.push(stringifyJson(block.arguments) ?? "null");
					} else if (block.type === "redactedThinking") {
						// Encrypted reasoning blob the provider still bills for wherever it
						// survives replay, as above; excluded from the compaction floor for
						// the same reason.
						signedReasoning = true;
						if (!excludeEncryptedReasoning && signaturesPriced && this.#receivesReasoningPayload(message)) {
							fragments.push(block.data);
						}
					} else if (block.type === "anthropicServerTool") {
						// Native Anthropic server-tool call/result replayed verbatim on the
						// wire (server_tool_use input and opaque result content). The provider
						// still bills for it on same-provider replay; excluded from the
						// compaction floor like other encrypted reasoning because its local
						// byte size diverges from provider billing.
						if (!excludeEncryptedReasoning) fragments.push(stringifyJson(block.block) ?? "null");
					}
				}
				// The visible text undercounts a native replay: the provider rebuilds
				// the full reasoning from its signature, billed at the turn's output
				// size less the visible text shake has since elided from it. The
				// floor keeps the visible count.
				if (
					signedReasoning &&
					!excludeEncryptedReasoning &&
					!signaturesPriced &&
					this.#replaysReasoningNatively(message)
				) {
					const visible = fragments.length === 0 ? extra : extra + this.countTokens(fragments);
					return Math.max(visible, message.usage.output - (message.elidedOutputTokens ?? 0));
				}
				break;
			}
			case "custom":
			case "hookMessage":
			case "toolResult": {
				if (typeof message.content === "string") {
					fragments.push(message.content);
				} else {
					for (const block of message.content) {
						if (block.type === "text" && block.text) {
							fragments.push(block.text);
						} else if (block.type === "image") {
							extra += this.imageTokens(base64ImageSize(block.data), block.detail);
						}
					}
				}
				break;
			}
			case "branchSummary":
			case "compactionSummary": {
				fragments.push(message.summary);
				if (message.role === "compactionSummary") {
					if (message.blocks) {
						for (const block of message.blocks) {
							if (block.type === "text") fragments.push(block.text);
							else extra += this.#frameTokens(block.data);
						}
					} else if (message.images) {
						for (const image of message.images) {
							extra += this.#frameTokens(image.data);
						}
					}
				}
				break;
			}
			default:
				return 0;
		}

		if (fragments.length === 0) return extra;
		return extra + this.countTokens(fragments);
	}

	/**
	 * Input tokens this reader bills for replaying `message`'s native Responses
	 * reasoning; `undefined` when the reader re-encodes the turn from its
	 * blocks instead, `null` when it replays but the backend reported no
	 * reasoning tokens to price it by. The payload goes back on the wire only
	 * to the api, model and provider that produced it (`convertMessages` in
	 * pi-ai's Responses providers), and then only what survives replay: a
	 * truncated thinking-only turn is dropped, a hidden-empty or reasoning-only
	 * payload sanitizes to nothing, and a cold session rebuilds the turn without
	 * its reasoning, so those send no reasoning and no signature (0).
	 */
	#replayedReasoningTokens(message: AssistantMessage): number | null | undefined {
		// A payload this reader does not own is not native history at all: the turn
		// is rebuilt from its blocks, and its signatures are priced below.
		if (!getNativeResponsesHistoryItems(message, this.#reasoningReader)) return undefined;
		// The request decides whether the payload goes on the wire; `/shake` reads
		// that same decision, so a kept turn and a billed turn always agree.
		const replay = getReplayableNativeResponsesHistoryItems(message, this.#reasoningReader);
		if (!replay || !replaysNativeResponsesTurn(replay, this.nativeHistoryReplay)) return 0;
		// Then the amount: nothing reasoning-shaped survives to price, or the turn is
		// dropped whole as truncated thinking, so it sends no reasoning and no
		// signature either. An answer-only payload replays with neither.
		if (!replay.some(item => item.type === "reasoning") || shouldDropTruncatedThinkingOnlyAssistant(message)) {
			return 0;
		}
		return message.usage?.reasoningTokens ?? null;
	}

	/** Whether a Tokenizer built for `model` with `options` would count every message as this one does. */
	countsAlike(model: TokenizerModel | null | undefined, options?: TokenizerOptions): boolean {
		return (
			tokenizerEncodingForModel(model) === this.#encoding &&
			snapcompact.frameBillingKey(snapcompact.frameBilling(model ?? undefined)) === this.frameBillingKey &&
			reasoningReplayKey(model) === this.reasoningReplayKey &&
			readsDeploymentSignatures(model) === this.#readsDeploymentSignatures &&
			filtersReasoningHistory(model) === this.#filtersReasoningHistory &&
			rebuiltThinkingTurns(model) === this.#rebuiltThinkingTurns &&
			resolveThinkingReplayTokens(model ?? {}) === this.thinkingReplayTokens &&
			ollamaChatDropsOwnThinking(model) === this.#dropsOllamaThinking &&
			completionsDropsOwnThinking(model) === this.#dropsCompletionsThinking &&
			(options?.nativeHistoryReplay ?? true) === this.nativeHistoryReplay
		);
	}

	/** One snapcompact frame at the active model's price for its pixel size; unreadable frames cost the ceiling. */
	#frameTokens(data: string): number {
		const size = base64ImageSize(data);
		return size ? snapcompact.frameTokens(this.#frameBilling, size) : snapcompact.FRAME_TOKEN_ESTIMATE;
	}
}

