describe("applyPricingPeerFallback", () => {
	it("prices Gemini ids at Google API peers and Claude ids at Vertex, falling back to Anthropic", () => {
		const googleCost = { input: 1.5, output: 9, cacheRead: 0.15, cacheWrite: 0 };
		const previewCost = { input: 2, output: 12, cacheRead: 0.2, cacheWrite: 0 };
		const vertexCost = { input: 6, output: 30, cacheRead: 0.6, cacheWrite: 7.5 };
		const anthropicCost = { input: 5, output: 25, cacheRead: 0.5, cacheWrite: 6.25 };
		const models: ModelSpec<Api>[] = [
			createSpec({ id: "gemini-3.5-flash", api: "google-generative-ai", provider: "google", cost: googleCost }),
			createSpec({
				id: "gemini-3.1-pro-preview",
				api: "google-generative-ai",
				provider: "google",
				cost: previewCost,
			}),
			createSpec({
				id: "claude-opus-4-6@default",
				api: "anthropic-messages",
				provider: "google-vertex",
				cost: vertexCost,
			}),
			createSpec({ id: "claude-opus-4-6", api: "anthropic-messages", provider: "anthropic", cost: anthropicCost }),
			createSpec({ id: "claude-sonnet-4-6", api: "anthropic-messages", provider: "anthropic", cost: anthropicCost }),
			createSpec({ id: "gemini-3.5-flash", api: "google-gemini-cli", provider: "google-antigravity" }),
			createSpec({ id: "gemini-3.1-pro", api: "google-gemini-cli", provider: "google-antigravity" }),
			createSpec({ id: "claude-opus-4-6", api: "google-gemini-cli", provider: "google-antigravity" }),
			createSpec({ id: "claude-sonnet-4-6", api: "google-gemini-cli", provider: "google-antigravity" }),
		];

		const result = applyPricingPeerFallback(models);

		expect(result[5]?.cost).toEqual(googleCost);
		expect(result[6]?.cost).toEqual(previewCost);
		// Vertex list price wins over Anthropic for aliased Claude ids.
		expect(result[7]?.cost).toEqual(vertexCost);
		// Dangling Vertex alias (no google-vertex row) falls back to Anthropic.
		expect(result[8]?.cost).toEqual(anthropicCost);
	});

	it("keeps zero cost for ids without a priced peer and never overwrites billable antigravity cost", () => {
		const zeroCost = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 };
		const pricedCost = { input: 0.5, output: 3, cacheRead: 0.05, cacheWrite: 0 };
		const models: ModelSpec<Api>[] = [
			createSpec({ id: "gemini-3-flash-preview", api: "google-generative-ai", provider: "google", cost: zeroCost }),
			createSpec({ id: "tab_flash_lite_preview", api: "google-gemini-cli", provider: "google-antigravity" }),
			createSpec({ id: "gemini-3-flash", api: "google-gemini-cli", provider: "google-antigravity" }),
			createSpec({
				id: "gemini-3.6-flash",
				api: "google-gemini-cli",
				provider: "google-antigravity",
				cost: pricedCost,
			}),
			createSpec({
				id: "gemini-3.6-flash",
				api: "google-generative-ai",
				provider: "google",
				cost: { input: 9, output: 9, cacheRead: 9, cacheWrite: 9 },
			}),
		];

		const result = applyPricingPeerFallback(models);

		// No billable google peer (zero-cost peer is not a pricing source).
		expect(result[1]?.cost).toEqual(zeroCost);
		expect(result[2]?.cost).toEqual(zeroCost);
		// Already-billable antigravity rows keep their own pricing.
		expect(result[3]?.cost).toEqual(pricedCost);
	});

	it("prices MiniMax Token Plan rows at pay-as-you-go peers", () => {
		const m3Cost = { input: 0.3, output: 1.2, cacheRead: 0.06, cacheWrite: 0 };
		const m27Cost = { input: 0.3, output: 1.2, cacheRead: 0.06, cacheWrite: 0.375 };
		const flashCost = { input: 0.15, output: 0.6, cacheRead: 0.015, cacheWrite: 0 };
		const zeroCost = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 };
		const models: ModelSpec<Api>[] = [
			createSpec({ id: "MiniMax-M3", api: "anthropic-messages", provider: "minimax", cost: m3Cost }),
			createSpec({ id: "MiniMax-M2.7", api: "anthropic-messages", provider: "minimax", cost: m27Cost }),
			createSpec({ id: "MiniMax-M3.1-Flash", api: "anthropic-messages", provider: "minimax", cost: flashCost }),
			createSpec({ id: "MiniMax-M3.1-Flash", api: "anthropic-messages", provider: "minimax-code" }),
			createSpec({ id: "MiniMax-M2.7", api: "anthropic-messages", provider: "minimax-code" }),
			createSpec({ id: "MiniMax-M2.1-lightning", api: "anthropic-messages", provider: "minimax-code" }),
			// No minimax-cn row: the China plan falls back to the international peer.
			createSpec({ id: "MiniMax-M3.1-Flash", api: "anthropic-messages", provider: "minimax-code-cn" }),
		];

		const result = applyPricingPeerFallback(models);

		expect(result[3]?.cost).toEqual(flashCost);
		expect(result[4]?.cost).toEqual(m27Cost);
		expect(result[5]?.cost).toEqual(zeroCost);
		expect(result[6]?.cost).toEqual(flashCost);
	});
});

import type { ImageContent } from "@oh-my-pi/pi-ai";
import type { PipeStreams } from "@oh-my-pi/pi-natives";
import { isRecord, logger, untilAborted } from "@oh-my-pi/pi-utils";
import type { StructuredSubagentOutput } from "@oh-my-pi/pi-tui/tools/task";
import type { OutputMeta } from "@oh-my-pi/pi-tui/tools/output-meta";
import { IrcBus } from "../irc/bus";
import type { JobWidgetInputs, JobWidgetRegistry } from "../job-widgets/types";

const DELIVERY_RETRY_BASE_MS = 500;
const DELIVERY_RETRY_MAX_MS = 30_000;
const DELIVERY_RETRY_JITTER_MS = 200;
const DEFAULT_RETENTION_MS = 5 * 60 * 1000;
/**
 * A settled job row whose result was already consumed — auto-delivered to its
 * sink, or recovered by a foreground `wait` snapshot — has
 * served its inspectability purpose: the model holds the result, and later
 * job snapshots listing it for the full retention window is exactly the
 * "background jobs hang around after they complete" complaint. Evict shortly
 * after consumption instead; the short grace still covers a follow-up
 * `agent://<id>` read of the just-delivered pointer. Unconsumed rows
 * (dead-lettered deliveries, still-retrying sinks, watch-suppressed jobs
 * nobody polled) keep the full {@link DEFAULT_RETENTION_MS} window.
 */
const CONSUMED_RESULT_EVICTION_MS = 30_000;
/** Evicted job ids remembered for {@link AsyncJobManager.getEvictedJob}; the oldest go first. */
const EVICTED_JOB_LIMIT = 256;
/**
 * Extra delay after an `async-result` delivery settles (its `ASIDE_MESSAGE_COMMIT`
 * hook fires, resolving `enqueueWithReceipt()`) before retained artifacts are
 * removed. The commit hook fires when the follow-up is inserted into the
 * transcript, not after the model's next provider call has actually read it —
 * this window gives that round trip time to complete before the backing
 * `<id>.md`/`.json` files disappear out from under an advertised `agent://` URL.
 */
const RETAINED_ARTIFACTS_CLEANUP_GRACE_MS = 60_000;
/**
 * Upper bound on how long retained-artifacts cleanup waits for a hung
 * delivery sink before giving up and running cleanup anyway. Without this,
 * a sink that never settles (e.g. a yield-queue receipt whose owning
 * session is gone) would leak the temp directory for the process lifetime
 * (PR #10625 review). Matches {@link DEFAULT_RETENTION_MS}: by the time a
 * job would have been evicted anyway, there is no realistic path left for
 * the model to still read the advertised `agent://` pointer.
 */
const RETAINED_ARTIFACTS_CLEANUP_MAX_WAIT_MS = DEFAULT_RETENTION_MS;
const DEFAULT_MAX_RUNNING_JOBS = 15;
/** Abort reason used only when the owning session shuts down the entire manager. */
export const ASYNC_JOB_MANAGER_SHUTDOWN_REASON = Symbol("AsyncJobManager shutdown");

/** Kind of work a managed job runs; drives job-row badges and delivery labels. */
export type AsyncJobType = "bash" | "task" | "eval";

/** Settled job-body payload: delivery text plus its parsed structured output. */
export interface AsyncJobRunResult {
	text: string;
	structured?: StructuredSubagentOutput;
	/** See {@link AsyncJob.agentOutputPublished}. */
	agentOutputPublished?: boolean;
}

/**
 * Job-body failure that still carries the run's structured output, so a
 * strict-mode schema violation fails the job without dropping the parsed
 * (invalid) payload.
 */
export class AsyncJobError extends Error {
	constructor(
		message: string,
		readonly structured?: StructuredSubagentOutput,
	) {
		super(message);
		this.name = "AsyncJobError";
	}
}

/** Progress metadata retained for renderers and multimodal completion delivery. */
export interface AsyncJobDetails extends Record<string, unknown> {
	/** Images recovered from command output, independent of text truncation. */
	images?: ImageContent[];
	/** Tool output metadata needed when a completion is delivered or recovered later. */
	meta?: OutputMeta;
}

/**
 * Progress record of one task job's agent. A batch `task` call shares one
 * `progress` array across its jobs, so the entry whose `id` is `agentId` wins;
 * a job reporting only its own spawn falls back to the first entry. Used by job
 * snapshots and eval `wait()` progress rows.
 */
export function agentProgress(
	details: AsyncJobDetails | undefined,
	agentId: string,
): Record<string, unknown> | undefined {
	const progress = details?.progress;
	if (!Array.isArray(progress)) return undefined;
	let first: Record<string, unknown> | undefined;
	for (const record of progress) {
		if (!isRecord(record)) continue;
		if (record.id === agentId) return record;
		first ??= record;
	}
	return first;
}

/**
 * What an evicted job's id still answers once its row is gone, so a reader
 * learns where its result went instead of a bare "not found".
 */
export interface EvictedJob {
	id: string;
	type: AsyncJobType;
	label: string;
	ownerId?: string;
	/** Owner-home token identifying the restore batch this row can be delivered to. */
	restoreReceiptId?: string;
	status: AsyncJob["status"];
	/** When the job's run settled. */
	endTime?: number;
	evictedAt: number;
	/** Whether its result reached the owner (pushed, or read by a snapshot) before the row went. */
	delivered: boolean;
	/** `expired`: retention ran out; `cleared`: its owner's session was reset, replaced, or switched. */
	reason: "expired" | "cleared";
}

export interface AsyncJob {
	id: string;
	type: AsyncJobType;
	status: "running" | "completed" | "failed" | "cancelled";
	startTime: number;
	/** When the job's run settled; `endTime - startTime` is its frozen run duration. */
	endTime?: number;
	label: string;
	/**
	 * What the job is for, in the model's words: the `i` intent on the call
	 * that started it, as one line of plain text. Job views lead with it over
	 * the `label`. Only tools whose call starts a single job set it.
	 */
	intent?: string;
	/**
	 * The user's request a `/tan` job carries out, verbatim. The owner never saw
	 * that work, so its completion notice quotes the request and frames the
	 * result as the user's tangent rather than the owner's own job.
	 */
	request?: string;
	abortController: AbortController;
	promise: Promise<void>;
	resultText?: string;
	errorText?: string;
	/**
	 * Parsed structured completion for a job whose work selected an output
	 * schema. Set from the body's {@link AsyncJobRunResult} or from an
	 * {@link AsyncJobError}. The job row is the carrier — every delivery
	 * attempt, redelivery, and `proc://` snapshot reads it from here.
	 */
	structured?: StructuredSubagentOutput;
	/** Latest progress text the running job reported (a bash job's output tail). */
	progressText?: string;
	/** Latest tool-render details reported by the running job. */
	latestDetails?: AsyncJobDetails;
	/**
	 * Registry id of the agent that registered the job (e.g. "Main",
	 * "AuthLoader"). Used by scoped cancel/list APIs so a subagent's teardown
	 * does not cancel its parent's jobs. Undefined for callers that don't
	 * supply an id (e.g. legacy tests, SDK consumers without an agent context).
	 */
	ownerId?: string;
	/** Owner-home token identifying the restore batch this row can be delivered to. */
	restoreReceiptId?: string;
	/**
	 * Registry id of the subagent this job runs (task/tan/vibe jobs). Lets
	 * job-view code link a job row to its AgentRegistry ref even when the job
	 * id differs from the agent id (vibe turn jobs, tan clones).
	 */
	agentId?: string;
	/**
	 * Whether this job's turn published the agent's `<agentId>.md` output. A
	 * follow-up turn that neither yielded nor produced a message result writes
	 * none, so `agent://<agentId>` still holds an earlier turn's output; job
	 * bodies that know this report it so deliveries advertise only the handles
	 * that answer for this turn. Undefined where the body does not report it.
	 */
	agentOutputPublished?: boolean;
	/** The process the job runs, when it spawns one. */
	process?: AsyncJobProcess;
	/** What the job's live widget reads; set by bash and task jobs. */
	widgetInputs?: JobWidgetInputs;
	/**
	 * Job is registered but parked behind a caller-managed gate (e.g. a task
	 * batch semaphore). Queued jobs do not count toward the running-job limit
	 * until the caller invokes `markRunning()` from the run context.
	 */
	queued?: boolean;
	/**
	 * Job backs a foreground tool call that may still auto-background. It is
	 * hidden from job listings and its delivery is suppressed until
	 * {@link AsyncJobManager.backgroundJob} promotes it; a call that finishes in
	 * the foreground hands it to {@link AsyncJobManager.releaseForegroundJob}.
	 */
	foreground?: boolean;
	/**
	 * Disposal closure for a detached spawn's temporary artifacts directory
	 * that `runStructuredSubagent()` retained past completion (so a
	 * delayed `agent://<id>` handle in an `async-result` delivery still
	 * resolves). The manager invokes and clears this exactly once — on
	 * eviction or manager disposal — so the retained directory does not
	 * outlive the job row it was kept alive for.
	 */
	retainedArtifactsCleanup?: () => Promise<void>;
}

/**
 * The process a job runs, for job inspectors (the jobs sheet): set by bodies
 * that spawn one (bash), absent for in-process work (eval, task).
 */
export interface AsyncJobProcess {
	/** Full command line; the job label is cut to 120 characters. */
	readonly command: string;
	/** Directory the command started in. */
	readonly cwd: string;
	/** Live pids the command spawned, in spawn order; empty before it starts and after it ends. */
	pids(): readonly number[];
	/** Copies of the bytes crossing the command's pipes, kept with the job row (`proc://<id>/streams`). */
	readonly streams?: PipeStreams;
}

/** Delivery callback for a settled job's result text. */
export type AsyncJobDeliverySink = (jobId: string, text: string, job?: AsyncJob) => void | Promise<void>;

export interface AsyncJobManagerOptions {
	/**
	 * Delivery sink for UNOWNED completions (jobs registered without an
	 * `ownerId`). Owned deliveries route exclusively through
	 * {@link AsyncJobManager.registerDeliverySink}; when the owner has no live
	 * sink they are dead-lettered (dropped with a warning; the job row keeps
	 * the result text until retention eviction) — never routed here, which
	 * would leak one agent's result into another session.
	 */
	onJobComplete?: AsyncJobDeliverySink;
	/** Running-job cap; a function is re-read on every capacity check so a live setting resizes the cap. */
	maxRunningJobs?: number | (() => number);
	retentionMs?: number;
	/**
	 * Delay after a job's `async-result` delivery settles before its retained
	 * artifacts are removed (see {@link RETAINED_ARTIFACTS_CLEANUP_GRACE_MS}).
	 * Defaults to that constant; tests override to `0` to assert cleanup
	 * without a real-time wait.
	 */
	retainedArtifactsCleanupGraceMs?: number;
	/**
	 * Upper bound on how long retained-artifacts cleanup waits for a job's
	 * delivery to settle before giving up and running cleanup anyway (see
	 * {@link RETAINED_ARTIFACTS_CLEANUP_MAX_WAIT_MS}). Defaults to that
	 * constant; tests override to a small value to assert the bound without
	 * a real-time wait.
	 */
	retainedArtifactsCleanupMaxWaitMs?: number;
	/**
	 * Delay before a settled job row is evicted once its result has been
	 * consumed (delivered to a sink or recovered by a foreground snapshot).
	 * Defaults to {@link CONSUMED_RESULT_EVICTION_MS}; tests override to a
	 * small value to assert eviction without real-time waits.
	 */
	consumedResultEvictionMs?: number;
}

interface AsyncJobDelivery {
	jobId: string;
	text: string;
	attempt: number;
	nextAttemptAt: number;
	lastError?: string;
	ownerId?: string;
	/** Owner-home token identifying the restore batch this row can be delivered to. */
	restoreReceiptId?: string;
	promise?: Promise<void>;
	/**
	 * Job-body metadata a sink needs to render the delivered result,
	 * snapshotted at enqueue time. `#deliverDelivery` falls back to
	 * reconstructing an `AsyncJob`-shaped record from this when the live job
	 * row has already been evicted (retention elapsed while delivery kept
	 * retrying) — without it, a recovered delivery would silently drop
	 * `structured` even though `text` survives on the delivery itself.
	 */
	jobSnapshot?: Pick<
		AsyncJob,
		| "type"
		| "status"
		| "startTime"
		| "endTime"
		| "label"
		| "intent"
		| "structured"
		| "agentId"
		| "agentOutputPublished"
		| "latestDetails"
	>;
}

export interface AsyncJobDeliveryState {
	queued: number;
	delivering: boolean;
	nextRetryAt?: number;
	pendingJobIds: string[];
}

export interface AsyncJobReapResult {
	settled: boolean;
	pendingJobIds: string[];
	completion: Promise<void>;
}

export interface AsyncJobRegisterOptions {
	/** Stage a cancellable job without a slot, then admit it under the running-job cap. */
	waitForCapacity?: boolean;
	/** Dependencies settled before admission; used only with `waitForCapacity`. */
	beforeStart?: (signal: AbortSignal) => Promise<void>;
	id?: string;
	/** Registry id of the agent that owns this job; used to scope cancelAll. */
	ownerId?: string;
	/** Owner-home token identifying the restore batch this row can be delivered to. */
	restoreReceiptId?: string;
	/** Registry id of the subagent this job runs; see {@link AsyncJob.agentId}. */
	agentId?: string;
	onProgress?: (text: string, details?: AsyncJobDetails) => void | Promise<void>;
	/** Register the job in queued state; see {@link AsyncJob.queued}. */
	queued?: boolean;
	/** Register the job as backing a foreground call; see {@link AsyncJob.foreground}. */
	foreground?: boolean;
	/** The process the job runs; see {@link AsyncJob.process}. */
	process?: AsyncJobProcess;
	/** See {@link AsyncJob.intent}. */
	intent?: string;
	/** See {@link AsyncJob.request}. */
	request?: string;
	/** See {@link AsyncJob.widgetInputs}. */
	widgetInputs?: JobWidgetInputs;
}

/**
 * Filter applied to job query/cancel/delivery APIs. Matches jobs registered by
 * exactly `ownerId` (registry id from `AgentRegistry`, e.g. "Main",
 * "AuthLoader"); `ownerId: undefined` matches only unowned jobs. Omit the
 * filter entirely for a manager-wide view.
 */
export interface AsyncJobFilter {
	ownerId: string | undefined;
	/** Owner-home token identifying the restore batch this row can be delivered to. */
	restoreReceiptId?: string;
}

/** What a job body receives from {@link AsyncJobManagerApi.register}. */
export interface AsyncJobRunContext {
	jobId: string;
	signal: AbortSignal;
	reportProgress: (text: string, details?: AsyncJobDetails) => Promise<void>;
	/** Clear the queued flag once the job actually starts executing. */
	markRunning: () => void;
}

/** A job body: the work {@link AsyncJobManagerApi.register} runs and tracks. */
export type AsyncJobRun = (ctx: AsyncJobRunContext) => Promise<string | AsyncJobRunResult>;

/**
 * The job surface sessions, tools and subagents use on their root's manager.
 * {@link AsyncJobManager} implements it on the root's thread; a subagent worker
 * holds a remote implementation (`thread/services/async-jobs-remote.ts`) whose
 * job ids, rows and deliveries stay on the root's manager.
 */
export interface AsyncJobManagerApi {
	/** Live widgets of this root's jobs, when the root session provides them. */
	readonly widgets: JobWidgetRegistry | undefined;
	/** True when the running-job count has reached the configured cap. */
	readonly atCapacity: boolean;
	/** Calls `listener` whenever a job settles; returns the unsubscribe. */
	onJobSettled(listener: () => void): () => void;
	/**
	 * Calls `listener` whenever what a job view shows may have moved: a job was
	 * registered, started, reported progress, settled, was promoted to the
	 * background, had its result consumed, or was evicted. Returns the unsubscribe.
	 */
	onJobsChanged(listener: () => void): () => void;
	/** Start tracking `run` as a job; returns its id. */
	register(type: AsyncJobType, label: string, run: AsyncJobRun, options?: AsyncJobRegisterOptions): string;
	/** Deliver an already-completed result without consuming a running-job slot. */
	publishCompleted(
		type: AsyncJobType,
		label: string,
		result: AsyncJobRunResult,
		options: { id?: string; ownerId?: string; agentId?: string },
	): string;
	/** Cancel one running job; a filter whose owner does not match reads as not-found. */
	cancel(id: string, filter?: AsyncJobFilter): boolean;
	getJob(id: string): AsyncJob | undefined;
	/** Running background jobs; foreground-backed jobs stay hidden until promoted. */
	getRunningJobs(filter?: AsyncJobFilter): AsyncJob[];
	/** Settled background jobs, newest first. */
	getRecentJobs(limit?: number, filter?: AsyncJobFilter): AsyncJob[];
	/** Every background job row. */
	getAllJobs(filter?: AsyncJobFilter): AsyncJob[];
	/** Promote a foreground-backed job to a background job; false for unknown ids. */
	backgroundJob(jobId: string): boolean;
	/** Drop a foreground-backed job whose result the foreground call already returned. */
	releaseForegroundJob(jobId: string): void;
	getDeliveryState(filter?: AsyncJobFilter): AsyncJobDeliveryState;
	hasPendingDeliveries(filter?: AsyncJobFilter): boolean;
	watchJobs(jobIds: string[]): number;
	/** Stop watching jobs, re-enqueueing skipped deliveries. */
	unwatchJobs(jobIds: string[]): number;
	acknowledgeDeliveries(jobIds: string[]): number;
	/** Mark settled job results as recovered by a foreground snapshot. */
	consumeJobResults(jobIds: string[]): number;
	/** True once a result was auto-delivered or recovered by a foreground snapshot. */
	isJobResultConsumed(jobId: string): boolean;
	/** Cancel running jobs (scoped by `filter`), aborting each with `reason`. */
	cancelAll(filter?: AsyncJobFilter, reason?: unknown): void;
	/** Evict settled jobs matching the filter now; returns how many. */
	evictCompletedJobs(filter?: AsyncJobFilter): number;
	/** The record an evicted job left behind; undefined for live or unknown ids, or a filter whose owner does not match. */
	getEvictedJob(id: string, filter?: AsyncJobFilter): EvictedJob | undefined;
	/** Records of evicted jobs matching the filter, most recently evicted first. */
	getEvictedJobs(filter?: AsyncJobFilter): EvictedJob[];
	waitForAll(): Promise<void>;
	/** Route completions of jobs owned by `ownerId` to `sink`; returns the unregister. */
	registerDeliverySink(ownerId: string, sink: AsyncJobDeliverySink): () => void;
	/** Wait until every job owned by `ownerId` settled; false when `timeoutMs` elapses first. */
	waitForOwnerJobs(ownerId: string, options?: { timeoutMs?: number; excludeSuppressed?: boolean }): Promise<boolean>;
	/** Cancel every job owned by `ownerId`, then wait until `deadlineAt`. */
	cancelAndReapOwnerJobs(ownerId: string, deadlineAt: number): Promise<AsyncJobReapResult>;
	drainDeliveries(options?: { timeoutMs?: number; filter?: AsyncJobFilter }): Promise<boolean>;
	isDeliverySuppressed(jobId: string): boolean;
	/** True while a settled job's completion is queued or in flight — its push is on the way. */
	isDeliveryPending(jobId: string): boolean;
	/** True when a foreground snapshot consumed this job's result while its push was still queued. */
	isDeliverySuperseded(jobId: string): boolean;
}

export class AsyncJobManager implements AsyncJobManagerApi {
	static #instance: AsyncJobManager | undefined;

	/** Legacy pointer to the first live root; child routing uses the parent's scoped manager instead. */
	static instance(): AsyncJobManager | undefined {
		return AsyncJobManager.#instance;
	}

	/** Install or clear the process-global instance. */
	static setInstance(value: AsyncJobManager | undefined): void {
		AsyncJobManager.#instance = value;
	}

	/** Reset the process-global instance. Test-only. */
	static resetForTests(): void {
		AsyncJobManager.#instance = undefined;
	}

	readonly #jobs = new Map<string, AsyncJob>();
	readonly #deliveries: AsyncJobDelivery[] = [];
	readonly #inFlightDeliveries: AsyncJobDelivery[] = [];
	readonly #suppressedDeliveries = new Set<string>();
	/**
	 * Settled jobs whose completion push a foreground snapshot superseded: the
	 * snapshot consumed the result, so the push it raced will not reach the owner
	 * even though it was queued or in flight when the snapshot read it. Kept apart
	 * from {@link #deliveries} so the delivery line can say "superseded" instead of
	 * promising a follow-up that cannot arrive (#16135 review).
	 */
	readonly #supersededDeliveries = new Set<string>();
	readonly #watchedJobs = new Set<string>();
	readonly #consumedJobResults = new Set<string>();
	readonly #evictionTimers = new Map<string, NodeJS.Timeout>();
	readonly #evicted = new Map<string, EvictedJob>();
	readonly #releasedForegroundJobs = new Set<string>();
	#nextAutoId = 1;
	readonly #deliverySinks = new Map<string, AsyncJobDeliverySink>();
	readonly #onJobComplete: AsyncJobManagerOptions["onJobComplete"];
	readonly #maxRunningJobsOption: AsyncJobManagerOptions["maxRunningJobs"];
	readonly #retentionMs: number;
	readonly #retainedArtifactsCleanupGraceMs: number;
	readonly #retainedArtifactsCleanupMaxWaitMs: number;
	readonly #consumedResultEvictionMs: number;
	#deliveryLoop: Promise<void> | undefined;
	#deliveryQueueChanged = Promise.withResolvers<void>();
	#capacityChanged = Promise.withResolvers<void>();
	#disposed = false;
	/** Live widgets of this root's jobs; set by the root session when widgets are available. */
	widgets: JobWidgetRegistry | undefined;
	readonly #settleListeners = new Set<() => void>();
	readonly #changeListeners = new Set<() => void>();

	/**
	 * Calls `listener` whenever a job settles (completed, failed or cancelled), so
	 * views counting running jobs repaint even when no result delivery follows.
	 * Returns the unsubscribe.
	 */
	onJobSettled(listener: () => void): () => void {
		this.#settleListeners.add(listener);
		return () => {
			this.#settleListeners.delete(listener);
		};
	}

	onJobsChanged(listener: () => void): () => void {
		this.#changeListeners.add(listener);
		return () => {
			this.#changeListeners.delete(listener);
		};
	}

	#notifyJobsChanged(jobId: string): void {
		for (const listener of this.#changeListeners) {
			try {
				listener();
			} catch (error) {
				logger.warn("Async job change listener failed", {
					jobId,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}
	}

	#matchesFilter(row: { ownerId?: string; restoreReceiptId?: string }, filter?: AsyncJobFilter): boolean {
		return (
			!filter ||
			(row.ownerId === filter.ownerId &&
				(filter.restoreReceiptId === undefined || row.restoreReceiptId === filter.restoreReceiptId))
		);
	}

	#filterJobs(jobs: Iterable<AsyncJob>, filter?: AsyncJobFilter): AsyncJob[] {
		if (!filter) return Array.from(jobs);
		const out: AsyncJob[] = [];
		for (const job of jobs) {
			if (this.#matchesFilter(job, filter)) out.push(job);
		}
		return out;
	}

	#visibleJobs(filter?: AsyncJobFilter): AsyncJob[] {
		return this.#filterJobs(this.#jobs.values(), filter).filter(job => !job.foreground);
	}

	constructor(options: AsyncJobManagerOptions) {
		this.#onJobComplete = options.onJobComplete;
		this.#maxRunningJobsOption = options.maxRunningJobs;
		this.#retentionMs = Math.max(0, Math.floor(options.retentionMs ?? DEFAULT_RETENTION_MS));
		this.#retainedArtifactsCleanupGraceMs = Math.max(
			0,
			Math.floor(options.retainedArtifactsCleanupGraceMs ?? RETAINED_ARTIFACTS_CLEANUP_GRACE_MS),
		);
		this.#retainedArtifactsCleanupMaxWaitMs = Math.max(
			0,
			Math.floor(options.retainedArtifactsCleanupMaxWaitMs ?? RETAINED_ARTIFACTS_CLEANUP_MAX_WAIT_MS),
		);
		this.#consumedResultEvictionMs = Math.max(
			0,
			Math.floor(options.consumedResultEvictionMs ?? CONSUMED_RESULT_EVICTION_MS),
		);
	}

	/** Effective running-job cap (at least 1), resolved at check time. */
	get #maxRunningJobs(): number {
		const option = this.#maxRunningJobsOption;
		const value = typeof option === "function" ? option() : option;
		return Math.max(1, Math.floor(value ?? DEFAULT_MAX_RUNNING_JOBS));
	}

	/** True when the running-job count has reached the configured cap. */
	get atCapacity(): boolean {
		if (this.#disposed) return true;
		// Mirror register(): queued jobs hold no execution slot.
		let activeCount = 0;
		for (const job of this.#jobs.values()) {
			if (job.status === "running" && !job.queued) activeCount++;
		}
		return activeCount >= this.#maxRunningJobs;
	}

	register(type: AsyncJobType, label: string, run: AsyncJobRun, options?: AsyncJobRegisterOptions): string {
		if (this.#disposed) {
			throw new Error("Async job manager is disposed");
		}
		// Queued jobs hold no execution slot yet — only count jobs that are
		// actually running so a large parked batch cannot starve registration.
		let activeCount = 0;
		for (const existing of this.#jobs.values()) {
			if (existing.status === "running" && !existing.queued) activeCount++;
		}
		const maxRunningJobs = this.#maxRunningJobs;
		if (!options?.waitForCapacity && activeCount >= maxRunningJobs) {
			throw new Error(
				`Background job limit reached (${maxRunningJobs}). Wait for running jobs to finish or cancel one.`,
			);
		}

		const id = this.#claimJobId(options?.id);
		if (options?.foreground) this.#suppressedDeliveries.add(id);
		const abortController = new AbortController();
		const startTime = Date.now();

		const job: AsyncJob = {
			id,
			type,
			status: "running",
			startTime,
			label,
			...(options?.intent ? { intent: options.intent } : {}),
			...(options?.request ? { request: options.request } : {}),
			abortController,
			promise: Promise.resolve(),
			ownerId: options?.ownerId,
			restoreReceiptId: options?.restoreReceiptId,
			agentId: options?.agentId,
			process: options?.process,
			widgetInputs: options?.widgetInputs,
			queued: options?.queued === true || options?.waitForCapacity === true,
			...(options?.foreground ? { foreground: true } : {}),
		};

		const reportProgress = async (text: string, details?: AsyncJobDetails): Promise<void> => {
			job.progressText = text;
			if (details) job.latestDetails = details;
			this.#notifyJobsChanged(id);
			if (!options?.onProgress) return;
			try {
				await options.onProgress(text, details);
			} catch (error) {
				logger.warn("Async job progress callback failed", {
					jobId: id,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		};
		job.promise = (async () => {
			try {
				if (options?.waitForCapacity) {
					// Publish every staged identity before any admission can run. In
					// particular, a restored parent's dependency scan must see its children.
					await Promise.resolve();
					abortController.signal.throwIfAborted();
					const { beforeStart } = options;
					if (beforeStart) await untilAborted(abortController.signal, () => beforeStart(abortController.signal));
					await this.#admitQueuedJob(job);
					// A change listener or another microtask may cancel after the slot is claimed.
					abortController.signal.throwIfAborted();
				}
				const outcome = await run({
					jobId: id,
					signal: abortController.signal,
					reportProgress,
					markRunning: () => {
						if (!job.queued) return;
						job.queued = false;
						this.#notifyJobsChanged(id);
					},
				});
				job.endTime = Date.now();
				const text = typeof outcome === "string" ? outcome : outcome.text;
				const structured = typeof outcome === "string" ? undefined : outcome.structured;
				if (structured) job.structured = structured;
				if (typeof outcome !== "string" && outcome.agentOutputPublished !== undefined) {
					job.agentOutputPublished = outcome.agentOutputPublished;
				}
				if (job.status === "cancelled") {
					job.resultText = text;
				} else {
					job.status = "completed";
					job.resultText = text;
					this.#recordAgentReply(job);
					this.#enqueueDelivery(id, text);
				}
			} catch (error) {
				job.endTime = Date.now();
				if (error instanceof AsyncJobError && error.structured) job.structured = error.structured;
				const errorText = error instanceof Error ? error.message : String(error);
				job.errorText = errorText;
				if (job.status !== "cancelled") {
					job.status = "failed";
					this.#recordAgentReply(job);
					this.#enqueueDelivery(id, errorText);
				}
			}
			this.#notifyCapacityChanged();
			if (this.#releasedForegroundJobs.has(id)) this.#discardForegroundJob(id);
			else this.#scheduleEviction(id);
			for (const listener of this.#settleListeners) {
				try {
					listener();
				} catch (error) {
					logger.warn("Async job settle listener failed", {
						jobId: id,
						error: error instanceof Error ? error.message : String(error),
					});
				}
			}
			this.#notifyJobsChanged(id);
		})();

		this.#jobs.set(id, job);
		this.#evicted.delete(id);
		this.#notifyJobsChanged(id);
		return id;
	}

	async #admitQueuedJob(job: AsyncJob): Promise<void> {
		const signal = job.abortController.signal;
		for (;;) {
			signal.throwIfAborted();
			if (this.#disposed) throw new Error("Async job manager is disposed");
			// Check and claim without an await: competing wakeups cannot take
			// the same slot. Cancelled queued jobs never enter their run callback.
			if (!this.atCapacity) {
				job.queued = false;
				this.#notifyJobsChanged(job.id);
				return;
			}
			await untilAborted(signal, this.#capacityChanged.promise);
		}
	}

	#notifyCapacityChanged(): void {
		const changed = this.#capacityChanged;
		this.#capacityChanged = Promise.withResolvers<void>();
		changed.resolve();
	}

	/**
	 * Deliver an already-completed result through the normal owner-scoped job
	 * queue without consuming a running-job slot.
	 */
	publishCompleted(
		type: AsyncJobType,
		label: string,
		result: AsyncJobRunResult,
		options: { id?: string; ownerId?: string; agentId?: string },
	): string {
		if (this.#disposed) throw new Error("Async job manager is disposed");
		const id = this.#claimJobId(options.id);
		const now = Date.now();
		const job: AsyncJob = {
			id,
			type,
			status: "completed",
			startTime: now,
			endTime: now,
			label,
			abortController: new AbortController(),
			promise: Promise.resolve(),
			ownerId: options.ownerId,
			agentId: options.agentId,
			resultText: result.text,
			structured: result.structured,
			agentOutputPublished: result.agentOutputPublished,
		};
		this.#jobs.set(id, job);
		this.#evicted.delete(id);
		this.#recordAgentReply(job);
		this.#enqueueDelivery(id, result.text);
		this.#scheduleEviction(id);
		this.#notifyJobsChanged(id);
		return id;
	}

	/**
	 * A settled job that runs a subagent carries that agent's outcome to the
	 * job's owner, which answers whatever the owner asked the agent before now:
	 * a reply `wait` must not keep reporting as owed.
	 */
	#recordAgentReply(job: AsyncJob): void {
		if (job.agentId !== undefined && job.ownerId !== undefined) IrcBus.recordReply(job.agentId, job.ownerId);
	}

	/**
	 * Cancel a single job by id. When a filter is given and its owner does not
	 * match the job's owner, the call is treated as not-found (returns false)
	 * so cross-agent cancellation is rejected at the manager level.
	 */
	cancel(id: string, filter?: AsyncJobFilter): boolean {
		const job = this.#jobs.get(id);
		if (!job) return false;
		if (!this.#matchesFilter(job, filter)) return false;
		if (job.status !== "running") return false;
		job.status = "cancelled";
		job.abortController.abort();
		this.#notifyCapacityChanged();
		this.#notifyJobsChanged(id);
		return true;
	}

	getJob(id: string): AsyncJob | undefined {
		return this.#jobs.get(id);
	}

	/** Running background jobs; foreground-backed jobs stay hidden until promoted. */
	getRunningJobs(filter?: AsyncJobFilter): AsyncJob[] {
		return this.#visibleJobs(filter).filter(job => job.status === "running");
	}

	/** Settled background jobs, newest first; foreground-backed jobs stay hidden. */
	getRecentJobs(limit = 10, filter?: AsyncJobFilter): AsyncJob[] {
		return this.#visibleJobs(filter)
			.filter(job => job.status !== "running")
			.sort((a, b) => b.startTime - a.startTime)
			.slice(0, limit);
	}

	/** Every background job row; foreground-backed jobs stay hidden until promoted. */
	getAllJobs(filter?: AsyncJobFilter): AsyncJob[] {
		return this.#visibleJobs(filter);
	}

	/**
	 * Promote a foreground-backed job to a real background job: it becomes
	 * visible to listings and its completion is delivered (re-enqueued when it
	 * already settled during the foreground wait). Returns false for unknown ids.
	 */
	backgroundJob(jobId: string): boolean {
		const job = this.#jobs.get(jobId);
		if (!job) return false;
		if (!job.foreground) return true;
		job.foreground = undefined;
		this.#suppressedDeliveries.delete(jobId);
		if (job.status === "completed" || job.status === "failed") {
			this.#enqueueDelivery(jobId, job.status === "completed" ? (job.resultText ?? "") : (job.errorText ?? ""));
		}
		this.#notifyJobsChanged(jobId);
		return true;
	}

	/**
	 * Drop a foreground-backed job whose result the foreground call already
	 * returned (or whose call aborted). The row is discarded as soon as its run
	 * settles and never surfaces as a background job.
	 */
	releaseForegroundJob(jobId: string): void {
		const job = this.#jobs.get(jobId);
		if (!job?.foreground) return;
		if (job.endTime !== undefined) this.#discardForegroundJob(jobId);
		else this.#releasedForegroundJobs.add(jobId);
	}

	getDeliveryState(filter?: AsyncJobFilter): AsyncJobDeliveryState {
		const deliveries = this.#filterDeliveries(filter);
		const inFlightDeliveries = this.#filterInFlightDeliveries(filter);
		const nextRetryAt = deliveries.reduce<number | undefined>((next, delivery) => {
			if (next === undefined) return delivery.nextAttemptAt;
			return Math.min(next, delivery.nextAttemptAt);
		}, undefined);

		return {
			queued: deliveries.length + inFlightDeliveries.length,
			delivering: inFlightDeliveries.length > 0 || (this.#deliveryLoop !== undefined && deliveries.length > 0),
			nextRetryAt,
			pendingJobIds: deliveries.concat(inFlightDeliveries).map(delivery => delivery.jobId),
		};
	}

	hasPendingDeliveries(filter?: AsyncJobFilter): boolean {
		return this.getDeliveryState(filter).queued > 0;
	}

	watchJobs(jobIds: string[]): number {
		const uniqueJobIds = Array.from(new Set(jobIds.map(id => id.trim()).filter(id => id.length > 0)));
		for (const jobId of uniqueJobIds) {
			this.#watchedJobs.add(jobId);
		}
		this.#notifyDeliveryQueueChanged();
		return uniqueJobIds.length;
	}

	/**
	 * Stop watching jobs. Settled jobs whose delivery was skipped while watched
	 * and not consumed are re-enqueued.
	 */
	unwatchJobs(jobIds: string[]): number {
		const uniqueJobIds = Array.from(new Set(jobIds.map(id => id.trim()).filter(id => id.length > 0)));
		let removed = 0;
		for (const jobId of uniqueJobIds) {
			if (!this.#watchedJobs.delete(jobId)) continue;
			removed += 1;
			const job = this.#jobs.get(jobId);
			if (!job || (job.status !== "completed" && job.status !== "failed")) continue;
			if (this.isDeliverySuppressed(jobId) || this.#consumedJobResults.has(jobId)) continue;
			const queued =
				this.#deliveries.some(delivery => delivery.jobId === jobId) ||
				this.#inFlightDeliveries.some(delivery => delivery.jobId === jobId);
			if (!queued) {
				this.#enqueueDelivery(jobId, job.status === "completed" ? (job.resultText ?? "") : (job.errorText ?? ""));
			}
		}
		return removed;
	}

	acknowledgeDeliveries(jobIds: string[]): number {
		const uniqueJobIds = Array.from(new Set(jobIds.map(id => id.trim()).filter(id => id.length > 0)));
		if (uniqueJobIds.length === 0) return 0;

		for (const jobId of uniqueJobIds) {
			this.#suppressedDeliveries.add(jobId);
		}

		const before = this.#deliveries.length;
		this.#deliveries.splice(
			0,
			this.#deliveries.length,
			...this.#deliveries.filter(delivery => !this.isDeliverySuppressed(delivery.jobId)),
		);
		this.#notifyDeliveryQueueChanged();
		return before - this.#deliveries.length;
	}

	/**
	 * Mark settled job results as recovered by a foreground snapshot.
	 *
	 * Suppresses queued delivery and marks retained bodies as consumed so later
	 * snapshots report execution state without replaying the same result.
	 */
	consumeJobResults(jobIds: string[]): number {
		const uniqueJobIds = Array.from(new Set(jobIds.map(id => id.trim()).filter(id => id.length > 0)));
		// Record the superseded push BEFORE acknowledging: acknowledgement drops
		// the queued entry, so `isDeliveryPending` is false by the time the
		// per-job consume below runs, and the delivery line could no longer tell a
		// push this snapshot superseded from one that was never queued (#16135
		// review).
		for (const jobId of uniqueJobIds) {
			if (this.isDeliveryPending(jobId)) this.#supersededDeliveries.add(jobId);
		}
		this.acknowledgeDeliveries(uniqueJobIds);
		let consumed = 0;
		for (const jobId of uniqueJobIds) {
			if (this.#consumeJobResult(jobId)) consumed += 1;
		}
		return consumed;
	}

	/** True once a result was auto-delivered or recovered by a foreground snapshot. */
	isJobResultConsumed(jobId: string): boolean {
		return this.#consumedJobResults.has(jobId);
	}

	/**
	 * Cancel running jobs. With a filter, cancels only jobs the matching owner
	 * registered; with no filter, cancels every running job
	 * (used by `dispose()` to nuke the manager's state).
	 *
	 * `reason` is forwarded to each job's `AbortController.abort`, so a session
	 * teardown can tag its owned jobs with {@link ASYNC_JOB_MANAGER_SHUTDOWN_REASON}
	 * before `dispose()` runs — the task executor reads it to park (not
	 * tombstone) a subagent interrupted purely by process shutdown.
	 */
	cancelAll(filter?: AsyncJobFilter, reason?: unknown): void {
		this.#cancelJobs(filter, reason);
	}

	#cancelJobs(filter?: AsyncJobFilter, reason?: unknown): void {
		for (const job of this.#filterJobs(this.#jobs.values(), filter)) {
			if (job.status !== "running") continue;
			job.status = "cancelled";
			job.abortController.abort(reason);
			this.#notifyJobsChanged(job.id);
		}
		this.#notifyCapacityChanged();
	}

	/**
	 * Immediately evict completed and failed jobs matching the filter instead of
	 * waiting for retention expiry, dropping every queued delivery so a prior
	 * session's result can never be injected into a later transcript. Returns the
	 * number of jobs evicted.
	 *
	 * A delivery whose sink call is already in flight (or drained onto a caller's
	 * yield queue) is guarded by the owner's delivery generation, not the per-id
	 * suppression marker — that marker is cleared when the id is reused.
	 */
	evictCompletedJobs(filter?: AsyncJobFilter): number {
		let evicted = 0;
		for (const job of this.#filterJobs(this.#jobs.values(), filter)) {
			if (job.status !== "completed" && job.status !== "failed") continue;
			this.acknowledgeDeliveries([job.id]);
			if (this.#evictJob(job.id, "cleared")) evicted += 1;
		}
		return evicted;
	}

	getEvictedJob(id: string, filter?: AsyncJobFilter): EvictedJob | undefined {
		const record = this.#evicted.get(id);
		if (
			!record ||
			((filter?.ownerId !== undefined || filter?.restoreReceiptId !== undefined) &&
				!this.#matchesFilter(record, filter))
		)
			return undefined;
		return record;
	}

	getEvictedJobs(filter?: AsyncJobFilter): EvictedJob[] {
		const records = [...this.#evicted.values()].reverse();
		return filter?.ownerId === undefined && filter?.restoreReceiptId === undefined
			? records
			: records.filter(record => this.#matchesFilter(record, filter));
	}

	async waitForAll(): Promise<void> {
		await Promise.all(Array.from(this.#jobs.values()).map(job => job.promise));
	}

	/**
	 * Route completions for jobs owned by `ownerId` to `sink`. Sessions register
	 * their own sink at construction and unregister on dispose. Owned deliveries
	 * with no live sink are dead-lettered — `onJobComplete` serves only unowned
	 * deliveries.
	 *
	 * Last registration wins for an owner id; the returned unregister clears the
	 * mapping only while it still points at `sink`, so a revived session's fresh
	 * registration survives its parked predecessor's late cleanup.
	 */
	registerDeliverySink(ownerId: string, sink: AsyncJobDeliverySink): () => void {
		this.#deliverySinks.set(ownerId, sink);
		return () => {
			if (this.#deliverySinks.get(ownerId) === sink) this.#deliverySinks.delete(ownerId);
		};
	}

	/**
	 * Wait until every job owned by `ownerId` has settled — its run promise
	 * resolved, which for cancelled jobs means the underlying process actually
	 * exited. Jobs registered while waiting (e.g. by a follow-up turn) are
	 * awaited too. Returns false when `timeoutMs` elapses first.
	 *
	 * `excludeSuppressed` skips jobs whose delivery is suppressed (acknowledged
	 * or `wait`-watched): those can never re-wake a run, so quiescence barriers
	 * pass it to share one contract with the pending-async-wake predicate.
	 * Teardown reaps omit it — worktree safety concerns every owner process.
	 */
	async waitForOwnerJobs(
		ownerId: string,
		options?: { timeoutMs?: number; excludeSuppressed?: boolean },
	): Promise<boolean> {
		const deadline =
			options?.timeoutMs === undefined ? Number.POSITIVE_INFINITY : Date.now() + Math.max(0, options.timeoutMs);
		const awaited = new Set<string>();
		for (;;) {
			const pending = this.#filterJobs(this.#jobs.values(), { ownerId }).filter(
				job => !awaited.has(job.id) && (options?.excludeSuppressed !== true || !this.isDeliverySuppressed(job.id)),
			);
			if (pending.length === 0) return true;
			for (const job of pending) awaited.add(job.id);
			const settled = await this.#waitForDeliveryPromise(
				Promise.all(pending.map(job => job.promise)).then(() => {}),
				deadline,
			);
			if (!settled) return false;
		}
	}

	/**
	 * Cancel every job owned by `ownerId`, then wait only until `deadlineAt`.
	 * The returned completion keeps waiting for actual process settlement when
	 * the deadline expires, so callers can move that cleanup out of the
	 * user-visible Task wait without losing ownership of the live work.
	 */
	async cancelAndReapOwnerJobs(ownerId: string, deadlineAt: number): Promise<AsyncJobReapResult> {
		this.cancelAll({ ownerId });
		const timeoutMs = Math.max(0, deadlineAt - Date.now());
		const settled = await this.waitForOwnerJobs(ownerId, { timeoutMs });
		if (settled) {
			return { settled: true, pendingJobIds: [], completion: Promise.resolve() };
		}
		const pendingJobIds = this.#filterJobs(this.#jobs.values(), { ownerId })
			.filter(job => job.status === "running" || job.status === "cancelled")
			.map(job => job.id);
		const completion = this.waitForOwnerJobs(ownerId).then(() => {});
		return { settled: false, pendingJobIds, completion };
	}

	async #waitForAllUntil(deadline: number): Promise<boolean> {
		const promises = Array.from(this.#jobs.values()).map(job => job.promise);
		if (promises.length === 0) return true;
		if (deadline === Number.POSITIVE_INFINITY) {
			await Promise.all(promises);
			return true;
		}
		const remainingMs = deadline - Date.now();
		if (remainingMs <= 0) return false;

		const timeout = Promise.withResolvers<"timeout">();
		const timer = setTimeout(() => timeout.resolve("timeout"), remainingMs);
		timer.unref();
		try {
			const result = await Promise.race([Promise.all(promises).then(() => "settled" as const), timeout.promise]);
			return result === "settled";
		} finally {
			clearTimeout(timer);
		}
	}

	async drainDeliveries(options?: { timeoutMs?: number; filter?: AsyncJobFilter }): Promise<boolean> {
		const timeoutMs = options?.timeoutMs;
		const filter = options?.filter;
		const hasDeadline = timeoutMs !== undefined;
		const deadline = hasDeadline ? Date.now() + Math.max(timeoutMs, 0) : Number.POSITIVE_INFINITY;

		while (this.hasPendingDeliveries(filter)) {
			if (filter) {
				const delivered = await this.#deliverNextFiltered(filter, deadline);
				if (delivered) continue;
				return false;
			}
			const inFlightDeliveries = this.#filterInFlightDeliveries();
			if (inFlightDeliveries.length > 0 && this.#filterDeliveries().length === 0) {
				const delivered = await this.#waitForDeliveryPromise(inFlightDeliveries[0]?.promise, deadline);
				if (delivered) continue;
				return false;
			}

			this.#ensureDeliveryLoop();
			const loop = this.#deliveryLoop;
			if (!loop) {
				continue;
			}

			if (!hasDeadline) {
				await loop;
				continue;
			}

			const remainingMs = deadline - Date.now();
			if (remainingMs <= 0) {
				return false;
			}

			await Promise.race([loop, Bun.sleep(remainingMs)]);
			if (Date.now() >= deadline && this.hasPendingDeliveries(filter)) {
				return false;
			}
		}

		return true;
	}

	async dispose(options?: { timeoutMs?: number }): Promise<boolean> {
		this.#disposed = true;
		this.#clearEvictionTimers();
		this.#cancelJobs(undefined, ASYNC_JOB_MANAGER_SHUTDOWN_REASON);
		const timeoutMs = Math.max(options?.timeoutMs ?? 3_000, 0);
		const deadline = Date.now() + timeoutMs;
		const jobsSettled = await this.#waitForAllUntil(deadline);
		const drained = await this.drainDeliveries({ timeoutMs: Math.max(deadline - Date.now(), 0) });
		this.#clearEvictionTimers();
		// Bypass the grace-period sleep: dispose has already drained/cancelled
		// deliveries above, so there is nothing left for the model to read via
		// `agent://<id>` — sleeping the retention window here would only leak
		// temp dirs for up to `retainedArtifactsCleanupGraceMs` (or past
		// process exit, since dispose does not await these cleanups).
		for (const job of this.#jobs.values()) this.#runRetainedArtifactsCleanup(job, { bypassGrace: true });
		this.#jobs.clear();
		this.#deliveries.length = 0;
		this.#notifyDeliveryQueueChanged();
		this.#inFlightDeliveries.length = 0;
		this.#suppressedDeliveries.clear();
		this.#supersededDeliveries.clear();
		this.#watchedJobs.clear();
		this.#consumedJobResults.clear();
		this.#releasedForegroundJobs.clear();
		this.#deliverySinks.clear();
		this.widgets?.dispose();
		this.widgets = undefined;
		return jobsSettled && drained;
	}

	#consumeJobResult(jobId: string): boolean {
		const job = this.#jobs.get(jobId);
		if (!job || job.status === "running" || this.#consumedJobResults.has(jobId)) return false;
		if (job.resultText === undefined && job.errorText === undefined) return false;
		this.#consumedJobResults.add(jobId);
		this.#notifyJobsChanged(jobId);
		// The result reached its consumer (sink delivery or foreground snapshot):
		// the row no longer needs to outlive the full retention window. Re-arm the
		// eviction timer with the short consumed grace — but only when no delivery
		// for this job is still queued or in flight. An in-flight delivery is an
		// async-result entry parked on the owner's yield queue, and the foreground
		// snapshot that consumed this result suppressed exactly that entry via
		// #suppressedDeliveries; evicting now would clear that marker (#evictJob)
		// before the queue's isStale check drains it, letting the already-consumed
		// result inject a duplicate async-result follow-up. A parked entry keeps
		// the row until its delivery settles (see #scheduleEviction), which then
		// arms the consumed grace. Clamping inside #scheduleEviction keeps a
		// shorter configured retention the effective cap.
		const deliveryPending =
			this.#deliveries.some(delivery => delivery.jobId === jobId) ||
			this.#inFlightDeliveries.some(delivery => delivery.jobId === jobId);
		if (!deliveryPending) {
			this.#scheduleEviction(jobId, this.#consumedResultEvictionMs);
		}
		return true;
	}

	/**
	 * Evict a released foreground job and, when it holds the newest auto id,
	 * return that id to the counter: it was never listed or delivered, so the
	 * next background job reuses it without gaps or ambiguity.
	 */
	#discardForegroundJob(jobId: string): void {
		this.#releasedForegroundJobs.delete(jobId);
		this.#evictJob(jobId);
		if (jobId === `bg_${this.#nextAutoId - 1}`) this.#nextAutoId -= 1;
	}

	#claimJobId(preferredId?: string): string {
		const id = this.#resolveJobId(preferredId);
		this.#suppressedDeliveries.delete(id);
		this.#supersededDeliveries.delete(id);
		this.#consumedJobResults.delete(id);
		this.#releasedForegroundJobs.delete(id);
		return id;
	}

	#resolveJobId(preferredId?: string): string {
		preferredId = preferredId?.trim();
		if (!preferredId) {
			// Monotonic for the manager's lifetime: evicted ids are never recycled,
			// so `bg_N` names one job for the whole session.
			while (true) {
				const id = `bg_${this.#nextAutoId}`;
				this.#nextAutoId += 1;
				if (!this.#jobs.has(id)) return id;
			}
		}

		const base = preferredId.trim();
		if (!this.#jobs.has(base)) return base;

		let suffix = 2;
		let candidate = `${base}-${suffix}`;
		while (this.#jobs.has(candidate)) {
			suffix += 1;
			candidate = `${base}-${suffix}`;
		}
		return candidate;
	}

	/**
	 * Fire a retained temporary artifacts cleanup exactly once, deferred
	 * until this job's `async-result` delivery has settled (delivered,
	 * dead-lettered, or given up retrying) plus a grace period. Job-row
	 * eviction happens on its own timer independent of delivery — a still-
	 * streaming owner session can leave a delivery in flight (its sink
	 * awaits `yieldQueue.enqueueWithReceipt()`) well past the retention
	 * window, and deleting the retained directory before that receipt
	 * settles would advertise an `agent://` URL whose backing files are
	 * already gone.
	 * The receipt itself resolves at `ASIDE_MESSAGE_COMMIT` — when the
	 * follow-up is inserted into the transcript, but *before* the next
	 * provider call that actually shows it to the model (agent-loop fires
	 * the commit hook, then starts the call). Running cleanup immediately
	 * on settlement would delete the artifacts before the model's very next
	 * turn has any chance to read the pointer via a tool call, so a grace
	 * period covers that round trip.
	 * Errors are logged, not thrown — a failed disposal must not block job
	 * eviction or manager teardown.
	 */
	#runRetainedArtifactsCleanup(job: AsyncJob, options?: { bypassGrace?: boolean }): void {
		const cleanup = job.retainedArtifactsCleanup;
		if (!cleanup) return;
		job.retainedArtifactsCleanup = undefined;
		const jobId = job.id;
		const bypassGrace = options?.bypassGrace === true;
		void this.#waitForJobDeliverySettledBounded(jobId)
			.then(() =>
				!bypassGrace && this.#retainedArtifactsCleanupGraceMs > 0
					? Bun.sleep(this.#retainedArtifactsCleanupGraceMs)
					: undefined,
			)
			.then(cleanup)
			.catch(error => {
				logger.warn("Async job retained artifacts cleanup failed", {
					jobId,
					error: error instanceof Error ? error.message : String(error),
				});
			});
	}

	/**
	 * Bounded variant of {@link #waitForJobDeliverySettled}: gives up and
	 * resolves after {@link #retainedArtifactsCleanupMaxWaitMs} even if the
	 * delivery sink never settles (e.g. a yield-queue receipt whose owning
	 * session is gone) so a hung sink cannot leak the retained temp
	 * directory for the process lifetime (PR #10625 review). The unbounded
	 * wait keeps running in the background after the bound trips; it is
	 * harmless once orphaned since cleanup no longer depends on it.
	 */
	async #waitForJobDeliverySettledBounded(jobId: string): Promise<void> {
		const timedOut = Promise.withResolvers<true>();
		const timer = setTimeout(() => timedOut.resolve(true), this.#retainedArtifactsCleanupMaxWaitMs);
		timer.unref();
		try {
			const timedOutFirst = await Promise.race([
				this.#waitForJobDeliverySettled(jobId).then(() => false as const),
				timedOut.promise,
			]);
			if (timedOutFirst) {
				logger.warn(
					"Async job delivery did not settle before the retained artifacts cleanup bound; running cleanup anyway",
					{
						jobId,
						maxWaitMs: this.#retainedArtifactsCleanupMaxWaitMs,
					},
				);
			}
		} finally {
			clearTimeout(timer);
		}
	}

	/**
	 * Resolve once no delivery for `jobId` is queued or in flight. Loops
	 * because a failed in-flight attempt may requeue itself for retry;
	 * terminates once the delivery succeeds, is dead-lettered (no live
	 * sink), or stops retrying (job already evicted from `#jobs`).
	 */
	async #waitForJobDeliverySettled(jobId: string): Promise<void> {
		for (;;) {
			const inFlight = this.#inFlightDeliveries.find(delivery => delivery.jobId === jobId);
			if (inFlight) {
				await inFlight.promise?.catch(() => {});
				continue;
			}
			const queued = this.#deliveries.find(delivery => delivery.jobId === jobId);
			if (!queued) return;
			this.#ensureDeliveryLoop();
			await this.#waitForDeliveryQueueChange(Math.max(50, queued.nextAttemptAt - Date.now()));
		}
	}

	/** Drop a job row; `reason` leaves an {@link EvictedJob} record for a background job's id. */
	#evictJob(jobId: string, reason?: EvictedJob["reason"]): boolean {
		clearTimeout(this.#evictionTimers.get(jobId));
		this.#evictionTimers.delete(jobId);
		this.#suppressedDeliveries.delete(jobId);
		this.#supersededDeliveries.delete(jobId);
		this.#watchedJobs.delete(jobId);
		const delivered = this.#consumedJobResults.delete(jobId);
		const job = this.#jobs.get(jobId);
		if (job) this.#runRetainedArtifactsCleanup(job);
		if (job && reason && !job.foreground) {
			this.#evicted.delete(jobId);
			this.#evicted.set(jobId, {
				id: jobId,
				type: job.type,
				label: job.label,
				ownerId: job.ownerId,
				restoreReceiptId: job.restoreReceiptId,
				status: job.status,
				endTime: job.endTime,
				evictedAt: Date.now(),
				delivered,
				reason,
			});
			if (this.#evicted.size > EVICTED_JOB_LIMIT) {
				const oldest = this.#evicted.keys().next().value;
				if (oldest !== undefined) this.#evicted.delete(oldest);
			}
		}
		this.widgets?.forget(jobId);
		const removed = this.#jobs.delete(jobId);
		if (removed) this.#notifyJobsChanged(jobId);
		return removed;
	}

	/**
	 * Arm (or re-arm) this job's eviction timer. The default delay is the full
	 * retention window; a consumed result passes the shorter
	 * {@link #consumedResultEvictionMs}. The delay is clamped to the configured
	 * retention so an explicit short retention always stays the effective cap.
	 * A timer that fires while a suppressed job's delivery is in flight (its
	 * async-result entry parked on a busy owner's yield queue) evicts only once
	 * that attempt settles: the parked entry's isStale check resolves through
	 * the suppression marker #evictJob clears, so evicting mid-park would
	 * re-inject a result a foreground snapshot already consumed. Unsuppressed
	 * in-flight deliveries keep the bounded lifecycle, so a receipt that never
	 * settles cannot pin the row and its retained artifacts.
	 */
	#scheduleEviction(jobId: string, delayMs: number = this.#retentionMs): void {
		if (this.#disposed) return;
		if (this.#retentionMs <= 0) {
			this.#evictJob(jobId, "expired");
			return;
		}
		const delay = Math.max(0, Math.min(this.#retentionMs, delayMs));
		clearTimeout(this.#evictionTimers.get(jobId));
		const timer = setTimeout(() => {
			const inFlight = this.#inFlightDeliveries.find(delivery => delivery.jobId === jobId)?.promise;
			if (!inFlight || !this.isDeliverySuppressed(jobId)) {
				this.#evictJob(jobId, "expired");
				return;
			}
			// The settled attempt may re-arm this job's timer (consumed grace);
			// only evict when nothing replaced this one in the meantime.
			void inFlight.then(() => {
				if (this.#evictionTimers.get(jobId) === timer) this.#evictJob(jobId, "expired");
			});
		}, delay);
		timer.unref();
		this.#evictionTimers.set(jobId, timer);
	}

	#clearEvictionTimers(): void {
		for (const timer of this.#evictionTimers.values()) {
			clearTimeout(timer);
		}
		this.#evictionTimers.clear();
	}

	#filterDeliveries(filter?: AsyncJobFilter): AsyncJobDelivery[] {
		return this.#deliveries.filter(
			delivery => this.#matchesFilter(delivery, filter) && !this.isDeliverySuppressed(delivery.jobId),
		);
	}

	#filterInFlightDeliveries(filter?: AsyncJobFilter): AsyncJobDelivery[] {
		return this.#inFlightDeliveries.filter(
			delivery => this.#matchesFilter(delivery, filter) && !this.isDeliverySuppressed(delivery.jobId),
		);
	}

	async #deliverNextFiltered(filter: AsyncJobFilter, deadline: number): Promise<boolean> {
		while (true) {
			let selected: AsyncJobDelivery | undefined;
			for (const delivery of this.#deliveries) {
				if (!this.#matchesFilter(delivery, filter)) continue;
				if (this.isDeliverySuppressed(delivery.jobId)) continue;
				if (!selected || delivery.nextAttemptAt < selected.nextAttemptAt) {
					selected = delivery;
				}
			}

			if (!selected) {
				const inFlight = this.#filterInFlightDeliveries(filter);
				if (inFlight.length === 0) return true;
				return this.#waitForDeliveryPromise(inFlight[0]?.promise, deadline);
			}

			const now = Date.now();
			if (selected.nextAttemptAt > now) {
				if (selected.nextAttemptAt > deadline) return false;
				await this.#waitForDeliveryQueueChange(selected.nextAttemptAt - now);
				continue;
			}

			const index = this.#deliveries.indexOf(selected);
			if (index === -1) continue;
			this.#deliveries.splice(index, 1);
			this.#notifyDeliveryQueueChanged();
			if (this.isDeliverySuppressed(selected.jobId)) continue;

			return this.#waitForDeliveryPromise(this.#deliverDelivery(selected), deadline);
		}
	}

	isDeliverySuppressed(jobId: string): boolean {
		return this.#suppressedDeliveries.has(jobId) || this.#watchedJobs.has(jobId);
	}

	/**
	 * True while a settled job's completion is queued or in flight — its push
	 * is on the way rather than lost. A `wait` that returns such a result
	 * handed it over first; the delivery it raced is not a missed push
	 * (#16052). Watch suppression is not consulted: `watchJobs` blocks new
	 * enqueue attempts, but a push already queued or in flight when the watch
	 * began is still on the way, and treating it as lost mislabels the result
	 * this snapshot hands over (#18635).
	 */
	isDeliveryPending(jobId: string): boolean {
		return (
			this.#deliveries.some(delivery => delivery.jobId === jobId) ||
			this.#inFlightDeliveries.some(delivery => delivery.jobId === jobId)
		);
	}

	/**
	 * True when a foreground snapshot recovered this job's result while its
	 * completion push was still queued or in flight. That push is superseded —
	 * the snapshot consumed the result, so the entry it suppressed cannot reach
	 * the owner. Lets the delivery line report a superseded push rather than
	 * "still on the way", which would make the model expect a duplicate (#16135
	 * review).
	 */
	isDeliverySuperseded(jobId: string): boolean {
		return this.#supersededDeliveries.has(jobId);
	}

	#enqueueDelivery(jobId: string, text: string): void {
		// Skip delivery if already acknowledged
		if (this.isDeliverySuppressed(jobId)) {
			return;
		}
		const job = this.#jobs.get(jobId);
		this.#queueDelivery({
			jobId,
			text,
			attempt: 0,
			nextAttemptAt: Date.now(),
			ownerId: job?.ownerId,
			restoreReceiptId: job?.restoreReceiptId,
			jobSnapshot: job
				? {
						type: job.type,
						status: job.status,
						startTime: job.startTime,
						endTime: job.endTime,
						label: job.label,
						intent: job.intent,
						structured: job.structured,
						agentId: job.agentId,
						agentOutputPublished: job.agentOutputPublished,
						latestDetails: job.latestDetails,
					}
				: undefined,
		});
		this.#ensureDeliveryLoop();
	}

	#ensureDeliveryLoop(): void {
		if (this.#deliveryLoop) {
			return;
		}

		this.#deliveryLoop = this.#runDeliveryLoop()
			.catch(error => {
				logger.error("Async job delivery loop crashed", { error: String(error) });
			})
			.finally(() => {
				this.#deliveryLoop = undefined;
				if (this.#deliveries.length > 0) {
					this.#ensureDeliveryLoop();
				}
			});
	}

	async #runDeliveryLoop(): Promise<void> {
		while (this.#deliveries.length > 0) {
			const delivery = this.#deliveries[0];
			if (this.isDeliverySuppressed(delivery.jobId)) {
				this.#deliveries.shift();
				continue;
			}
			const waitMs = delivery.nextAttemptAt - Date.now();
			if (waitMs > 0) {
				await this.#waitForDeliveryQueueChange(waitMs);
				continue;
			}
			if (this.#deliveries[0] !== delivery) {
				continue;
			}
			if (this.isDeliverySuppressed(delivery.jobId)) {
				this.#deliveries.shift();
				continue;
			}

			this.#deliveries.shift();
			void this.#deliverDelivery(delivery);
		}
	}

	/**
	 * Resolve the sink for one delivery attempt: owned deliveries route ONLY to
	 * their owner's registered sink (a missing sink dead-letters — never the
	 * default, which would misroute a dead owner's result into another
	 * session); unowned deliveries use the constructor default. Resolved per
	 * attempt so a sink registered between retries (e.g. a revived session)
	 * picks up the retry.
	 */
	#resolveDeliverySink(ownerId: string | undefined): AsyncJobDeliverySink | undefined {
		if (ownerId !== undefined) return this.#deliverySinks.get(ownerId);
		return this.#onJobComplete;
	}

	#deliverDelivery(delivery: AsyncJobDelivery): Promise<void> {
		const row = this.#jobs.get(delivery.jobId);
		// A retained/retrying restore result must not borrow a replacement row's
		// metadata or consume that row's result, even if the public id was reused.
		if (
			row &&
			(row.restoreReceiptId !== undefined || delivery.restoreReceiptId !== undefined) &&
			row.restoreReceiptId !== delivery.restoreReceiptId
		) {
			delivery.promise = Promise.resolve();
			return delivery.promise;
		}
		const rowIsCurrent = () => this.#jobs.get(delivery.jobId) === row;
		const sink = this.#resolveDeliverySink(delivery.ownerId);
		if (!sink) {
			// Dead-letter: owned delivery with no live sink (session disposed or
			// parked), or unowned delivery with no default sink. Drop it — the
			// job row keeps its result/error text until retention eviction, so
			// the outcome stays inspectable via job queries and agent:// reads.
			logger.warn("Async job delivery dead-lettered: no delivery sink", {
				jobId: delivery.jobId,
				ownerId: delivery.ownerId,
			});
			delivery.promise = Promise.resolve();
			return delivery.promise;
		}
		const promise = (async () => {
			this.#inFlightDeliveries.push(delivery);
			let delivered = false;
			try {
				await sink(delivery.jobId, delivery.text, row ?? this.#reconstructEvictedJob(delivery));
				delivered = true;
				// A foreground snapshot may have consumed this result while the
				// sink receipt was parked. The receipt has now settled, so the
				// suppression tombstone no longer needs the full retention window.
				if (rowIsCurrent() && this.#consumedJobResults.has(delivery.jobId) && this.#jobs.has(delivery.jobId)) {
					this.#scheduleEviction(delivery.jobId, this.#consumedResultEvictionMs);
				}
			} catch (error) {
				delivery.attempt += 1;
				delivery.lastError = error instanceof Error ? error.message : String(error);
				delivery.nextAttemptAt = Date.now() + this.#getRetryDelay(delivery.attempt);
				if (rowIsCurrent() && !this.isDeliverySuppressed(delivery.jobId) && this.#jobs.has(delivery.jobId)) {
					this.#queueDelivery(delivery);
				}
				logger.warn("Async job completion delivery failed", {
					jobId: delivery.jobId,
					attempt: delivery.attempt,
					nextRetryAt: delivery.nextAttemptAt,
					error: delivery.lastError,
				});
			} finally {
				const index = this.#inFlightDeliveries.indexOf(delivery);
				if (index !== -1) this.#inFlightDeliveries.splice(index, 1);
				if (this.#deliveries.length > 0) this.#ensureDeliveryLoop();
			}
			// A normally delivered result is consumed only after the attempt left
			// #inFlightDeliveries, so it can arm the short eviction grace.
			if (delivered && rowIsCurrent() && !this.#consumedJobResults.has(delivery.jobId)) {
				this.#consumeJobResult(delivery.jobId);
			}
		})();
		delivery.promise = promise;
		return promise;
	}

	/**
	 * Rebuild a minimal {@link AsyncJob} from a delivery's enqueue-time
	 * snapshot when the live job row was already evicted by the time this
	 * delivery attempt runs (retention elapsed while delivery kept retrying).
	 * Lets the sink still render `type`/`label`/`structured` instead of
	 * silently losing them, matching what `job.resultText` would have carried
	 * had the row survived.
	 */
	#reconstructEvictedJob(delivery: AsyncJobDelivery): AsyncJob | undefined {
		const snapshot = delivery.jobSnapshot;
		if (!snapshot) return undefined;
		return {
			id: delivery.jobId,
			type: snapshot.type,
			status: snapshot.status,
			startTime: snapshot.startTime,
			endTime: snapshot.endTime,
			label: snapshot.label,
			intent: snapshot.intent,
			abortController: new AbortController(),
			promise: Promise.resolve(),
			resultText: delivery.text,
			ownerId: delivery.ownerId,
			restoreReceiptId: delivery.restoreReceiptId,
			structured: snapshot.structured,
			agentId: snapshot.agentId,
			agentOutputPublished: snapshot.agentOutputPublished,
			latestDetails: snapshot.latestDetails,
		};
	}

	#queueDelivery(delivery: AsyncJobDelivery): void {
		const index = this.#deliveries.findIndex(candidate => candidate.nextAttemptAt > delivery.nextAttemptAt);
		if (index === -1) this.#deliveries.push(delivery);
		else this.#deliveries.splice(index, 0, delivery);
		this.#notifyDeliveryQueueChanged();
	}

	async #waitForDeliveryQueueChange(delayMs: number): Promise<void> {
		const timerElapsed = Promise.withResolvers<void>();
		const timer = setTimeout(timerElapsed.resolve, delayMs);
		timer.unref();
		try {
			await Promise.race([timerElapsed.promise, this.#deliveryQueueChanged.promise]);
		} finally {
			clearTimeout(timer);
		}
	}

	#notifyDeliveryQueueChanged(): void {
		this.#deliveryQueueChanged.resolve();
		this.#deliveryQueueChanged = Promise.withResolvers<void>();
	}

	async #waitForDeliveryPromise(promise: Promise<void> | undefined, deadline: number): Promise<boolean> {
		if (!promise) return true;
		if (deadline === Number.POSITIVE_INFINITY) {
			await promise;
			return true;
		}
		const remainingMs = deadline - Date.now();
		if (remainingMs <= 0) return false;
		let timedOut = false;
		await Promise.race([
			promise,
			Bun.sleep(remainingMs).then(() => {
				timedOut = true;
			}),
		]);
		return !timedOut;
	}

	#getRetryDelay(attempt: number): number {
		const exp = Math.min(Math.max(attempt - 1, 0), 8);
		const backoffMs = DELIVERY_RETRY_BASE_MS * 2 ** exp;
		const jitterMs = Math.floor(Math.random() * DELIVERY_RETRY_JITTER_MS);
		return Math.min(DELIVERY_RETRY_MAX_MS, backoffMs + jitterMs);
	}
}

#!/usr/bin/env bun
// Strip macOS malloc-stack-logging vars in the parent entrypoint, before any
// subprocess/worker spawn. libmalloc reads MallocStackLogging /
// MallocStackLoggingNoCompact during malloc bootstrap (pre-main) in every child
// and warns when they're present but set to "off"; a child cannot suppress its
// own warning, so the only fix is to keep them out of the inherited env here.
// (They must be unset, not set — presence is the trigger.)
try {
	delete process.env.MallocStackLogging;
	delete process.env.MallocStackLoggingNoCompact;
} catch {}

/**
 * CLI entry point — registers all commands explicitly and delegates to the
 * lightweight CLI runner from pi-utils.
 */
import type * as WorkerThreads from "node:worker_threads";
import type { MessagePort } from "node:worker_threads";
import type { CliConfig, CommandMetadata } from "@oh-my-pi/pi-utils/cli";
import type * as Postmortem from "@oh-my-pi/pi-utils/postmortem";
import {
	APP_NAME,
	getActiveProfile,
	MIN_BUN_VERSION,
	resolveProfileEnv,
	setProfile,
	VERSION,
} from "@oh-my-pi/pi-utils/dirs";

import { raiseInteractiveQos } from "@oh-my-pi/pi-utils/process-qos";
import {
	declareWorkerHostEntry,
	installWorkerInbox,
	isWorkerHostSelector,
	SHELL_PROCESS_SELECTOR,
} from "@oh-my-pi/pi-utils/worker-host";
import { installSqliteLockShim } from "@oh-my-pi/pi-natives/sqlite-locks";
import { isNativeShell, runNativeShell } from "./cli/native-shell";
import { extractProfileFlags } from "./cli/profile-bootstrap";
import type * as NativeBuiltinsSmoke from "./cli/smoke-native-builtins";
import type * as NativeSortSmoke from "./cli/smoke-native-sort";
import {
	AUTO_UPDATE_WORKER_ARG,
	COMPUTER_WORKER_ARG,
	PARENT_WATCHDOG_WORKER_ARG,
	STATS_ACTIVITY_WORKER_ARG,
	SUBAGENT_WORKER_ARG,
} from "./cli/worker-selectors";
import { DAEMON_WORKER_ARG } from "./daemon/protocol";
import { MNEMOPI_EMBED_WORKER_ARG } from "./mnemopi/embed-protocol";
import type * as JsProcessEntry from "./eval/js/process-entry";
import type { WorkerInbound as JsWorkerInbound, WorkerOutbound as JsWorkerOutbound } from "./eval/js/worker-protocol";
import { startParentWatchdog } from "./subprocess/parent-watchdog";

if (Bun.semver.order(Bun.version, MIN_BUN_VERSION) < 0) {
	process.stderr.write(
		`error: Bun runtime must be >= ${MIN_BUN_VERSION} (found v${Bun.version}). Please upgrade: bun upgrade\n`,
	);
	process.exit(1);
}

// On Windows `process.title` is the shared console title, not a process name
// (see `setProcessName`): every omp child would retitle the pane's tab.
if (process.platform !== "win32") {
	try {
		process.title = APP_NAME;
	} catch {}
}

// `Bun.build`-API compiled Windows executables report `import.meta.main ===
// false`: the standalone loader keys the entry module with native backslashes
// (`B:\~BUN\root\cli.js`) but registers the main path with forward slashes
// (`B:/~BUN/root/cli.js`), so Bun's internal match fails. `bun build --compile`
// CLI builds are unaffected. A compiled binary's entry module is by definition
// the process entry, so the define-folded PI_COMPILED marker stands in.
const isProcessEntry = import.meta.main || process.env.PI_COMPILED === "true";

/**
 * Worker inboxes must attach before this entry module reaches its first await,
 * so this branch uses Bun's synchronous CommonJS bridge. Ordinary CLI startup
 * never evaluates `node:worker_threads`.
 */
function getWorkerParentPort(): MessagePort | null {
	const workerThreads: typeof WorkerThreads = require("node:worker_threads");
	return workerThreads.parentPort;
}

/**
 * Launch flags that only switch off discovery or persistence. An argv made of
 * these still enters interactive mode, so the speculative first frame is
 * valid; anything else (subcommands, `-p`, model/session selectors) skips it.
 */
const PREPAINT_SAFE_FLAGS: Record<string, true> = {
	"--no-session": true,
	"--no-extensions": true,
	"--no-skills": true,
	"--no-rules": true,
	"--no-context-files": true,
	"--no-tools": true,
	"--no-judge": true,
	"--no-spotlight": true,
	"--offline": true,
	"--no-lsp": true,
	"--no-title": true,
	"--no-prewalk": true,
	"--no-pty": true,
};

/** Complete the OS-visible process-name setup after speculative first paint. */
async function setFullProcessName(): Promise<void> {
	// Latency boundary: bun:ffi/node:os are unnecessary before the first frame.
	const { setProcessName } = await import("@oh-my-pi/pi-utils/process-name");
	setProcessName(APP_NAME);
}

/** Install PI_PROXY handling before any command implementation can make a provider request. */
async function installNetworkBootstrap(): Promise<void> {
	// Latency boundary: proxy socket/error modules are unnecessary before the first frame.
	const { installGlobalProxyFetch } = await import("@oh-my-pi/pi-ai/utils/proxy");
	installGlobalProxyFetch();
}

// Worker-host entry declaration (Worker threads and worker subprocesses
// re-enter `Bun.main` with a hidden argv selector instead of loading separate
// worker entrypoints) happens inside `runCli` after profile bootstrap:
// `@oh-my-pi/pi-utils/env` eagerly loads `.env` from the agent directory at
// import time, so it must not be imported before `setProfile` runs.

async function showHelp(config: CliConfig<CommandMetadata>): Promise<void> {
	// Root help historically loads the selected profile's environment. The
	// lazily loaded help module imports it statically after profile bootstrap.
	const [{ renderRootHelp }, { getExtraHelpText }] = await Promise.all([
		import("@oh-my-pi/pi-utils/cli"),
		import("./cli/help-extra"),
	]);
	renderRootHelp(config);
	const extra = getExtraHelpText();
	if (extra.trim().length > 0) {
		process.stdout.write(`\n${extra}\n`);
	}
}
/**
 * Smoke-test entry. Spawns bundled workers, serves the stats dashboard once,
 * pings everything, then exits.
 *
 * Purpose: catch the silent worker-load and bundled-asset regressions that hit
 * compiled binaries and the npm CLI bundle. Version/help paths do not spawn
 * worker modules or serve dashboard assets on a fresh install, so this probe is
 * the minimal end-to-end test that proves those distribution-only paths work.
 * Wired into `scripts/install-tests/run-ci.sh` so binary / source-link /
 * tarball installs all exercise it on every CI run.
 */
async function runSmokeTest(): Promise<void> {
	const { smokeTestSpotlightWorker, smokeTestSyncWorker, startServer } = await import("@oh-my-pi/omp-stats");
	const { smokeTestTinyTitleWorker } = await import("./tiny/title-client");
	const { smokeTestSttWorker } = await import("./stt/asr-client");
	const { smokeTestTtsWorker } = await import("./tts/tts-client");
	const { smokeTestMnemopiEmbedWorker } = await import("./mnemopi/embed-client");
	const { smokeTestStatsActivityWorker } = await import("./stats/activity-client");
	const { smokeTestJsEvalWorker } = await import("./eval/js/context-manager");
	// Other smoke dependencies stay lazy so normal CLI startup does not load their worker clients.
	const { isolateDaemonForSmokeTest, smokeTestDaemon } = await import("./daemon/client");
	const { smokeTestSubagentWorker } = await import("./thread/subagent-worker");
	// Every smoke that reaches the daemon must start this build's own, never the user's live one.
	const cleanupDaemon = await isolateDaemonForSmokeTest();
	try {
		// Keep the native addon out of ordinary CLI startup, like the worker-host bridge above.
		const { smokeTestNativeSort }: typeof NativeSortSmoke = require("./cli/smoke-native-sort");
		const sort = await smokeTestNativeSort();
		process.stdout.write(
			`native-sort smoke: ${sort.localeCollation ? "en_US.UTF-8 collation" : "host byte fallback"}\n`,
		);
		const { smokeTestNativeBuiltins }: typeof NativeBuiltinsSmoke = require("./cli/smoke-native-builtins");
		const builtins = await smokeTestNativeBuiltins();
		process.stdout.write(
			`native-builtins smoke: chmod ${builtins.chmodNoDereference ? "no-follow rejection verified" : "not applicable (Windows)"}; dd unsupported flags rejected before I/O and supported copies verified; env builtin disabled; external env ${builtins.envExternalIsolation ? "Unix isolation verified" : "not tested (Windows)"}\n`,
		);
		await smokeTestSyncWorker();
		await smokeTestSpotlightWorker();
		await smokeTestStatsActivityWorker();

		const statsServer = await startServer(0);
		try {
			const response = await fetch(`http://127.0.0.1:${statsServer.port}/`);
			if (!response.ok) throw new Error(`stats dashboard smoke failed: HTTP ${response.status}`);
			const html = await response.text();
			if (!html.includes('<div id="root"></div>') || !html.includes("index.js")) {
				throw new Error("stats dashboard smoke failed: dashboard HTML was not served");
			}
		} finally {
			statsServer.stop();
		}

		await smokeTestTinyTitleWorker();
		await smokeTestSttWorker();
		await smokeTestJsEvalWorker();
		const { smokeTestComputerWorker } = await import("./tools/computer/supervisor");
		await smokeTestComputerWorker();
		await smokeTestTtsWorker();
		await smokeTestMnemopiEmbedWorker();
		await smokeTestDaemon();
		await smokeTestSubagentWorker();
	} finally {
		await cleanupDaemon();
	}
	process.stdout.write("smoke-test: ok\n");
}

const TINY_WORKER_ARG = "__omp_worker_tiny_inference";
const STATS_SYNC_WORKER_ARG = "__omp_worker_stats_sync";
const STATS_SPOTLIGHT_WORKER_ARG = "__omp_worker_stats_spotlight";
const TAB_WORKER_ARG = "__omp_worker_tab";
const JS_EVAL_WORKER_ARG = "__omp_worker_js_eval";
const JS_EVAL_PROCESS_ARG = "__omp_worker_js_eval_process";
const STT_WORKER_ARG = "__omp_worker_stt";
const TTS_WORKER_ARG = "__omp_worker_tts";

async function runWorkerEntrypoint(arg: string | undefined): Promise<boolean> {
	if (arg === TINY_WORKER_ARG) {
		await runTinyWorker();
		return true;
	}
	if (arg === STATS_SYNC_WORKER_ARG || arg === STATS_SPOTLIGHT_WORKER_ARG) {
		// The stats workers handle messages via `self.onmessage`, assigned during
		// this *async* dynamic import. Bun flushes the worker's initial message
		// buffer when the entry module's top-level evaluation finishes — before
		// this dispatch completes — so anything the parent posted right after
		// spawning (the smoke ping, the first parse or build request) would be dropped.
		// Park early events and replay them once the module's handler is live.
		// Worker-thread entries using `parentPort` need the same sync-prefix
		// buffering; the computer/tab/eval cases install that inbox below.
		const scope = globalThis as unknown as { onmessage: ((event: MessageEvent) => void) | null };
		const pending: MessageEvent[] = [];
		const buffer = (event: MessageEvent): void => {
			pending.push(event);
		};
		scope.onmessage = buffer;
		if (arg === STATS_SYNC_WORKER_ARG) await import("@oh-my-pi/omp-stats/sync-worker");
		else await import("@oh-my-pi/omp-stats/spotlight-worker");
		const handler = scope.onmessage;
		if (handler && handler !== buffer) {
			for (const event of pending) handler.call(scope, event);
		}
		return true;
	}
	// Bun flushes messages the parent posted before spawn once this entry's
	// top-level evaluation completes. Install a buffering inbox synchronously
	// before binding the selected worker's real handler so the parent's
	// synchronous `init` survives. The dynamically imported tab/eval modules
	// consume the same inbox after their module evaluation begins.
	if (arg === TAB_WORKER_ARG) {
		const parentPort = getWorkerParentPort();
		if (parentPort) installWorkerInbox(parentPort);
		await import("./tools/browser/tab-worker-entry");
		return true;
	}
	if (arg === COMPUTER_WORKER_ARG) {
		const parentPort = getWorkerParentPort();
		if (parentPort) installWorkerInbox(parentPort);
		const { startComputerWorker } = await import("./tools/computer/worker-entry");
		startComputerWorker();
		return true;
	}
	if (arg === JS_EVAL_WORKER_ARG) {
		const parentPort = getWorkerParentPort();
		if (parentPort) installWorkerInbox(parentPort);
		await import("./eval/js/worker-entry");
		return true;
	}
	if (arg === SUBAGENT_WORKER_ARG) {
		const parentPort = getWorkerParentPort();
		if (parentPort) installWorkerInbox(parentPort);
		await import("./thread/subagent-worker-entry");
		return true;
	}
	if (arg === JS_EVAL_PROCESS_ARG) {
		// This selector is the synchronous bootstrap boundary: keep the evaluator
		// runtime and postmortem/inspector graph out of ordinary startup without
		// putting an await ahead of the subprocess message handler.
		const { startJsEvalProcess }: typeof JsProcessEntry = require("./eval/js/process-entry");
		// The .js subpath is the package's unconditional export for synchronous loading.
		const { interceptUnhandledRejections }: typeof Postmortem = require("@oh-my-pi/pi-utils/postmortem.js");
		// The JS evaluator forwards user-controlled payloads (tool-call args,
		// display outputs); a non-serializable one must fail that cell, not
		// SIGKILL the kernel and erase the eval session's state.
		await runIpcSubprocessWorker<JsWorkerInbound, JsWorkerOutbound>(
			transport => startJsEvalProcess(transport, interceptUnhandledRejections),
			{ rethrowConnectedSendErrors: true },
		);
		return true;
	}
	if (arg === STT_WORKER_ARG) {
		const { runSttWorker } = await import("./stt/asr-worker");
		await runSttWorker();
		return true;
	}
	if (arg === TTS_WORKER_ARG) {
		const { runTtsWorker } = await import("./tts/tts-worker");
		await runTtsWorker();
		return true;
	}
	if (arg === MNEMOPI_EMBED_WORKER_ARG) {
		const { startMnemopiEmbedWorker } = await import("./mnemopi/embed-worker");
		await startMnemopiEmbedWorker();
		return true;
	}
	if (arg === STATS_ACTIVITY_WORKER_ARG) {
		const parentPort = getWorkerParentPort();
		if (parentPort) installWorkerInbox(parentPort);
		await import("./stats/activity-worker");
		return true;
	}
	if (arg === PARENT_WATCHDOG_WORKER_ARG) {
		const parentPort = getWorkerParentPort();
		if (parentPort) installWorkerInbox(parentPort);
		await import("./subprocess/parent-watchdog-worker");
		return true;
	}
	if (arg === DAEMON_WORKER_ARG) {
		// Worker selectors must dispatch before the normal command graph loads.
		const { startDaemonFromEnvironment } = await import("./daemon/server");
		await startDaemonFromEnvironment();
		return true;
	}
	if (arg === AUTO_UPDATE_WORKER_ARG) {
		// Selector boundary keeps the updater graph out of ordinary startup. The worker
		// downloads releases, so it needs the PI_PROXY handling ordinary commands get.
		await installNetworkBootstrap();
		const { runAutoUpdateWorker } = await import("./cli/auto-update");
		await runAutoUpdateWorker();
		return true;
	}
	return false;
}

/**
 * Boot a subprocess-isolated transformers.js worker over the parent's IPC
 * channel and block until the parent disconnects. The tiny-model, STT, and TTS
 * workers each run `onnxruntime-node` (loaded transitively by
 * `@huggingface/transformers`) in a child address space because its NAPI
 * finalizer segfaults Bun on shutdown (issue #1606); the parent `SIGKILL`s the
 * child so that finalizer never runs in either process. This wires `process`
 * IPC to the worker's typed transport, keeps the event loop alive while the
 * worker is idle, and hard-kills the process on parent `disconnect` or — via
 * the off-main-thread {@link startParentWatchdog} — parent exit.
 */
async function runIpcSubprocessWorker<In, Out>(
	start: (transport: {
		send(message: Out): void;
		sendAndFlush(message: Out): Promise<void>;
		onMessage(handler: (message: In) => void): () => void;
	}) => void,
	options?: {
		/**
		 * Rethrow send failures while the IPC channel is still connected instead
		 * of shutting down. A connected-channel failure means this particular
		 * message could not be serialized (e.g. a JS eval cell passed a function
		 * into tool args, a DataCloneError under advanced serialization) — the
		 * caller must see that error, exactly as Worker `postMessage` would
		 * deliver it, rather than losing the whole worker and its state.
		 * Channel-gone failures still shut down.
		 */
		rethrowConnectedSendErrors?: boolean;
	},
): Promise<void> {
	const { promise: shuttingDown, resolve: shutdown } = Promise.withResolvers<void>();
	type IpcSend = (this: NodeJS.Process, message: unknown, callback?: (error: Error | null) => void) => boolean;
	// `process.send` only exists when spawned with an IPC channel; the parent
	// always spawns us that way. If it's missing, the parent vanished and
	// there's no one to talk to.
	const ipcSend = (): IpcSend | undefined => (process as NodeJS.Process & { send?: IpcSend }).send;
	if (!ipcSend()) {
		// Intentional fall-through: shutdown() only resolves the promise;
		// the await + SIGKILL tail below is what actually exits.
		shutdown();
	}
	const send = (message: Out): void => {
		const sender = ipcSend();
		if (!sender) {
			shutdown();
			return;
		}
		try {
			sender.call(process, message);
		} catch (error) {
			if (options?.rethrowConnectedSendErrors && process.connected) throw error;
			shutdown();
		}
	};
	const sendAndFlush = (message: Out): Promise<void> => {
		const sender = ipcSend();
		if (!sender) {
			shutdown();
			return Promise.resolve();
		}
		const { promise, resolve } = Promise.withResolvers<void>();
		try {
			sender.call(process, message, () => resolve());
		} catch {
			shutdown();
			resolve();
		}
		return promise;
	};
	start({
		send,
		sendAndFlush,
		onMessage(handler) {
			const wrap = (data: unknown): void => handler(data as In);
			process.on("message", wrap);
			return () => {
				process.off("message", wrap);
			};
		},
	});
	const initialParentPid = process.ppid;
	if (process.platform === "win32" && initialParentPid <= 0) {
		shutdown();
	} else if (initialParentPid > 0) {
		startParentWatchdog(initialParentPid);
	}
	const keepalive = setInterval(() => {}, 2 ** 30);
	// Parent went away (crashed, SIGKILL, etc.) — commit suicide so we don't
	// linger as an orphan. SIGKILL via `process.kill` keeps us symmetrical with
	// the parent's hard-kill on shutdown: skip every JS/native finalizer.
	process.on("disconnect", () => shutdown());
	try {
		await shuttingDown;
	} finally {
		clearInterval(keepalive);
	}
	process.kill(process.pid, "SIGKILL");
}

/**
 * Hidden subcommand that boots the ONNX tiny-model worker for one model over
 * stdin/stdout; the daemon's `infer` units host it, shared by every omp
 * process on the machine. It exists so `onnxruntime-node` (loaded transitively by
 * `@huggingface/transformers`) never runs in an omp address space — its NAPI
 * finalizer segfaults Bun on Windows (issue #1606).
 */
async function runTinyWorker(): Promise<void> {
	const { startTinyWorkerFromEnvironment } = await import("./tiny/worker");
	await startTinyWorkerFromEnvironment();
}

/** Resolved top-level command name (never its arguments), for the unsettled-entry report. */
let runningCommand: string | undefined;

/** Run the CLI with the given argv (no `process.argv` prefix). */
export async function runCli(argv: string[]): Promise<void> {
	// `omp zsh|bash|sh [args...]`: the whole argv belongs to the shell (`--help`,
	// `--profile`, `-c` included), so it dispatches before profile bootstrap,
	// prepaint, network setup and the command table.
	if (isNativeShell(argv[0])) {
		await runNativeShell(argv);
	}
	// A shell process (a named service, a pty command): the argv after the
	// selector is its own, its command's flags included, so it dispatches
	// before anything reads flags out of it.
	if (argv[0] === SHELL_PROCESS_SELECTOR) {
		// Command boundary: only shell processes load the engine entry here.
		const { runShellProcess } = await import("./exec/shell-process-worker");
		await runShellProcess(argv.slice(1));
	}
	let resolvedArgv = argv;
	try {
		const extracted = extractProfileFlags(resolvedArgv);
		resolvedArgv = extracted.argv;
		if (extracted.profile !== undefined) {
			setProfile(extracted.profile);
		} else {
			// No explicit --profile: activate any OMP_PROFILE/PI_PROFILE inherited
			// from the environment. Module-load resolution deliberately swallows an
			// invalid value to avoid an uncaught throw before this try/catch is in
			// scope (see `readProfileFromEnvSafe` in dirs.ts), and callers may set
			// OMP_PROFILE after importing this module (profile aliases/tests). Surfacing
			// validation here turns `OMP_PROFILE=.. omp --version` into a clean error;
			// calling setProfile keeps every later path helper on the env-selected
			// profile instead of the default agent directory.
			setProfile(resolveProfileEnv(process.env.OMP_PROFILE, process.env.PI_PROFILE));
		}
		if (extracted.aliasName !== undefined) {
			// Command boundary: shell/path setup is used only by --alias.
			const { installProfileAlias, resolveProfileAliasCommandFromProcess } = await import("./cli/profile-alias");
			const profile = extracted.profile ?? getActiveProfile();
			if (!profile) {
				throw new Error("--alias requires --profile <name> or OMP_PROFILE");
			}
			const result = await installProfileAlias({
				profile,
				aliasName: extracted.aliasName,
				command: resolveProfileAliasCommandFromProcess(),
			});
			process.stdout.write(
				`Created ${result.aliasName} for profile ${result.profile} in ${result.configPath}\n` +
					`Restart your shell or run: ${result.reloadedWith}\n` +
					`Then use: ${result.aliasName} update, ${result.aliasName} --version, or ${result.aliasName}\n`,
			);
			return;
		}
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		process.stderr.write(`Error: ${message}\n`);
		process.exitCode = 1;
		return;
	}

	// Declare this module as the worker-host entry now that the active profile
	// is resolved. The worker-host module is side-effect-free; importing
	// `@oh-my-pi/pi-utils/env` here would snapshot the wrong agent `.env`.
	// Gated on `isProcessEntry`: only the real CLI process entry is a valid
	// worker host. Worker-thread re-entry has `!Bun.isMainThread` (isProcessEntry === false),
	// and importers (`runCli` in profile-CLI tests, SDK embedding) have `import.meta.main === false`
	// — declaring there would poison `workerHostEntry()` for the whole test process, forcing eval/stats/
	// browser workers onto the same-realm inline fallback.
	// This must run before worker selector dispatch so that worker subprocesses
	// (e.g. stats activity) are registered as hosts and can themselves spawn worker threads.
	if (isProcessEntry) declareWorkerHostEntry();

	// Worker-thread entry dispatch must run before the first `await`: the
	// stats sync worker's buffering onmessage handler is installed in the
	// synchronous prefix of `runWorkerEntrypoint`, and Bun flushes the
	// worker's parked initial messages as soon as the entry module's
	// top-level evaluation finishes.
	if (isWorkerHostSelector(resolvedArgv[0])) {
		// Invoke dispatch first so its inbox is installed before asynchronous
		// process-name setup yields; neither dependency belongs in prepaint.
		const [dispatched] = await Promise.all([runWorkerEntrypoint(resolvedArgv[0]), setFullProcessName()]);
		if (!dispatched) {
			process.stderr.write(`Error: unknown worker selector: ${resolvedArgv[0]}\n`);
			process.exitCode = 1;
		}
		return;
	}

	// The user waits on this process (startup, typing, redraws), not on its
	// workers: on macOS its main thread runs above the default class a busy
	// machine's builds compete in.
	if (isProcessEntry) raiseInteractiveQos();

	if (resolvedArgv[0] === "--license") {
		// Command boundary: bundled notices are read only when requested.
		const { formatLicenseOutput } = await import("./cli/license");
		process.stdout.write(formatLicenseOutput());
		return;
	}
	const helpOrVersion =
		resolvedArgv[0] === "--help" ||
		resolvedArgv[0] === "-h" ||
		resolvedArgv[0] === "--version" ||
		resolvedArgv[0] === "-v" ||
		resolvedArgv[0] === "help";
	// Before any store opens (the prepaint composer's cache included): SQLite's POSIX
	// locks would be released by any other close of the same file in this process
	// (issue #15586); OFD locks are not. Help and version open no store and load no addon.
	// A failed install is reported once the launch has a warning sink (`main.ts`,
	// `ensureSqliteLockShim`); this module stays free of pi-utils' env snapshot.
	if (isProcessEntry && !helpOrVersion) installSqliteLockShim();
	let stopStartupComposer: (() => void) | undefined;
	if (
		!process.env.PI_TIMING &&
		process.stdin.isTTY === true &&
		process.stdout.isTTY === true &&
		resolvedArgv.every(arg => PREPAINT_SAFE_FLAGS[arg] === true)
	) {
		// Intentional exception to the static-import convention: this latency boundary
		// keeps the TUI graph out of worker, subcommand, help, and version launches.
		// Loading it statically would erase the measured cold-start improvement.
		const { beginStartupComposer, stopPendingStartupComposer } = await import("./modes/startup-composer");
		beginStartupComposer({ version: VERSION });
		stopStartupComposer = stopPendingStartupComposer;
	}

	// The speculative composer owns stdin before either loader yields, so input
	// typed during initialization stays buffered. Neither graph is needed to
	// produce that frame.
	await Promise.all([setFullProcessName(), helpOrVersion ? Promise.resolve() : installNetworkBootstrap()]);

	if (resolvedArgv[0] === "--smoke-test") {
		await runSmokeTest();
		return;
	}

	try {
		const [{ run }, { commands, resolveCliArgv }] = await Promise.all([
			import("@oh-my-pi/pi-utils/cli"),
			import("./cli-commands"),
		]);
		// --help and --version are handled by run() directly; --license returned above.
		// Everything else that isn't a known subcommand routes to "launch".
		const resolved = resolveCliArgv(resolvedArgv);
		if ("error" in resolved) {
			process.stderr.write(`error: ${resolved.error}\n`);
			process.exitCode = 1;
			return;
		}
		runningCommand = resolved.argv[0];
		await run({ bin: APP_NAME, version: VERSION, argv: resolved.argv, commands, metadataHelp: showHelp });
	} finally {
		stopStartupComposer?.();
	}
}

// Floating call instead of top-level await: TLA forces `--bytecode` (CJS
// lowering) builds to fail, and the entrypoint needs nothing after this.
// The catch mirrors what an unhandled TLA rejection produced: error dump to
// stderr, exit code 1. A settled entry leaves the exit code to the command. An
// entry still pending when the event loop drains (an await that can never
// settle) exits 1 with a diagnostic: TLA would have hung there, and a bare
// floating call exits 0 as if the command had succeeded.
// Guarded so importing `runCli` (profile CLI tests, SDK embedding) does not
// launch the agent as a side effect. Worker threads re-enter this module as
// their entry with `import.meta.main === false`, so the worker-host dispatch
// is admitted via `!Bun.isMainThread`.
if (isProcessEntry || !Bun.isMainThread) {
	const postmortem: typeof Postmortem = require("@oh-my-pi/pi-utils/postmortem.js");
	postmortem.installProcessHandlers();
	// A one-shot CLI run (`omp --help | head`, `omp --version | true`, `omp <sub> | grep -m1`)
	// whose stdout consumer closes before the write drains gets an EPIPE that Bun surfaces as
	// an unhandled rejection. Treat a vanished stdout peer as an ordinary Unix disconnect
	// (graceful exit) rather than the fatal path. Interactive launches register their own
	// terminal lifetime; help/version/subcommand launches never start one. See #10930. The
	// registration lives for the process — a one-shot entry exits right after runCli settles.
	postmortem.registerStdioDisconnectHandling();
	const entry = runCli(process.argv.slice(2));
	postmortem.reportUnsettledEntry(entry, () => runningCommand);
	entry.catch(async error => {
		// Failure boundary: inspector/postmortem is irrelevant to successful startup.
		const { fatal } = await import("@oh-my-pi/pi-utils/postmortem");
		fatal(error);
	});
}

