/**
 * Durable ownership registry for targets in the project-shared daemon-owned
 * Chromium (`omp.browser.headless`/`omp.browser.headed`).
 *
 * The shared browser outlives any single omp process, but tab ownership is
 * otherwise tracked only in that process's memory (`tab-supervisor`'s `tabs`
 * map). When a session ends abnormally (crash, SIGKILL, cleanup timeout) its
 * in-process map dies with it and the pages it opened stay open in the shared
 * Chromium forever, accumulating into multi-GB orphan targets (issue #10022).
 *
 * This module records, on disk under the daemon runtime dir, which OS process
 * created each shared-browser page target. Any live omp process can then reap
 * targets whose owning process is gone. It only ever touches OMP-owned
 * targets: shared-browser pages and tabs omp itself created through the
 * browser relay (`relay/owned-targets.ts`). Borrowed relay tabs and
 * connected/spawned browsers are never recorded.
 *
 * Ownership is authoritative in the safe direction: a target is reaped only
 * when its owner PID reports `ESRCH` (definitively dead). A live PID is never
 * reaped, so a live session's tabs cannot be yanked out from under it; the
 * worst case (recycled PID) leaves an orphan uncollected rather than closing a
 * live page.
 */
import * as fs from "node:fs/promises";
import * as path from "node:path";
import { getDaemonRuntimeDir, isEnoent, isPidAlive, logger, untilAborted } from "@oh-my-pi/pi-utils";
import type { Browser, CDPSession, Connection } from "puppeteer-core";
import { browserConnection } from "./launch";

/** Identifies one shared-browser daemon's target registry. */
export interface SharedTargetScope {
	/** Canonical project directory whose scope holds the browser unit (as stamped on the handle). */
	projectDir: string;
	/** Key of the browser's `proc` unit, e.g. `omp.browser.headless`. */
	daemonName: string;
	/** Registry parent dir; defaults to the project's daemon runtime dir. Machine-global daemons (browser relay) pass their own. */
	runtimeDir?: string;
}

/** On-disk ownership record: one file per owning omp process. */
interface OwnershipFile {
	pid: number;
	updatedAt: number;
	targets: string[];
}

/**
 * Reap only records whose owner has been dead AND untouched for this long.
 * The PID probe is already authoritative; the grace window is a conservative
 * guard against clock skew and PID reuse races, and keeps a just-crashed
 * process's very fresh records around briefly in case it is being restarted.
 */
const DEFAULT_GRACE_MS = 15_000;

/** Re-send cadence and overall budget of {@link closeSharedTargetUntilGone}. */
const RECLOSE_INTERVAL_MS = 2_000;
const RECLOSE_BUDGET_MS = 30_000;
/** Per-target budget of {@link retryUnclosedSharedTargets}, so a sweep over many targets stays bounded. */
const RETRY_CLOSE_BUDGET_MS = 5_000;

/** In-process set of shared-browser targets this process created, keyed by registry dir. */
const ownedByDir = new Map<string, Set<string>>();
/** Owned targets whose close this process could not confirm, keyed by registry dir. */
const unclosedByDir = new Map<string, Set<string>>();
/** In-flight {@link retryUnclosedSharedTargets} run per registry dir. */
const unclosedRetries = new Map<string, Promise<number>>();
/** Per-registry-dir write serialization so concurrent record/forget can't tear the file. */
const writeChains = new Map<string, Promise<void>>();

function registryDir(scope: SharedTargetScope): string {
	return path.join(scope.runtimeDir ?? getDaemonRuntimeDir(scope.projectDir), `${scope.daemonName}.targets`);
}

/** Serialize a write against others for the same registry dir. */
function chain(dir: string, task: () => Promise<void>): Promise<void> {
	const prev = writeChains.get(dir) ?? Promise.resolve();
	const next = prev.then(task, task);
	writeChains.set(
		dir,
		next.catch(() => undefined),
	);
	return next;
}

/** Persist (or, when empty, remove) this process's ownership file for a registry dir. */
async function flush(dir: string): Promise<void> {
	const owned = ownedByDir.get(dir);
	const file = path.join(dir, `${process.pid}.json`);
	if (!owned || owned.size === 0) {
		await fs.rm(file, { force: true }).catch(() => undefined);
		return;
	}
	const record: OwnershipFile = { pid: process.pid, updatedAt: Date.now(), targets: [...owned] };
	const tmp = `${file}.${process.pid}.tmp`;
	await fs.mkdir(dir, { recursive: true });
	await Bun.write(tmp, JSON.stringify(record));
	await fs.rename(tmp, file);
}

/** Record that this process created `targetId` in the given shared browser. */
export async function recordSharedTarget(scope: SharedTargetScope, targetId: string): Promise<void> {
	const dir = registryDir(scope);
	let owned = ownedByDir.get(dir);
	if (!owned) {
		owned = new Set();
		ownedByDir.set(dir, owned);
	}
	owned.add(targetId);
	await chain(dir, () => flush(dir)).catch(err =>
		logger.debug("Failed to record shared-browser target ownership", {
			error: err instanceof Error ? err.message : String(err),
		}),
	);
}

/** Drop `targetId` from this process's ownership file (closed the normal way). */
export async function forgetSharedTarget(scope: SharedTargetScope, targetId: string): Promise<void> {
	const dir = registryDir(scope);
	unclosedByDir.get(dir)?.delete(targetId);
	const owned = ownedByDir.get(dir);
	if (!owned?.delete(targetId)) return;
	await chain(dir, () => flush(dir)).catch(err =>
		logger.debug("Failed to update shared-browser target ownership", {
			error: err instanceof Error ? err.message : String(err),
		}),
	);
}

/**
 * Drop every target this process still claims in `scope`. For when the whole
 * shared browser is confirmed gone — the daemon reported its browser unit in a
 * terminal state after a stop — which takes the targets that could not be
 * closed with it; the records are dead weight that would otherwise be
 * rewritten on every later write until this process exits. Only call this on
 * that confirmation: while the browser lives, the records are the only handle
 * a later reap has on its orphaned targets.
 */
export async function forgetSharedTargets(scope: SharedTargetScope): Promise<void> {
	const dir = registryDir(scope);
	unclosedByDir.delete(dir);
	const owned = ownedByDir.get(dir);
	if (!owned || owned.size === 0) return;
	owned.clear();
	await chain(dir, () => flush(dir)).catch(err =>
		logger.debug("Failed to clear shared-browser target ownership", {
			error: err instanceof Error ? err.message : String(err),
		}),
	);
}

/** Options for {@link collectOrphanTargets}; the defaults hit the real registry, the seams are for tests. */
export interface CollectOrphanOptions {
	/** Wall clock; injectable for deterministic grace-window tests. */
	now?: () => number;
	/** PID liveness probe; injectable so tests need no real subprocesses. */
	isAlive?: (pid: number) => boolean;
	/** Grace window in ms before a dead owner's records are eligible. */
	graceMs?: number;
}

/** Targets belonging to one dead process, kept grouped so partial failures remain retryable. */
export interface OrphanOwner {
	file: string;
	pid: number;
	updatedAt: number;
	targetIds: string[];
}

/** Orphan-scan result grouped by durable ownership file. */
export interface OrphanScan {
	owners: OrphanOwner[];
}

/**
 * Scan a registry dir for targets whose owning process is gone. Returns one
 * entry per dead owner so a reaper can retain only targets whose CDP closure
 * was not confirmed. This process's own file and every live-owner file are
 * left untouched.
 */
export async function collectOrphanTargets(
	scope: SharedTargetScope,
	opts: CollectOrphanOptions = {},
): Promise<OrphanScan> {
	const now = opts.now ?? Date.now;
	const isAlive = opts.isAlive ?? isPidAlive;
	const graceMs = opts.graceMs ?? DEFAULT_GRACE_MS;
	const dir = registryDir(scope);
	let entries: string[];
	try {
		entries = await fs.readdir(dir);
	} catch (err) {
		if (isEnoent(err)) return { owners: [] };
		throw err;
	}
	const owners: OrphanOwner[] = [];
	const nowMs = now();
	for (const entry of entries) {
		if (!entry.endsWith(".json")) continue;
		const file = path.join(dir, entry);
		let record: OwnershipFile;
		try {
			record = (await Bun.file(file).json()) as OwnershipFile;
		} catch {
			continue; // torn or malformed file; a live owner will rewrite it
		}
		if (typeof record?.pid !== "number" || !Array.isArray(record.targets)) continue;
		if (record.pid === process.pid) continue; // our own file
		if (isAlive(record.pid)) continue; // owner still running
		if (nowMs - (record.updatedAt ?? 0) < graceMs) continue; // conservative grace
		owners.push({
			file,
			pid: record.pid,
			updatedAt: record.updatedAt,
			targetIds: record.targets.filter(id => typeof id === "string"),
		});
	}
	return { owners };
}

/**
 * How long {@link closeCdpTarget} waits by default for Chromium to destroy a target whose close it accepted.
 * Past it the close counts as unconfirmed, as a failed one does.
 */
const CLOSE_CONFIRM_TIMEOUT_MS = 5_000;

/**
 * Close a page target by id on the browser's root connection. Returns true only
 * when CDP reports the target destroyed or confirms it no longer exists; a
 * dropped connection or transient protocol failure returns false so durable
 * ownership remains available for a later retry. Never throws.
 *
 * A browser-target session per call would race: overlapping ones make puppeteer
 * lose the browser target (puppeteer#15750). Puppeteer enables target discovery
 * on the root connection when it connects, so `Target.targetDestroyed` arrives there.
 *
 * `Target.closeTarget` answers `success` once Chromium has started closing the
 * page, not once it is gone: the target stays listed until its renderer has
 * unloaded it. Its `Target.targetDestroyed` confirms the close instead, as it
 * does for Puppeteer's own `page.close()`.
 *
 * A caller that bounds the whole close MUST pass a `confirmTimeoutMs` well below
 * its budget, so a missed `targetDestroyed` still leaves time for the
 * `Target.getTargets` absence check to decide the result.
 */
export async function closeCdpTarget(
	browser: Browser,
	targetId: string,
	confirmTimeoutMs = CLOSE_CONFIRM_TIMEOUT_MS,
): Promise<boolean> {
	let connection: Connection;
	try {
		connection = browserConnection(browser);
	} catch {
		return false;
	}
	const destroyed = Promise.withResolvers<boolean>();
	const onDestroyed = (event: { targetId: string }): void => {
		if (event.targetId === targetId) destroyed.resolve(true);
	};
	connection.on("Target.targetDestroyed", onDestroyed);
	let timer: NodeJS.Timeout | undefined;
	try {
		try {
			const result = await connection.send("Target.closeTarget", { targetId });
			if (result.success) {
				timer = setTimeout(() => destroyed.resolve(false), confirmTimeoutMs);
				if (await destroyed.promise) return true;
			}
		} catch {
			// A concurrent reaper or the page itself may already have closed the
			// target. Confirm absence before treating the cleanup as complete.
		}
		try {
			const { targetInfos } = await connection.send("Target.getTargets");
			return !targetInfos.some(info => info.targetId === targetId);
		} catch {
			return false;
		}
	} finally {
		clearTimeout(timer);
		connection.off("Target.targetDestroyed", onDestroyed);
	}
}

/**
 * {@link closeCdpTarget} for the omp relay, over a channel that answers browser-level `Target.*`
 * commands. The relay's `Target.getTargets` lists only tabs it can drive right now, not those of a
 * disconnected browser or with a dismissed debugger, so absence is read from `Target.getTargetInfo`:
 * it looks the id up among every tab the extensions reported, and answers an unknown id with the
 * browser target.
 */
export async function closeRelayTarget(channel: Pick<CDPSession, "send">, targetId: string): Promise<boolean> {
	try {
		const result = await channel.send("Target.closeTarget", { targetId });
		if (result.success) return true;
	} catch {
		// Closed already (the worker's own close), or the extension cannot answer.
	}
	try {
		const { targetInfo } = await channel.send("Target.getTargetInfo", { targetId });
		return targetInfo.targetId !== targetId;
	} catch {
		return false;
	}
}

/** Bounds of {@link closeSharedTargetUntilGone}. */
interface CloseUntilGoneOptions {
	/** Give up (returning false) after this long; default 30 s. */
	budgetMs?: number;
	/** Re-send interval while the target is still listed; default 2 s. */
	intervalMs?: number;
}

/**
 * Confirms a web search page's close like {@link closeCdpTarget} (#16680). Chromium can answer
 * `success: true` and keep the page, so the close is re-sent every `intervalMs` while the target
 * is listed. Returns false once `budgetMs` elapses or the connection drops; never throws.
 */
export async function closeSharedTargetUntilGone(
	browser: Browser,
	targetId: string,
	opts: CloseUntilGoneOptions = {},
): Promise<boolean> {
	const intervalMs = opts.intervalMs ?? RECLOSE_INTERVAL_MS;
	const stop = AbortSignal.timeout(opts.budgetMs ?? RECLOSE_BUDGET_MS);
	let connection: Connection;
	try {
		connection = browserConnection(browser);
	} catch {
		return false;
	}
	const destroyed = Promise.withResolvers<true>();
	const onDestroyed = (event: { targetId: string }): void => {
		if (event.targetId === targetId) destroyed.resolve(true);
	};
	connection.on("Target.targetDestroyed", onDestroyed);
	try {
		// A closed connection rejects every send at once; stop rather than spin to the budget.
		while (!stop.aborted && browser.connected) {
			const round = AbortSignal.any([stop, AbortSignal.timeout(intervalMs)]);
			// Sent outright, not under `round`: a stalled Chromium outlasts rounds, and a skipped send never closes.
			// The reply proves nothing: success can leave the page open; an error may mean it went.
			void connection.send("Target.closeTarget", { targetId }).catch(() => {});
			// Answered after the close, so it also settles a target already gone, or one whose event was missed.
			const unlisted = connection.send("Target.getTargets").then(
				reply => (reply.targetInfos.some(info => info.targetId === targetId) ? destroyed.promise : true),
				() => (browser.connected ? destroyed.promise : false),
			);
			if (await untilAborted(round, Promise.race([destroyed.promise, unlisted])).catch(() => false)) return true;
		}
		return false;
	} finally {
		connection.off("Target.targetDestroyed", onDestroyed);
	}
}

/** Mark a target whose close went unconfirmed for retry while this process lives; the reaper skips live owners. */
export function markSharedTargetUnclosed(scope: SharedTargetScope, targetId: string): void {
	const dir = registryDir(scope);
	let unclosed = unclosedByDir.get(dir);
	if (!unclosed) {
		unclosed = new Set();
		unclosedByDir.set(dir, unclosed);
	}
	unclosed.add(targetId);
}

/**
 * Retry the closes marked for `scope`, forgetting confirmed ones.
 * Returns the count closed; never throws. Concurrent calls for a scope share one run.
 */
export function retryUnclosedSharedTargets(browser: Browser, scope: SharedTargetScope): Promise<number> {
	const dir = registryDir(scope);
	const inFlight = unclosedRetries.get(dir);
	if (inFlight) return inFlight;
	const run = retryUnclosed(browser, scope, dir);
	unclosedRetries.set(dir, run);
	void run.finally(() => {
		if (unclosedRetries.get(dir) === run) unclosedRetries.delete(dir);
	});
	return run;
}

async function retryUnclosed(browser: Browser, scope: SharedTargetScope, dir: string): Promise<number> {
	const pending = unclosedByDir.get(dir);
	if (!pending || pending.size === 0) return 0;
	let closed = 0;
	// Iterate live, not a snapshot: overlapping searches share this run, so ids they mark mid-sweep
	// must be tried too. Set iteration reaches entries added during it and skips forgotten ones.
	for (const targetId of pending) {
		const gone = await closeSharedTargetUntilGone(browser, targetId, { budgetMs: RETRY_CLOSE_BUDGET_MS });
		if (!gone) {
			logger.debug("Shared-browser target still open after retried close", { targetId });
			continue;
		}
		closed++;
		await forgetSharedTarget(scope, targetId);
	}
	if (closed > 0) logger.debug("Closed lingering shared-browser targets", { count: closed, daemon: scope.daemonName });
	return closed;
}

/** Atomically retain unresolved targets, or remove an ownership file once all are resolved. */
async function updateOwnershipFile(owner: OrphanOwner, targetIds: string[]): Promise<void> {
	if (targetIds.length === 0) {
		await fs.rm(owner.file, { force: true });
		return;
	}
	const tmp = `${owner.file}.${process.pid}.tmp`;
	try {
		const record: OwnershipFile = { pid: owner.pid, updatedAt: owner.updatedAt, targets: targetIds };
		await Bun.write(tmp, JSON.stringify(record));
		await fs.rename(tmp, owner.file);
	} catch (error) {
		await fs.rm(tmp, { force: true }).catch(() => undefined);
		throw error;
	}
}

/**
 * Reap shared-browser targets whose owning omp process is gone. Each owner
 * file is removed only after every target is confirmed closed/absent; partial
 * failures atomically retain the unresolved ids for the next attach to retry.
 * Failures are logged, never thrown, so cleanup cannot block browser open.
 */
export async function reapOrphanSharedTargets(
	browser: Browser,
	scope: SharedTargetScope,
	closeTarget: (targetId: string) => Promise<boolean> = targetId => closeCdpTarget(browser, targetId),
): Promise<number> {
	let scan: OrphanScan;
	try {
		scan = await collectOrphanTargets(scope);
	} catch (err) {
		logger.debug("Failed to scan shared-browser target registry", {
			error: err instanceof Error ? err.message : String(err),
		});
		return 0;
	}
	let closed = 0;
	for (const owner of scan.owners) {
		const retained: string[] = [];
		for (const targetId of owner.targetIds) {
			if (await closeTarget(targetId)) {
				closed++;
			} else {
				retained.push(targetId);
				logger.debug("Retaining orphaned shared-browser target for retry", { targetId, ownerPid: owner.pid });
			}
		}
		if (retained.length === owner.targetIds.length) continue;
		try {
			await updateOwnershipFile(owner, retained);
		} catch (err) {
			logger.debug("Failed to update shared-browser ownership after reap", {
				ownerPid: owner.pid,
				error: err instanceof Error ? err.message : String(err),
			});
		}
	}
	if (closed > 0) logger.debug("Reaped orphaned shared-browser targets", { count: closed, daemon: scope.daemonName });
	return closed;
}

/** Test-only reset of the in-process ownership state. */
export function resetOrphanRegistryForTest(): void {
	ownedByDir.clear();
	unclosedByDir.clear();
	unclosedRetries.clear();
	writeChains.clear();
}

import * as path from "node:path";
import { isCompiledBinary, logger, untilAborted, workerHostEntry } from "@oh-my-pi/pi-utils";
import type { Subprocess } from "bun";
import type { Browser, CDPSession } from "puppeteer-core";
import { ToolAbortError } from "../tool-errors";
import { ToolError } from "@oh-my-pi/pi-tui/tools/tool-errors";
import { findFreeCdpPort, findReusableCdp, gracefulKillTreeOnce, resolveSpawnArgs, waitForCdp } from "./attach";
import { type CmuxKind, CmuxUnavailableError } from "./cmux/rpc";
import { CmuxSocketClient } from "./cmux/socket-client";
import {
	BROWSER_PROTOCOL_TIMEOUT_MS,
	closeLaunchedBrowser,
	connectPuppeteer,
	DEFAULT_VIEWPORT,
	launchHeadlessBrowser,
	loadPuppeteer,
	removeUserDataDir,
	type UserAgentOverride,
} from "./launch";
import { reapOrphanSharedTargets, type SharedTargetScope } from "./orphan-registry";
import { ensureRelayDaemon, isLoopbackRelayUrl, restartRelayDaemon } from "./relay/daemon";
import { closeRelayOwnedTarget, relayTargetScope } from "./relay/owned-targets";
import type { RelayKind } from "./relay/kind";
import { UPDATE_RELAY_EXTENSION, waitForRelayExtension } from "./relay/probe";
import { ensureSharedBrowser } from "./shared-daemon";
import type { TernKind } from "./tern/kind";
import { TernSocketClient } from "./tern/wire";
import type { UnitLease } from "./unit-lease";
import { WebKitHost } from "./webkit/host";
import type { WebKitKind } from "./webkit/kind";

export type PuppeteerBrowserKind =
	| {
			kind: "headless";
			headless: boolean;
			/** Process-local launch flag; shared browsers use the tab-scoped CDP override instead. */
			insecure?: boolean;
	  }
	| { kind: "spawned"; path: string; args?: string[] }
	| { kind: "connected"; cdpUrl: string }
	| RelayKind;

export type BrowserKind = PuppeteerBrowserKind | CmuxKind | TernKind | WebKitKind;

export type BrowserKindTag = BrowserKind["kind"];

interface BrowserHandleCommon {
	key: string;
	kind: BrowserKind;
	refCount: number;
}

export interface PuppeteerBrowserHandle extends BrowserHandleCommon {
	kind: PuppeteerBrowserKind;
	browser: Browser;
	/** Browser-level WebSocket endpoint tab workers attach through. */
	wsEndpoint: string;
	cdpUrl?: string;
	/** The browser's main process, which owns its windows on screen; unknown for connected endpoints and the relay. */
	pid?: number;
	/** OMP-owned temp Chromium profile directory removed on dispose (process-local headless launches). */
	userDataDir?: string;
	/** Daemon unit backing this handle; dispose disconnects instead of closing, kill routes to the daemon. */
	sharedDaemon?: { name: string; projectDir: string };
	/** Lease on the daemon unit (shared Chromium or relay) this handle uses; released on dispose. */
	daemonLease?: UnitLease;
	subprocess?: Subprocess;
	stealth: { browserSession: CDPSession | null; override: UserAgentOverride | null };
}

export interface CmuxBrowserHandle extends BrowserHandleCommon {
	kind: CmuxKind;
	client: CmuxSocketClient;
	surface?: string;
}

/** A connection to the Tern daemon whose browser PiPs host this handle's tabs. */
export interface TernBrowserHandle extends BrowserHandleCommon {
	kind: TernKind;
	/** The daemon connection every tab of this handle drives its PiP through. */
	tern: TernSocketClient;
}

/** omp's own WebKit host process, whose headless web views (one block each) are this handle's tabs. */
export interface WebKitBrowserHandle extends BrowserHandleCommon {
	kind: WebKitKind;
	/** The host process omp started and stops with the handle. */
	webkit: WebKitHost;
}

export type BrowserHandle = PuppeteerBrowserHandle | CmuxBrowserHandle | TernBrowserHandle | WebKitBrowserHandle;

/**
 * Durable-ownership scope for a browser handle, or undefined when the handle is
 * not the project-shared daemon-supervised Chromium (the only browser whose targets
 * outlive their creating process and thus need cross-process orphan reaping).
 */
export function sharedTargetScopeOf(handle: BrowserHandle): SharedTargetScope | undefined {
	if (!("browser" in handle)) return undefined;
	if (handle.kind.kind !== "headless" || !handle.sharedDaemon) return undefined;
	return { projectDir: handle.sharedDaemon.projectDir, daemonName: handle.sharedDaemon.name };
}

/** Controls bounded browser-handle teardown and identifies the owning resource in timeout diagnostics. */
export interface ReleaseBrowserOptions {
	kill: boolean;
	timeoutMs?: number;
	resource?: string;
}

const browsers = new Map<string, BrowserHandle>();
/**
 * In-flight opens by browser key, so concurrent acquisitions share one launch instead of storming Chromium.
 * `settled` resolves once the open settles or its caller aborts, whichever comes first.
 */
const pendingOpens = new Map<string, { settled: Promise<void> }>();

export function browserKey(kind: BrowserKind): string {
	switch (kind.kind) {
		case "headless":
			return `headless:${kind.headless ? "1" : "0"}:${kind.insecure ? "tls" : ""}`;
		case "spawned":
			return `spawned:${JSON.stringify([kind.path, kind.args ?? []])}`;
		case "connected":
			return `connected:${kind.cdpUrl}`;
		case "relay":
			return `relay:${kind.cdpUrl}`;
		case "cmux":
			return `cmux:${kind.socketPath}`;
		case "tern":
			return `tern:${kind.socketPath}:${kind.pane}`;
		case "webkit":
			return `webkit:${kind.path}`;
	}
}

export interface AcquireBrowserOptions {
	cwd: string;
	viewport?: { width: number; height: number; deviceScaleFactor?: number };
	signal?: AbortSignal;
	/** Start, or replace an outdated, loopback relay daemon when a relay is not serving. Default true. */
	startRelay?: boolean;
}

export async function acquireBrowser(kind: BrowserKind, opts: AcquireBrowserOptions): Promise<BrowserHandle> {
	if (kind.kind === "spawned") kind = { ...kind, args: resolveSpawnArgs(kind.path, kind.args, opts.cwd) };
	const key = browserKey(kind);
	for (;;) {
		const existing = browsers.get(key);
		if (existing) {
			if ("client" in existing) return existing;
			if (
				"tern" in existing
					? existing.tern.connected
					: "webkit" in existing
						? existing.webkit.client.connected
						: existing.browser.connected
			) {
				return existing;
			}
			browsers.delete(key);
			await disposeBrowserHandle(existing, { kill: false });
			continue;
		}
		// Short-circuit before launching: the tool wrapper's `untilAborted` only
		// rejects its outer promise on abort; without this check `openBrowserHandle`
		// would still fire and its result would land in `browsers` below.
		if (opts.signal?.aborted) throw new ToolAbortError("Browser open aborted");

		// Single-flight per key: a concurrent caller already opening this browser
		// wins; everyone else waits and re-reads the registry. Without this, N
		// simultaneous opens each launch a Chromium and the last write wins,
		// leaking the rest as unreferenced process trees.
		const pending = pendingOpens.get(key);
		if (pending) {
			await untilAborted(opts.signal, () => pending.settled);
			continue;
		}
		const open = openBrowserHandle(kind, opts);
		const settled = Promise.withResolvers<void>();
		const entry = { settled: settled.promise };
		// An open whose caller aborted is disposed below, never published, so it
		// stops being this key's single flight the moment its caller gives up:
		// waiters start a fresh attempt instead of waiting out a launch or connect
		// that may never return. Only the registered entry is removed, so a late
		// settlement cannot drop a replacement already in flight. A spawned app
		// keeps its key until its abandoned open has been disposed: that kills
		// the app, which a fresh attempt could otherwise adopt as a reusable endpoint.
		const clearEntry = () => {
			opts.signal?.removeEventListener("abort", clearEntry);
			if (pendingOpens.get(key) === entry) pendingOpens.delete(key);
			settled.resolve();
		};
		if (kind.kind !== "spawned") opts.signal?.addEventListener("abort", clearEntry, { once: true });
		pendingOpens.set(key, entry);
		let handle: BrowserHandle;
		try {
			handle = await open;
		} catch (error) {
			clearEntry();
			throw error;
		}
		// The launch may resolve AFTER the caller has already aborted (the outer
		// `untilAborted` rejects immediately on abort but does not cancel the
		// inner promise, and `launchHeadlessBrowser` does not accept a signal).
		// Without this branch the completed handle sits in `browsers` at
		// refCount:0 forever — no tab ever takes a hold, `releaseBrowser` never
		// fires, and `releaseAllTabs` walks `tabs`, not `browsers`, so the
		// orphaned Chromium/app process / puppeteer handle survives to process
		// exit. (Issue #3963.)
		if (opts.signal?.aborted) {
			await disposeBrowserHandle(handle, { kill: kind.kind === "spawned" }).catch(err => {
				logger.debug("Failed to dispose orphan browser after abort", {
					error: err instanceof Error ? err.message : String(err),
				});
			});
			clearEntry();
			throw new ToolAbortError("Browser open aborted");
		}
		browsers.set(key, handle);
		clearEntry();
		return handle;
	}
}

export function normalizeConnectedCdpUrl(rawCdpUrl: string): string {
	const cdpUrl = rawCdpUrl.replace(/\/+$/, "");
	if (/^wss?:\/\//i.test(cdpUrl)) {
		throw new ToolError(
			"browser app CDP URL must be the HTTP CDP discovery endpoint (for example http://127.0.0.1:9222), not a ws:// browser websocket URL.",
		);
	}
	return cdpUrl;
}

async function openBrowserHandle(kind: BrowserKind, opts: AcquireBrowserOptions): Promise<BrowserHandle> {
	if (kind.kind === "cmux") {
		const client = new CmuxSocketClient({ socketPath: kind.socketPath, password: kind.password });
		await client.connect().catch((error: unknown) => {
			if (error instanceof ToolError && !(error instanceof ToolAbortError)) {
				throw new CmuxUnavailableError(error.message);
			}
			throw error;
		});
		return {
			key: browserKey(kind),
			kind,
			client,
			surface: kind.surface,
			refCount: 0,
		};
	}
	if (kind.kind === "tern") {
		const tern = new TernSocketClient({ socketPath: kind.socketPath });
		await tern.connect();
		return { key: browserKey(kind), kind, tern, refCount: 0 };
	}
	if (kind.kind === "webkit") {
		return {
			key: browserKey(kind),
			kind,
			webkit: await WebKitHost.launch(kind.path, kind.viewer, opts.signal),
			refCount: 0,
		};
	}
	if (kind.kind === "headless") {
		// Every real omp process (session, subagent, worker — anything with a CLI
		// worker host) MUST go through the project-shared daemon-supervised Chromium:
		// per-process launches are what produced launch storms and orphaned
		// process trees. The process-local launch survives only for hosts that
		// cannot spawn the omp daemon (bun test, SDK embedding without a CLI entry).
		if (isCompiledBinary() || workerHostEntry() !== null) {
			return await openSharedHeadlessHandle(kind, opts);
		}
		const { browser, wsEndpoint, userDataDir } = await launchHeadlessBrowser({
			headless: kind.headless,
			viewport: opts.viewport,
			insecure: kind.insecure,
		});
		return {
			key: browserKey(kind),
			kind,
			browser,
			wsEndpoint,
			pid: browser.process()?.pid,
			userDataDir,
			refCount: 0,
			stealth: { browserSession: null, override: null },
		};
	}
	if (kind.kind === "connected") {
		const cdpUrl = normalizeConnectedCdpUrl(kind.cdpUrl);
		await waitForCdp(cdpUrl, 5_000, opts.signal);
		const puppeteer = await loadPuppeteer();
		const browser = await connectPuppeteer(puppeteer, {
			browserURL: cdpUrl,
			defaultViewport: null,
			protocolTimeout: BROWSER_PROTOCOL_TIMEOUT_MS,
		});
		return {
			key: browserKey(kind),
			kind,
			browser,
			wsEndpoint: browser.wsEndpoint(),
			cdpUrl,
			refCount: 0,
			stealth: { browserSession: null, override: null },
		};
	}
	if (kind.kind === "relay") {
		const cdpUrl = normalizeConnectedCdpUrl(kind.cdpUrl);
		// Loopback relays are global daemon units, auto-started on demand (the
		// extension dials in on its own). Hosts without a CLI worker entry
		// (bun test, SDK embedding) never start them. Remote relay URLs must
		// already be serving.
		const autoStart =
			opts.startRelay !== false && isLoopbackRelayUrl(cdpUrl) && (isCompiledBinary() || workerHostEntry() !== null);
		let lease = autoStart ? await ensureRelayDaemon({ cdpUrl, signal: opts.signal }) : null;
		try {
			// The relay answers /json/version with 503 until its extension dials in;
			// the wait fails fast when nothing serves the port or the server has
			// already outlived the window an installed extension needs to connect.
			let outcome = await waitForRelayExtension(cdpUrl, opts.signal);
			// A daemon-supervised relay outlives omp upgrades; replace an incompatible
			// one with this version's once, and a compatible older one only while no
			// CDP client uses it. A manually started relay is left to its owner.
			if (outcome === "outdated-relay" && autoStart) {
				const restart = await restartRelayDaemon({ cdpUrl, lease, signal: opts.signal });
				lease = restart.lease;
				if (restart.restarted) outcome = await waitForRelayExtension(cdpUrl, opts.signal);
			} else if (outcome === "idle-older-relay" && autoStart) {
				// Probe again even when it was kept: another omp may have replaced it since.
				lease = (await restartRelayDaemon({ cdpUrl, lease, signal: opts.signal, idleOnly: true })).lease;
				outcome = await waitForRelayExtension(cdpUrl, opts.signal);
			}
			if (outcome === "unreachable") {
				throw new ToolError(
					`omp browser relay is not reachable at ${cdpUrl}. Start it with \`omp browser-relay\` (or check the endpoint), and make sure the OMP Browser Relay extension is loaded in Chrome.`,
				);
			}
			if (outcome === "no-extension") {
				throw new ToolError(
					`omp browser relay is serving at ${cdpUrl} but its extension never connected. Install it with \`omp browser-relay install\` and check the toolbar badge shows "on".`,
				);
			}
			if (outcome === "extension-gone") {
				throw new ToolError(
					`omp browser relay is serving at ${cdpUrl} but its extension disconnected and has not come back. Open Chrome with the OMP Browser Relay extension and check the toolbar badge shows "on".`,
				);
			}
			if (outcome === "outdated-relay") {
				throw new ToolError(
					`The browser relay at ${cdpUrl} is out of date. Restart the relay under this OMP version, then retry.`,
				);
			}
			if (outcome === "outdated-extension") {
				throw new ToolError(`The OMP Browser Relay extension is out of date. ${UPDATE_RELAY_EXTENSION}`);
			}
			const puppeteer = await loadPuppeteer();
			const browser = await connectPuppeteer(puppeteer, {
				browserURL: cdpUrl,
				defaultViewport: null,
				protocolTimeout: BROWSER_PROTOCOL_TIMEOUT_MS,
			});
			// Use the new daemon lease path and reap only proven OMP-owned targets.
			const wsEndpoint = browser.wsEndpoint();
			void reapOrphanSharedTargets(browser, relayTargetScope(cdpUrl), targetId =>
				closeRelayOwnedTarget(wsEndpoint, targetId),
			);
			return {
				key: browserKey(kind),
				kind,
				browser,
				wsEndpoint,
				cdpUrl,
				daemonLease: lease ?? undefined,
				refCount: 0,
				stealth: { browserSession: null, override: null },
			};
		} catch (err) {
			await lease?.release();
			throw err;
		}
	}

	const exe = kind.path;
	if (!path.isAbsolute(exe)) {
		throw new ToolError(
			`app must be an absolute executable path (got ${JSON.stringify(exe)}). Pass the binary inside Foo.app/Contents/MacOS/, not the .app bundle.`,
		);
	}
	const appArgs = kind.args ?? [];
	const reused = await findReusableCdp(exe, { signal: opts.signal, appArgs });
	let cdpUrl: string;
	let pid: number;
	let subprocess: Subprocess | undefined;
	if (reused) {
		logger.debug("Reusing existing CDP endpoint for attach", { exe, pid: reused.pid, cdpUrl: reused.cdpUrl });
		cdpUrl = reused.cdpUrl;
		pid = reused.pid;
	} else {
		const port = await findFreeCdpPort();
		const launchArgs = [...appArgs, `--remote-debugging-port=${port}`];
		const child = Bun.spawn([exe, ...launchArgs], {
			cwd: opts.cwd,
			stdout: "ignore",
			stderr: "ignore",
			stdin: "ignore",
		});
		child.unref();
		subprocess = child;
		pid = child.pid;
		cdpUrl = `http://127.0.0.1:${port}`;
		try {
			await waitForCdp(cdpUrl, 30_000, opts.signal);
		} catch (err) {
			await gracefulKillTreeOnce(child.pid).catch(() => undefined);
			if (err instanceof ToolAbortError) throw err;
			if (err instanceof Error && err.name === "AbortError") throw err;
			throw new ToolError(`Failed to attach to ${path.basename(exe)} on ${cdpUrl}: ${(err as Error).message}`);
		}
	}

	const puppeteer = await loadPuppeteer();
	let browser: Browser;
	try {
		browser = await connectPuppeteer(puppeteer, {
			browserURL: cdpUrl,
			defaultViewport: null,
			protocolTimeout: BROWSER_PROTOCOL_TIMEOUT_MS,
		});
	} catch (err) {
		if (subprocess) await gracefulKillTreeOnce(subprocess.pid);
		throw new ToolError(`Connected to ${cdpUrl} but puppeteer.connect failed: ${(err as Error).message}`);
	}
	return {
		key: browserKey(kind),
		kind,
		browser,
		wsEndpoint: browser.wsEndpoint(),
		cdpUrl,
		pid,
		subprocess,
		refCount: 0,
		stealth: { browserSession: null, override: null },
	};
}

export function holdBrowser(handle: BrowserHandle): void {
	handle.refCount++;
}

export async function releaseBrowser(handle: BrowserHandle, opts: ReleaseBrowserOptions): Promise<void> {
	handle.refCount = Math.max(0, handle.refCount - 1);
	if (handle.refCount === 0) {
		// Only evict if the registry still points at THIS handle. After a disconnect,
		// `acquireBrowser` may have already replaced the entry with a fresh live handle
		// under the same key; deleting blindly would orphan that new browser.
		if (browsers.get(handle.key) === handle) browsers.delete(handle.key);
		await disposeBrowserHandle(handle, opts);
	}
}

async function disposeBrowserHandle(handle: BrowserHandle, opts: ReleaseBrowserOptions): Promise<void> {
	if ("client" in handle) {
		handle.client.close();
		return;
	}
	if ("tern" in handle) {
		handle.tern.close();
		return;
	}
	if ("webkit" in handle) {
		// The host is omp's own process whoever asked: it stops with its last tab, `kill` or not.
		await handle.webkit.close();
		return;
	}
	if (handle.kind.kind === "headless") {
		if (handle.sharedDaemon) {
			// The daemon owns the Chromium; this process only drops its CDP
			// connection and its lease. `kill` is scoped to spawned-app browsers —
			// stopping the shared unit here would tear down every other session's
			// tabs. Chrome dies shortly after the last omp client in the project
			// releases its lease (unit idle policy), when its CDP endpoint stops
			// answering after a failed tab cleanup
			// (`stopSharedBrowserIfUnreachable`), or via an explicit stop
			// (`write proc://<name>/kill`).
			if (handle.browser.connected) {
				try {
					handle.browser.disconnect();
				} catch (err) {
					logger.debug("Failed to disconnect from shared browser", { error: (err as Error).message });
				}
			}
			await handle.daemonLease?.release();
			return;
		}
		if (handle.browser.connected) {
			await closeLaunchedBrowser({ browser: handle.browser, userDataDir: handle.userDataDir });
		}
		// OMP owns the profile directory (puppeteer's temp cleanup is disabled by
		// our explicit --user-data-dir), so remove it now the process tree has
		// exited. Tolerant of the Windows lock-held window (issue #7058).
		if (handle.userDataDir) await removeUserDataDir(handle.userDataDir);
		return;
	}
	// Connected and relay browsers belong to the user: drop our CDP link, never kill.
	if (handle.kind.kind === "connected" || handle.kind.kind === "relay") {
		if (handle.browser.connected) {
			try {
				handle.browser.disconnect();
			} catch (err) {
				logger.debug("Failed to disconnect from remote browser", { error: (err as Error).message });
			}
		}
		await handle.daemonLease?.release();
		return;
	}
	if (handle.browser.connected) {
		try {
			handle.browser.disconnect();
		} catch (err) {
			logger.debug("Failed to disconnect from spawned browser", { error: (err as Error).message });
		}
	}
	// A discovered CDP PID is borrowed, not ours to kill on close or abort.
	if (opts.kill && handle.subprocess && handle.subprocess.exitCode === null) {
		await gracefulKillTreeOnce(handle.subprocess.pid);
	}
}

/**
 * Attach to the project-shared daemon-supervised Chromium. Failures surface as
 * `ToolError` — a CLI-host process never silently falls back to a private
 * Chromium, so a broken daemon cannot quietly recreate per-process launch
 * storms.
 */
async function openSharedHeadlessHandle(
	kind: Extract<PuppeteerBrowserKind, { kind: "headless" }>,
	opts: AcquireBrowserOptions,
): Promise<PuppeteerBrowserHandle> {
	const vp = opts.viewport ?? DEFAULT_VIEWPORT;
	let lease: UnitLease | undefined;
	try {
		const shared = await ensureSharedBrowser({
			projectDir: opts.cwd,
			headless: kind.headless,
			viewport: vp,
			signal: opts.signal,
		});
		lease = shared.lease;
		const puppeteer = await loadPuppeteer();
		const browser = await connectPuppeteer(puppeteer, {
			browserWSEndpoint: shared.wsEndpoint,
			defaultViewport: kind.headless
				? {
						width: vp.width,
						height: vp.height,
						deviceScaleFactor: vp.deviceScaleFactor ?? DEFAULT_VIEWPORT.deviceScaleFactor,
					}
				: null,
			protocolTimeout: BROWSER_PROTOCOL_TIMEOUT_MS,
		});
		// Attaching to the shared daemon is the natural point to sweep targets
		// left behind by omp processes that died without teardown — bounds
		// accumulation without a background timer. Best-effort and detached so a
		// slow reap never delays the open (issue #10022).
		void reapOrphanSharedTargets(browser, { projectDir: shared.projectDir, daemonName: shared.daemonName });
		return {
			key: browserKey(kind),
			kind,
			browser,
			wsEndpoint: shared.wsEndpoint,
			pid: shared.pid,
			sharedDaemon: { name: shared.daemonName, projectDir: shared.projectDir },
			daemonLease: shared.lease,
			refCount: 0,
			stealth: { browserSession: null, override: null },
		};
	} catch (err) {
		await lease?.release();
		if (err instanceof ToolAbortError || err instanceof ToolError) throw err;
		if (opts.signal?.aborted) throw new ToolAbortError("Browser open aborted");
		throw new ToolError(`Shared browser attach failed: ${err instanceof Error ? err.message : String(err)}`);
	}
}

/** Test-only accessor for the module-global browsers map. */
export function getBrowsersMapForTest(): ReadonlyMap<string, BrowserHandle> {
	return browsers;
}

/**
 * CDP façade over `chrome.debugger`.
 *
 * Puppeteer clients (the omp browser tool: one supervisor connection plus one
 * per tab worker) connect to this bridge as if it were Chrome's browser
 * debugging endpoint. Chrome only allows a single debugger attachment per tab,
 * so the bridge owns ONE `chrome.debugger` attachment per tab (via the
 * extension) and multiplexes every downstream connection over it with minted
 * per-connection session ids.
 *
 * Emulated surface (everything else is forwarded to `chrome.debugger`):
 * - the browser target (`/json/version` handshake, `Browser.getVersion`)
 * - the `Target.*` domain, including puppeteer's tab → page auto-attach
 *   hierarchy (see puppeteer-core `cdp/ExtensionTransport.ts`, the reference
 *   implementation for this emulation)
 *
 * Session id namespaces seen by a downstream connection:
 * - minted tab pseudo-sessions (`ST<tab>.<conn>.<n>`) — Target emulation only
 * - minted page pseudo-sessions (`SP<tab>.<conn>.<n>`) — forwarded to the
 *   tab's root debugger session
 * - real child session ids (OOPIFs, workers) — created by Chrome under the
 *   shared root session and passed through verbatim
 */
import { createHash } from "node:crypto";
import { VERSION } from "@oh-my-pi/pi-utils/dirs";
import { BROWSER_PAGE_PROTOCOL_TIMEOUT_MS } from "../launch";
import {
	DISCARDED_TABS_PROTOCOL_VERSION,
	EXTENSION_RELOAD_PROTOCOL_VERSION,
	isHiddenFrame,
	isOlderOmpVersion,
	isOmpVersion,
} from "./protocol";
import type { ExtToRelayMessage, HiddenFrame, RelayRpcRequest, RelayToExtMessage, TabSnapshot } from "./protocol";

/** Transport-agnostic websocket surface the bridge writes to. */
export interface RelaySocket {
	send(text: string): void;
	close(): void;
}

interface CdpCommand {
	id: number;
	method: string;
	params?: Record<string, unknown>;
	sessionId?: string;
}

/**
 * Per-pseudo-session Runtime domain state.
 * - `default`: never toggled Runtime — still receives the relay's legacy
 *   root-event fan-out, so omp's own patched-puppeteer client (which
 *   pull-acquires contexts and never sends `Runtime.enable`) keeps getting
 *   `Runtime.executionContextCreated`.
 * - `enabled`: ran `Runtime.enable`; gets the existing-context replay.
 * - `disabled`: explicitly ran `Runtime.disable`; silenced until it re-enables.
 */
type RuntimeState = "default" | "enabled" | "disabled";

/**
 * CDP `{ enabled }` switches Chrome keeps per debugger session. Every relay session of a tab shares one attachment,
 * which outlives them, so the bridge keeps a switch on while any session asks for it and turns it off once none does.
 */
const TAB_WIDE_SWITCHES = ["Page.setInterceptFileChooserDialog", "Emulation.setFocusEmulationEnabled"] as const;
type TabWideSwitch = (typeof TAB_WIDE_SWITCHES)[number];

function isTabWideSwitch(method: string): method is TabWideSwitch {
	return (TAB_WIDE_SWITCHES as readonly string[]).includes(method);
}

interface SessionRef {
	kind: "tab" | "page";
	/** Registry key of the owning tab (`<instance code>:<chrome tabId>`). */
	tabKey: string;
	tabId: number;
	runtimeState: RuntimeState;
	/** Context ids already announced to this pseudo-session. */
	readonly runtimeContexts: Set<number>;
	/** In-flight `Runtime.enable` for this session; duplicates await it. */
	runtimeEnabling: Promise<void> | null;
	/** Monotonic ownership token for enable rollback and replay. */
	runtimeEpoch: number;
	/** Sent `Target.setAutoAttach`; only such a session is told about real child targets. */
	autoAttach: boolean;
	/** Tab-wide switches ({@link TAB_WIDE_SWITCHES}) this session turned on. */
	readonly switches: Set<TabWideSwitch>;
}

interface TargetInfo {
	targetId: string;
	type: "tab" | "page" | "browser";
	title: string;
	url: string;
	attached: boolean;
	canAccessOpener: boolean;
}

class CdpConnection {
	discover = false;
	autoAttach = false;
	/** Minted pseudo-sessions owned by this connection. */
	readonly sessions = new Map<string, SessionRef>();
	/** Tabs this connection claimed as drive targets (`/cdp?claim=` / `Target.createTarget`). */
	readonly claims = new Set<string>();
	/** Real child session id → the session it was announced on; its events and detach go there. */
	readonly childParents = new Map<string, string>();
	readonly explicitChildren = new Set<string>();

	constructor(
		readonly id: number,
		readonly socket: RelaySocket,
	) {}

	sessionsForTab(tabKey: string, kind?: "tab" | "page"): string[] {
		const out: string[] = [];
		for (const [sessionId, ref] of this.sessions) {
			if (ref.tabKey === tabKey && (!kind || ref.kind === kind)) out.push(sessionId);
		}
		return out;
	}

	/** This tab's first page session that armed auto-attach; one per connection so no child is announced twice. */
	childTargetSessionForTab(tabKey: string): string | undefined {
		for (const [sessionId, ref] of this.sessions) {
			if (ref.tabKey === tabKey && ref.kind === "page" && ref.autoAttach) return sessionId;
		}
		return undefined;
	}
}

/** Transport replacement is retryable and must not permanently ban a tab. */
class ExtensionReplacedError extends Error {}

/**
 * Rewrites the files of the extension Chrome knows as `extensionId` to this omp's, when that is the copy this relay
 * may update; resolves whether the files on disk are now this omp's (then the bridge asks the extension to reload).
 */
export type RelayBridgeExtensionUpdater = (extensionId: string) => Promise<boolean>;

/** A connected extension browser instance; one per browser/profile. */
interface ExtInstance {
	instanceId: string;
	/** Short code derived from the instance id and browser run; names target ids (`TAB<code>.<tabId>`). */
	code: string;
	socket: RelaySocket | null;
	info: {
		userAgent: string;
		browserVersion: string;
		discardedTabsProtocol?: number;
		ompVersion?: string;
		reloadProtocol?: number;
		downloadsProtocol?: number;
		ownershipReported: boolean;
	} | null;
	/** Chrome extension id from the socket's `Origin`; null when the upgrade carried none. */
	extensionId: string | null;
	/** The relay is rewriting this extension's files to reload it: not ready meanwhile (its socket closes after). */
	updating: boolean;
	/** `Date.now()` when its socket closed; null while connected. */
	goneSince: number | null;
	/** Settles at its next hello; created by the first caller that waits for one. */
	reconnected: PromiseWithResolvers<void> | null;
}

/**
 * Deterministic per-instance code for target ids: stable across relay restarts and service-worker restarts, new
 * after a browser restart (when Chrome reuses tab ids). Older extensions send no browser session.
 */
function instanceCode(instanceId: string, browserSession: string): string {
	const identity = browserSession ? `${instanceId}/${browserSession}` : instanceId;
	return createHash("sha256").update(identity).digest("base64url").slice(0, 8);
}

function tabKeyOf(extCode: string, tabId: number): string {
	return `${extCode}:${tabId}`;
}

function tabTargetIdFromKey(key: string): string {
	return `TAB${key.replace(":", ".")}`;
}

function pageTargetIdFromKey(key: string): string {
	return `PAGE${key.replace(":", ".")}`;
}

function parseTargetId(targetId: string): { key: string; kind: "tab" | "page" } | null {
	const match = /^(TAB|PAGE)([^.]+)\.(\d+)$/.exec(targetId);
	if (!match) return null;
	const kind: "tab" | "page" = match[1] === "TAB" ? "tab" : "page";
	return { key: `${match[2]}:${match[3]}`, kind };
}

class TabState {
	/** Assigned in the constructor body from the owning instance. */
	readonly tabKey: string;
	url: string;
	title: string;
	active: boolean;
	/** Discarded tabs cannot answer debugger calls. */
	discarded: boolean;
	windowId: number;
	pinned: boolean;
	/** Chrome tab group id from the last snapshot; -1 when ungrouped. */
	groupId: number;
	/** Whether `chrome.debugger` is currently attached to this tab. */
	attached = false;
	/**
	 * Why Chrome refused omp this tab (its attach error, or the user cancelling the debugger bar); while set the
	 * tab is not adoptable. Cleared on navigation.
	 */
	refusal: string | undefined;
	/** Whether targets for this tab were announced to discovering connections. */
	announced = false;
	attaching: Promise<boolean> | null = null;
	/** Discard cancels the waiter but keeps the extension RPC alive for late cleanup. */
	attachCancelled = false;
	attachGeneration = 0;
	cancelAttach: (() => void) | null = null;
	/** Retry when a revived tab's canceled attach request finally settles. */
	retryAttachAfterDiscard = false;
	/** Relay-initiated detach in flight; reattach serializes behind it. */
	detaching: Promise<void> | null = null;
	/** A successful attach completed after the most recently requested relay detach. */
	reattachedAfterDetach = false;
	/** The relay asked the extension to close this tab (`Target.closeTarget`); its coming detach is not Chrome's own. */
	closing = false;
	closeAttempt: Promise<void> | null = null;
	/** Tab-wide switches whose last change never reached the extension (its socket was down or the send failed). */
	readonly unsettledSwitches = new Set<TabWideSwitch>();
	/** True after the relay put this tab in the omp group; `ompGroupId` holds that group. */
	grouped = false;
	/** Group RPC in flight — suppresses duplicate requests from load-time tabUpdated bursts. */
	grouping = false;
	ompGroupId: number | undefined;
	/** Normalized session label for omp-owned tab grouping. */
	label?: string;
	/** Creator's temporary claim; the worker that owns this new tab takes it over. */
	provisionalClaimConnId?: number;
	/** User pulled the tab out of the omp group — never re-group it. */
	groupOptOut = false;
	/** The app in front of the user when omp's input last reached this tab, and when; a window the tab opens uses it once. */
	frontAtInput: { app: FrontApp; at: number } | null = null;
	/**
	 * The extension created this tab for omp in the current browser session
	 * (hello `ownedTabIds`, or `Target.createTarget` here). The orphan reaper
	 * closes only such tabs, so a stale record whose tab id Chrome reused after
	 * a restart can never close a user tab.
	 */
	ompCreated = false;
	/**
	 * Real Chrome sessions (OOPIF/worker children) under this tab's attachment: the child session
	 * that reported each (none for the root) and its `Target.attachedToTarget` params.
	 */
	readonly realSessions = new Map<string, { parent: string | undefined; event: Record<string, unknown> }>();
	/** Live execution contexts from the shared root debugger session. */
	readonly runtimeContexts = new Map<number, Record<string, unknown>>();
	/** Whether the shared root Runtime domain has been enabled by the bridge. */
	rootRuntimeEnabled = false;
	rootRuntimeEnabling: Promise<void> | null = null;
	/** Invalidates an in-flight Runtime enable when the debugger detaches. */
	runtimeGeneration = 0;
	/** Settled by the next detach Chrome reports on its own (not one the relay requested). */
	chromeDetach = Promise.withResolvers<void>();
	/**
	 * Other extensions' frames the extension hid in this tab, held until a worker driving it takes them
	 * (`OMP.takeHiddenFrames`): when it adopts the tab, or with the result of the run during which the relay told it
	 * (`OMP.foreignFramesHidden`). Chrome's detach ends a worker's sessions on the tab, so the one that re-adopts it
	 * takes what the last one could not.
	 */
	hiddenFrames: HiddenFrame[] = [];

	constructor(
		readonly instanceId: string,
		readonly extCode: string,
		readonly tabId: number,
		snap: TabSnapshot,
	) {
		this.tabKey = tabKeyOf(extCode, tabId);
		this.url = snap.url;
		this.title = snap.title;
		this.active = snap.active;
		this.discarded = snap.discarded;
		this.windowId = snap.windowId;
		this.pinned = snap.pinned;
		this.groupId = snap.groupId;
	}

	update(snap: TabSnapshot): void {
		this.url = snap.url;
		this.title = snap.title;
		this.active = snap.active;
		this.discarded = snap.discarded;
		this.windowId = snap.windowId;
		this.pinned = snap.pinned;
		this.groupId = snap.groupId;
	}
}

/** URLs `chrome.debugger` cannot attach to; hidden from downstream discovery entirely. */
const INELIGIBLE_URL = /^(chrome|devtools|edge|view-source|chrome-extension|chrome-untrusted|chrome-search):/i;

const RPC_TIMEOUT_MS = 20_000;
/** How long after its timeout a late RPC result is still undone; a wedged extension must not grow the map forever. */
const LATE_RPC_KEEP_MS = 60_000;
const CDP_ERROR_METHOD_NOT_FOUND = -32601;
const CDP_ERROR_SERVER = -32000;
/**
 * How long a new tab waits for the browser it belongs in (that of `nearTargetId` or of a tab the client drives) to
 * reconnect after its socket closed: the extension's longest reconnect backoff (10 s) plus its hello.
 */
const AFFINE_RECONNECT_WAIT_MS = 12_000;
/** Chrome's answer to a command in flight when it ends the debugger attachment. */
const DETACHED_COMMAND_ERROR = /Detached while handling command/;
/** How long such a failure waits for the extension to report the detach itself. */
const CHROME_DETACH_REPORT_MS = 1_000;
/** {@link RelayBridge.#rpc}'s failure when the extension sent no answer within the deadline. */
class RpcTimeoutError extends Error {}
/**
 * Deadline for a command whose answer waits on the page itself (a promise it settles, a navigation it commits),
 * where {@link RPC_TIMEOUT_MS} is for one Chrome answers at once. omp's own clients give up at
 * `BROWSER_PAGE_PROTOCOL_TIMEOUT_MS`, as on a launched Chrome; the relay waits a little longer so their error, not the
 * relay's, reaches the call.
 */
const PAGE_BOUND_RPC_TIMEOUT_MS = BROWSER_PAGE_PROTOCOL_TIMEOUT_MS + 5_000;
/** A window a tab opens this long after omp's input reached it is still taken to be that input's doing. */
const POPUP_AFTER_INPUT_MS = 1_000;
/** How long the user's app is held in front after omp's input opened a window; Chrome activates within milliseconds. */
const KEEP_FRONT_MS = 500;
/**
 * omp's CDP inputs a page can open a window on, by method and event `type`: those that give the page user activation
 * (a button or key going down, a release, a tap). Moves, wheels, key-ups and inserted text never do, so they read no
 * front app. `true`: every event of that method.
 */
const WINDOW_OPENING_INPUT: Record<string, Record<string, true> | true> = {
	"Input.dispatchMouseEvent": { mousePressed: true, mouseReleased: true },
	"Input.emulateTouchFromMouseEvent": { mousePressed: true, mouseReleased: true },
	"Input.dispatchKeyEvent": { keyDown: true, rawKeyDown: true },
	"Input.dispatchTouchEvent": { touchStart: true, touchEnd: true },
	"Input.synthesizeTapGesture": true,
};

function canOpenWindow(method: string, params: Record<string, unknown> | undefined): boolean {
	if (!Object.hasOwn(WINDOW_OPENING_INPUT, method)) return false;
	const types = WINDOW_OPENING_INPUT[method];
	const type = params?.type;
	return types === true || (typeof type === "string" && Object.hasOwn(types, type));
}

/** The app in front of the user, as `macOSFrontApp` from `@oh-my-pi/pi-natives` reads it. */
export interface FrontApp {
	/** Puts the app back in front each time the app that took the front takes it again within `durationMs`, until the user picks an app; resolves how many times. */
	keepInFront(durationMs: number): Promise<number>;
}

/**
 * Multiplexing CDP bridge between downstream puppeteer connections and the
 * relay extension. One instance per relay server; all state lives here so an
 * extension service-worker restart only has to re-handshake.
 */
export class RelayBridge {
	/** Tab registries keyed by `<instance code>:<chrome tabId>`; one namespace per browser instance. */
	#tabs = new Map<string, TabState>();
	#conns = new Map<number, CdpConnection>();
	#connSeq = 0;
	#sessionSeq = 0;
	#rpcSeq = 0;
	/** Connected extension browser instances, keyed by stable instance id. */
	#instances = new Map<string, ExtInstance>();
	#socketInstance = new Map<RelaySocket, string>();
	/** Chrome extension id each extension socket's upgrade named in its `Origin`. */
	#socketExtensionId = new Map<RelaySocket, string>();
	/** Rewrites the files of the extension with this id to this omp's; resolves whether it did (see {@link RelayBridgeExtensionUpdater}). */
	#updateExtension: RelayBridgeExtensionUpdater | null;
	/** Per instance, the extension versions the relay already reloaded it from: never twice from the same one. */
	#updateTried = new Map<string, Set<string>>();
	/** Instance whose hello ran last: answers browser-wide requests and owns created tabs. */
	#lastHelloInstance: string | null = null;
	#extensionSeen = false;
	/**
	 * Tabs omp opened whose close failed while their browser was offline (see {@link #closeTab}), by tab key, with
	 * the URL the tab showed: closed at that browser's next hello, unless the tab is gone or shows another page.
	 */
	#closeOnHello = new Map<string, string>();
	#retiredCodes = new Set<string>();
	/** `Date.now()` when the last ready extension socket closed; null while one is ready or none ever was. */
	#extensionGoneSince: number | null = null;
	#pendingRpc = new Map<
		string,
		{ resolve: (value: unknown) => void; reject: (err: Error) => void; timer: NodeJS.Timeout }
	>();
	/**
	 * Timed-out RPCs whose late success still needs undoing (a tab Chrome created after omp gave up), by
	 * `instance:id`.
	 */
	#lateRpc = new Map<string, { onResult: (result: unknown) => void; timer: NodeJS.Timeout }>();
	/** Real child session id → owning tab key, learned from `Target.attachedToTarget` events. */
	#realSessionTabs = new Map<string, string>();
	#log: (message: string, data?: Record<string, unknown>) => void;
	/** Tab-group appearance for driven tabs; null disables grouping. */
	#group: { title: string; color: string } | null;
	/** Tabs awaiting the next group RPC; drained one batch at a time. */
	#groupQueue: TabState[] = [];
	/** True while {@link #drainGroupQueue} runs — group RPCs must never overlap. */
	#groupDraining = false;
	/** Each tab switch's last transition, by `tabKey method`; see {@link #serializeSwitches}. */
	#switchTransitions = new Map<string, Promise<void>>();
	/** Reads the app in front of the user; set by {@link keepFrontAppWith} where the relay can put it back (macOS). */
	#readFrontApp: (() => FrontApp | null) | undefined;
	/**
	 * When the running hold on the user's app ends (`Date.now()` ms), at its deadline or once it settles, whichever is
	 * first; 0 with none. A window opened meanwhile shares it, and omp's input reads no front app then: the browser may
	 * be in front, and a later hold would keep it there.
	 */
	#keepingFrontUntil = 0;

	constructor(
		opts: {
			log?: (message: string, data?: Record<string, unknown>) => void;
			/** Group tabs the agent actively drives under one per-window Chrome tab group. */
			group?: { title: string; color: string } | null;
			/** Enables extension self-update; absent, the relay never rewrites or reloads an extension. */
			updateExtension?: RelayBridgeExtensionUpdater;
		} = {},
	) {
		this.#log = opts.log ?? (() => {});
		this.#group = opts.group ?? null;
		this.#updateExtension = opts.updateExtension ?? null;
	}

	/** True once an extension has completed its hello handshake, and the relay is not rewriting its files. */
	get ready(): boolean {
		for (const inst of this.#instances.values()) {
			if (inst.socket && inst.info && !inst.updating) return true;
		}
		return false;
	}

	/** The instance whose hello ran last (browser-wide requests route there). */
	#lastHello(): ExtInstance | undefined {
		if (this.#lastHelloInstance) {
			const inst = this.#instances.get(this.#lastHelloInstance);
			if (inst?.socket) return inst;
		}
		for (const inst of this.#instances.values()) {
			if (inst.socket) return inst;
		}
		return undefined;
	}

	/**
	 * The browser the caller's tabs live in: the one named by `nearTargetId` (a tab the caller drives on another
	 * connection; omp gives every tab its own), else one holding a tab this connection drives. Offline or not.
	 */
	#affineInstance(conn: CdpConnection, nearTargetId: unknown): ExtInstance | undefined {
		const near = typeof nearTargetId === "string" ? parseTargetId(nearTargetId) : null;
		if (near) {
			// The target id names its browser even after the user closed that tab.
			const code = near.key.slice(0, near.key.indexOf(":"));
			const inst = [...this.#instances.values()].find(inst => inst.code === code);
			if (inst) return inst;
		}
		const own = [...conn.claims].map(key => this.#tabs.get(key)).find(tab => tab !== undefined);
		return own && this.#instances.get(own.instanceId);
	}

	/** Wait for an offline browser's hello, up to {@link AFFINE_RECONNECT_WAIT_MS} after its socket closed. */
	async #awaitReconnect(inst: ExtInstance): Promise<void> {
		if (inst.socket || inst.goneSince === null) return;
		const left = inst.goneSince + AFFINE_RECONNECT_WAIT_MS - Date.now();
		if (left <= 0) return;
		inst.reconnected ??= Promise.withResolvers<void>();
		const timeout = Promise.withResolvers<void>();
		const timer = setTimeout(timeout.resolve, left);
		try {
			await Promise.race([inst.reconnected.promise, timeout.promise]);
		} finally {
			clearTimeout(timer);
		}
	}

	/**
	 * The browser a new tab opens in: the caller's ({@link #affineInstance}), else the one showing the first selected
	 * tab (the tab an open without a target used to adopt), else the last hello, so a reconnecting extension's hello
	 * does not move new tabs to another browser.
	 */
	#instanceForNewTab(affine: ExtInstance | undefined): ExtInstance | undefined {
		if (affine?.socket) return affine;
		for (const tab of this.#tabs.values()) {
			if (!tab.active || tab.discarded || !this.#eligible(tab)) continue;
			const inst = this.#instances.get(tab.instanceId);
			if (inst?.socket) return inst;
		}
		const last = this.#lastHello();
		if (last && [...this.#tabs.values()].some(tab => tab.instanceId === last.instanceId)) return last;
		for (const inst of this.#instances.values()) {
			if (inst.socket && [...this.#tabs.values()].some(tab => tab.instanceId === inst.instanceId)) return inst;
		}
		return last;
	}

	/** True after the first hello, and stays true: separates a reaped service worker from an absent extension. */
	get extensionSeen(): boolean {
		return this.#extensionSeen;
	}

	/** Milliseconds since the last ready extension disconnected, or null while one is connected or none ever was. */
	get extensionGoneForMs(): number | null {
		return this.#extensionGoneSince === null ? null : Date.now() - this.#extensionGoneSince;
	}

	/** Downstream CDP clients (omp browser sessions, puppeteer) connected right now. */
	get cdpClientCount(): number {
		return this.#conns.size;
	}

	/** Payload for `GET /json/version`. */
	versionInfo(wsUrl: string): Record<string, string | number> {
		const info = this.#lastHello()?.info;
		let hasCompatibleExtension = false;
		// The oldest connected extension's installing omp, so a current browser cannot hide a stale one.
		// A stamp of unknown age yields to any other, so it cannot hide one either.
		let oldestExtensionOmp: string | undefined;
		for (const instance of this.#instances.values()) {
			if (!instance.socket || instance.info?.discardedTabsProtocol !== DISCARDED_TABS_PROTOCOL_VERSION) continue;
			// Its files are being rewritten; it says which version it runs once it is back.
			if (instance.updating) continue;
			hasCompatibleExtension = true;
			const ompVersion = instance.info.ompVersion ?? "";
			if (
				oldestExtensionOmp === undefined ||
				isOlderOmpVersion(ompVersion, oldestExtensionOmp) ||
				(oldestExtensionOmp !== "" && !isOmpVersion(oldestExtensionOmp))
			) {
				oldestExtensionOmp = ompVersion;
			}
		}
		const ua = info?.userAgent ?? "";
		return {
			Browser: info?.browserVersion ?? "Chrome/unknown",
			"Protocol-Version": "1.3",
			"User-Agent": ua,
			"V8-Version": "",
			"WebKit-Version": "",
			webSocketDebuggerUrl: wsUrl,
			ompRelayVersion: VERSION,
			ompRelayDiscardedTabsProtocol: String(DISCARDED_TABS_PROTOCOL_VERSION),
			ompExtensionDiscardedTabsProtocol: String(hasCompatibleExtension ? DISCARDED_TABS_PROTOCOL_VERSION : 0),
			ompRelayCdpClients: this.#conns.size,
			ompExtensionVersion: oldestExtensionOmp ?? "",
		};
	}

	/** Payload for `GET /json/list` (debugging aid; per-target endpoints are not served). */
	listTargets(): Array<Record<string, string>> {
		const out: Array<Record<string, string>> = [];
		for (const tab of this.#tabs.values()) {
			if (!this.#eligible(tab)) continue;
			out.push({
				id: pageTargetIdFromKey(tab.tabKey),
				type: "page",
				title: tab.title,
				url: tab.url,
				active: String(tab.active),
				discarded: String(tab.discarded),
			});
		}
		return out;
	}

	// ---- extension lifecycle -------------------------------------------------

	#rejectPendingExtensionRpcs(instanceId: string, error: Error): void {
		const prefix = `${instanceId}:`;
		for (const [key, pending] of this.#pendingRpc) {
			if (!key.startsWith(prefix)) continue;
			clearTimeout(pending.timer);
			pending.reject(error);
			this.#pendingRpc.delete(key);
		}
	}

	/**
	 * A new extension socket connected; its hello assigns (or reuses) a browser instance.
	 * `extensionId` is the Chrome extension id its upgrade's `Origin` named, if any.
	 */
	extConnected(socket: RelaySocket, extensionId?: string): void {
		if (extensionId) this.#socketExtensionId.set(socket, extensionId);
		this.#log("extension socket connected");
	}

	extClosed(socket: RelaySocket): void {
		this.#socketExtensionId.delete(socket);
		const instanceId = this.#socketInstance.get(socket);
		if (instanceId === undefined) return;
		this.#socketInstance.delete(socket);
		const inst = this.#instances.get(instanceId);
		if (!inst || inst.socket !== socket) return;
		inst.socket = null;
		inst.goneSince = Date.now();
		inst.updating = false;
		this.#rejectPendingExtensionRpcs(instanceId, new Error("relay extension disconnected"));
		// Keep the instance's tabs listed (the browser may reconnect), but drop
		// debugger state: the attachment died with the service worker.
		for (const tab of this.#tabs.values()) {
			if (tab.instanceId !== instanceId) continue;
			tab.attached = false;
			tab.attaching = null;
			this.#resetRuntime(tab);
			// The extension dissolves omp groups on disconnect (or died along
			// with them); grouping state is unknowable until the next hello.
			tab.grouped = false;
			tab.grouping = false;
			tab.ompGroupId = undefined;
		}
		this.#groupQueue = this.#groupQueue.filter(tab => tab.instanceId !== instanceId);
		if (!this.ready) this.#extensionGoneSince ??= Date.now();
	}

	extMessage(socket: RelaySocket, raw: string): void {
		let msg: ExtToRelayMessage;
		try {
			msg = JSON.parse(raw) as ExtToRelayMessage;
		} catch {
			this.#log("dropping malformed extension message");
			return;
		}
		if (msg.t === "hello") {
			this.#onHello(socket, msg);
			return;
		}
		const instanceId = this.#socketInstance.get(socket);
		if (instanceId === undefined) return;
		const inst = this.#instances.get(instanceId);
		if (!inst || inst.socket !== socket) return;
		switch (msg.t) {
			case "rpcResult": {
				const key = `${instanceId}:${msg.id}`;
				const pending = this.#pendingRpc.get(key);
				if (!pending) {
					const late = this.#lateRpc.get(key);
					if (!late) return;
					this.#lateRpc.delete(key);
					clearTimeout(late.timer);
					if (msg.ok) late.onResult(msg.result);
					if (this.#conns.size === 0) void this.#updateIdleExtensions();
					return;
				}
				this.#pendingRpc.delete(key);
				clearTimeout(pending.timer);
				if (msg.ok) pending.resolve(msg.result);
				else pending.reject(new Error(msg.error ?? "extension rpc failed"));
				return;
			}
			case "cdpEvent":
				this.#onCdpEvent(tabKeyOf(inst.code, msg.tabId), msg.sessionId, msg.method, msg.params);
				return;
			case "detached":
				this.#onTabDetached(tabKeyOf(inst.code, msg.tabId), msg.reason, msg.relayInitiated === true);
				return;
			case "framesHidden":
				this.#onFramesHidden(tabKeyOf(inst.code, msg.tabId), msg.frames);
				return;
			case "tabCreated":
				this.#onTabUpsert(msg.tab, instanceId);
				return;
			case "tabUpdated":
				this.#onTabUpsert(msg.tab, instanceId);
				return;
			case "tabRemoved":
				this.#onTabRemoved(tabKeyOf(inst.code, msg.tabId));
				return;
			case "ping":
				socket.send(JSON.stringify({ t: "pong" } satisfies RelayToExtMessage));
				return;
		}
	}

	#onHello(socket: RelaySocket, msg: Extract<ExtToRelayMessage, { t: "hello" }>): void {
		// Hellos without an instance id (legacy extension builds) share one anon
		// instance and keep the historical latest-wins replacement semantics.
		const instanceId = typeof msg.instanceId === "string" && msg.instanceId.length > 0 ? msg.instanceId : "anon";
		const code = instanceCode(instanceId, typeof msg.browserSession === "string" ? msg.browserSession : "");
		let inst = this.#instances.get(instanceId);
		if (!inst) {
			inst = {
				instanceId,
				code,
				socket: null,
				info: null,
				goneSince: null,
				reconnected: null,
				extensionId: null,
				updating: false,
			};
			this.#instances.set(instanceId, inst);
		} else if (inst.socket && inst.socket !== socket) {
			// Same browser reconnected (service-worker restart): retire the old
			// socket. Debugger-derived state dies with the old attachment, so
			// reset runtime state exactly like the old single-slot replace did;
			// the hello's attachedTabIds reconciliation runs right after.
			for (const tab of this.#tabs.values()) {
				if (tab.instanceId === instanceId) this.#resetRuntime(tab);
			}
			this.#rejectPendingExtensionRpcs(instanceId, new ExtensionReplacedError());
			this.#socketInstance.delete(inst.socket);
			inst.socket.close();
		}
		if (inst.code !== code) {
			this.#retiredCodes.add(inst.code);
			// The browser restarted, and Chrome reuses tab ids: retire the previous run's targets, and the closes
			// queued for them, so an old target id cannot name a tab the user opened since.
			for (const [key, tab] of this.#tabs) {
				if (tab.instanceId === instanceId) this.#onTabRemoved(key);
			}
			for (const key of this.#closeOnHello.keys()) {
				if (key.startsWith(`${inst.code}:`)) this.#closeOnHello.delete(key);
			}
			inst.code = code;
		}
		inst.socket = socket;
		inst.goneSince = null;
		inst.reconnected?.resolve();
		inst.reconnected = null;
		this.#socketInstance.set(socket, instanceId);
		inst.extensionId = this.#socketExtensionId.get(socket) ?? null;
		inst.updating = false;
		inst.info = {
			userAgent: msg.userAgent,
			browserVersion: msg.browserVersion,
			discardedTabsProtocol: msg.discardedTabsProtocol,
			ompVersion: typeof msg.ompVersion === "string" ? msg.ompVersion : undefined,
			reloadProtocol: msg.reloadProtocol,
			downloadsProtocol: msg.downloadsProtocol,
			ownershipReported: Array.isArray(msg.ownedTabIds),
		};
		this.#lastHelloInstance = instanceId;
		this.#extensionSeen = true;
		this.#extensionGoneSince = null;
		// The hello GC is scoped to this instance: another browser's tabs are
		// untouched, which is what lets Chrome and Edge share one relay.
		const seen = new Set<number>();
		const attachedNow = new Set(msg.attachedTabIds);
		const known = new Set<string>();
		for (const tab of this.#tabs.values()) if (tab.instanceId === instanceId) known.add(tab.tabKey);
		for (const snap of msg.tabs) {
			seen.add(snap.tabId);
			this.#onTabUpsert(snap, instanceId, { silent: true });
		}
		for (const [key, tab] of this.#tabs) {
			if (tab.instanceId !== instanceId || seen.has(tab.tabId)) continue;
			this.#onTabRemoved(key);
		}
		// Absent on older extensions: keep what this relay learned from its own createTarget calls.
		const ompCreated = Array.isArray(msg.ownedTabIds) ? new Set(msg.ownedTabIds) : null;
		// Reconcile authoritative ownership before any deferred close, even when id and URL match.
		for (const tab of this.#tabs.values()) {
			if (tab.instanceId === instanceId && ompCreated) tab.ompCreated = ompCreated.has(tab.tabId);
		}
		// Close the tabs whose close failed while this browser was offline, unless the user closed them meanwhile or
		// the id now names another page.
		for (const [key, url] of this.#closeOnHello) {
			if (!key.startsWith(`${inst.code}:`)) continue;
			this.#closeOnHello.delete(key);
			const closed = this.#tabs.get(key);
			if (closed?.ompCreated && closed.url === url && !this.#claimed(key))
				void this.#closeTab(key, closed.tabId, inst).catch(() => undefined);
		}
		for (const tab of this.#tabs.values()) {
			if (tab.instanceId !== instanceId) continue;
			if (ompCreated) tab.ompCreated = ompCreated.has(tab.tabId);
			const wasAttached = tab.attached;
			tab.attached = attachedNow.has(tab.tabId);
			tab.attaching = null;
			tab.cancelAttach = null;
			tab.attachCancelled = false;
			if (!tab.attached) this.#forgetChildren(tab);
			if (tab.discarded) {
				// Retire held sessions now; revival will reannounce and attach the tab.
				this.#retractTab(tab);
				this.#detachIfUnheld(tab.tabKey);
				continue;
			}
			// An attachment that outlived the extension's socket kept its switches, including any a release could not
			// turn off while the socket was down, and one this bridge first hears of (the relay restarted under a live
			// extension) may hold any switch a vanished client left on: bring those to what live sessions want now.
			if (!known.has(tab.tabKey)) for (const method of TAB_WIDE_SWITCHES) tab.unsettledSwitches.add(method);
			const unsettled = [...tab.unsettledSwitches];
			tab.unsettledSwitches.clear();
			if (tab.attached) {
				for (const method of unsettled)
					this.#sendSwitch(tab.tabKey, method, this.#switchWanted(tab.tabKey, method));
			}
			// A service-worker restart can drop attachments while downstream
			// connections still hold sessions: restore them best-effort.
			if (wasAttached && !tab.attached && this.#sessionHolders(tab.tabKey).length > 0) {
				void this.#ensureAttached(tab).then(ok => {
					if (!ok) this.#onTabDetached(tab.tabKey, "reattach_failed", false);
					// The lost attachment took its switches with it.
					else {
						for (const method of TAB_WIDE_SWITCHES) {
							if (this.#switchWanted(tab.tabKey, method)) this.#sendSwitch(tab.tabKey, method, true);
						}
					}
				});
			}
			// A tab the hello brings that no client was told about, such as one a browser opened before its
			// extension connected, is announced now: no later change has to happen for Puppeteer to see it.
			if (!tab.announced && this.#eligible(tab)) this.#announceTab(tab);
		}
		this.#syncGrouping();
		this.#log("extension connected", {
			instanceId,
			tabs: msg.tabs.length,
			version: msg.browserVersion,
			omp: inst.info.ompVersion,
		});
		this.#maybeUpdateExtension(inst);
	}

	// ---- extension self-update ------------------------------------------------

	/**
	 * The older omp version this extension runs, when the relay may replace it: the extension reloads on request,
	 * its script carries an omp version older than this relay's, its socket named its Chrome id, and the relay has
	 * not already reloaded it from that version (a reload that brings the same version back must not loop).
	 */
	#outdatedReloadable(inst: ExtInstance): string | null {
		const ompVersion = inst.info?.ompVersion ?? "";
		if (inst.info?.reloadProtocol !== EXTENSION_RELOAD_PROTOCOL_VERSION || !inst.extensionId) return null;
		if (!isOmpVersion(ompVersion) || !isOlderOmpVersion(ompVersion, VERSION)) return null;
		return this.#updateTried.get(inst.instanceId)?.has(ompVersion) ? null : ompVersion;
	}

	/**
	 * Why reloading this extension now would cost someone something, or null. A reload drops the extension's
	 * socket and every debugger attachment it holds, so it waits for no CDP client to be connected (no claimed
	 * tab, no held session) and none of the extension's tabs to be attached, attaching or detaching. It also waits
	 * out the extension's calls in flight and the tab closes queued for its next hello: the reloaded extension
	 * reports a new browser session, which retires the target ids they name, so a tab omp opened would stay open.
	 */
	#reloadBlocker(inst: ExtInstance): string | null {
		if (!inst.socket) return "disconnected";
		if (this.#conns.size > 0) return "CDP clients connected";
		for (const tab of this.#tabs.values()) {
			if (tab.instanceId === inst.instanceId && (tab.attached || tab.attaching || tab.detaching)) {
				return "tabs attached";
			}
		}
		// A call past its timeout whose late result still closes what it made (a tab created after omp gave up) counts.
		for (const key of [...this.#pendingRpc.keys(), ...this.#lateRpc.keys()]) {
			if (key.startsWith(`${inst.instanceId}:`)) return "extension calls pending";
		}
		for (const key of this.#closeOnHello.keys()) {
			if (key.startsWith(`${inst.code}:`)) return "tab closes queued";
		}
		return null;
	}

	/** Rewrite an outdated extension's files to this omp's and ask it to reload, when that costs nothing. */
	#maybeUpdateExtension(inst: ExtInstance): void {
		const updateExtension = this.#updateExtension;
		if (!updateExtension || inst.updating) return;
		const from = this.#outdatedReloadable(inst);
		if (from === null) return;
		const busy = this.#reloadBlocker(inst);
		if (busy !== null) {
			this.#log("extension update deferred", { instanceId: inst.instanceId, from, reason: busy });
			return;
		}
		const socket = inst.socket!;
		// Not ready while the files change: a client waits for the reloaded extension instead of connecting.
		inst.updating = true;
		void updateExtension(inst.extensionId!)
			.catch(err => {
				this.#log("extension update failed", { error: err instanceof Error ? err.message : String(err) });
				return false;
			})
			.then(updated => {
				if (inst.socket !== socket || !inst.updating) return;
				// A client may have connected or a tab attached while the files were written.
				const busy = updated ? this.#reloadBlocker(inst) : "files not rewritten";
				if (busy !== null) {
					inst.updating = false;
					this.#log("extension update stopped", { instanceId: inst.instanceId, from, reason: busy });
					return;
				}
				const tried = this.#updateTried.get(inst.instanceId) ?? new Set<string>();
				tried.add(from);
				this.#updateTried.set(inst.instanceId, tried);
				socket.send(JSON.stringify({ t: "reload" } satisfies RelayToExtMessage));
				this.#log("extension reloading into update", { instanceId: inst.instanceId, from, to: VERSION });
				// Retire the socket now, as if the reload had closed it: nothing new may reach a browser that is
				// about to drop its socket and attachments. An extension that ignored the request redials.
				socket.close();
				this.extClosed(socket);
			});
	}

	/**
	 * With no CDP client left, once every tab's attach and detach has settled (their cleanup included, which can start
	 * another detach): update the extensions that were kept busy. An attach left running after its tab was discarded
	 * is not awaited twice; its own RPC retries the update when it settles.
	 */
	async #updateIdleExtensions(): Promise<void> {
		const awaited = new Set<Promise<unknown>>();
		for (;;) {
			const busy = Array.from(this.#tabs.values(), tab => tab.attaching ?? tab.detaching).filter(
				(p): p is Promise<boolean> | Promise<void> => p !== null && !awaited.has(p),
			);
			if (busy.length === 0) break;
			for (const p of busy) awaited.add(p);
			await Promise.all(busy);
		}
		if (this.#conns.size > 0) return;
		for (const inst of this.#instances.values()) this.#maybeUpdateExtension(inst);
	}

	// ---- downstream (puppeteer) lifecycle -------------------------------------

	/**
	 * Register a downstream CDP websocket; returns the connection id. `claim` is the target the connecting omp tab
	 * worker drives (`/cdp?claim=`), claimed before puppeteer sends anything to it.
	 */
	cdpConnected(socket: RelaySocket, claim?: string): number {
		const conn = new CdpConnection(++this.#connSeq, socket);
		this.#conns.set(conn.id, conn);
		this.#log("cdp client connected", { conn: conn.id });
		const parsed = claim ? parseTargetId(claim) : null;
		const tab = parsed ? this.#tabs.get(parsed.key) : undefined;
		if (tab) {
			try {
				this.#claimTab(conn, tab.tabKey, undefined, true);
			} catch (err) {
				this.#conns.delete(conn.id);
				socket.close();
				throw err;
			}
		}
		return conn.id;
	}

	cdpClosed(connId: number): void {
		const conn = this.#conns.get(connId);
		if (!conn) return;
		this.#conns.delete(connId);
		const touched = new Set<string>();
		for (const ref of conn.sessions.values()) touched.add(ref.tabKey);
		const departed = [...conn.sessions.values()];
		conn.sessions.clear();
		const armedTabs = new Set<string>();
		for (const ref of departed) {
			this.#releaseSwitches(ref);
			if (ref.autoAttach) armedTabs.add(ref.tabKey);
		}
		for (const tabKey of armedTabs) this.#releaseAutoAttach(tabKey);
		// Tabs this client claimed leave the omp group unless another claimant
		// remains — session holders don't count: the long-lived registry
		// connection holds sessions on every tab without driving any of them.
		for (const tabId of conn.claims) {
			const tab = this.#tabs.get(tabId);
			if (tab?.provisionalClaimConnId === connId) tab.provisionalClaimConnId = undefined;
			if (tab) this.#syncTabGrouping(tab);
		}
		conn.claims.clear();
		// Drop the debugger (and its infobar) from tabs nobody drives anymore.
		for (const tabKey of touched) this.#detachIfUnheld(tabKey);
		this.#log("cdp client closed", { conn: connId });
		if (this.#conns.size === 0) void this.#updateIdleExtensions();
	}

	cdpMessage(connId: number, raw: string): void {
		const conn = this.#conns.get(connId);
		if (!conn) return;
		let msg: CdpCommand;
		try {
			msg = JSON.parse(raw) as CdpCommand;
		} catch {
			return;
		}
		if (typeof msg.id !== "number" || typeof msg.method !== "string") return;
		void this.#handleCdpCommand(conn, msg).catch(err => {
			this.#replyError(conn, msg, err instanceof Error ? err.message : String(err));
		});
	}

	// ---- command routing -------------------------------------------------------

	async #handleCdpCommand(conn: CdpConnection, msg: CdpCommand): Promise<void> {
		const sessionId = msg.sessionId;
		if (!sessionId) {
			await this.#handleBrowserCommand(conn, msg);
			return;
		}
		const ref = conn.sessions.get(sessionId);
		if (ref?.kind === "tab") {
			this.#handleTabSessionCommand(conn, msg, ref);
			return;
		}
		if (ref?.kind === "page") {
			await this.#handlePageSessionCommand(conn, msg, sessionId, ref);
			return;
		}
		const realTabKey = this.#realSessionTabs.get(sessionId);
		if (realTabKey !== undefined && conn.childParents.has(sessionId)) {
			const announce =
				msg.method === "Target.setAutoAttach" && msg.params?.autoAttach === true
					? () => this.#announceChildren(conn, realTabKey, sessionId, sessionId)
					: undefined;
			await this.#forwardToTab(conn, msg, realTabKey, sessionId, announce);
			return;
		}
		this.#replyError(conn, msg, `Unknown session id ${sessionId}`);
	}

	async #handlePageSessionCommand(
		conn: CdpConnection,
		msg: CdpCommand,
		sessionId: string,
		ref: SessionRef,
	): Promise<void> {
		if (msg.method === "Runtime.disable") {
			ref.runtimeState = "disabled";
			ref.runtimeEpoch++;
			ref.runtimeContexts.clear();
			// Abandon any in-flight enable's ownership: a later enable starts fresh
			// rather than joining a cycle that predates this disable.
			ref.runtimeEnabling = null;
			this.#reply(conn, msg, {});
			return;
		}
		if (msg.method !== "Runtime.enable") {
			if (msg.method === "Target.setAutoAttach") {
				await this.#serializeSwitches(ref.tabKey, "Target.setAutoAttach", async () => {
					if (conn.sessions.get(sessionId) !== ref) {
						this.#replyError(conn, msg, `Unknown session id ${sessionId}`);
						return;
					}
					// Arm before sending: Chrome reports existing children before answering.
					const previous = ref.autoAttach;
					ref.autoAttach = msg.params?.autoAttach === true;
					const announce = () => {
						const parent = conn.childTargetSessionForTab(ref.tabKey);
						if (parent) this.#announceChildren(conn, ref.tabKey, undefined, parent);
					};
					if (!ref.autoAttach && this.#autoAttaches(ref.tabKey)) {
						this.#reply(conn, msg, {});
					} else if (
						!(await this.#forwardToTab(conn, msg, ref.tabKey, undefined, ref.autoAttach ? announce : undefined))
					) {
						ref.autoAttach = previous;
						if (previous && conn.sessions.get(sessionId) !== ref) this.#releaseAutoAttach(ref.tabKey);
						return;
					}
					const tab = this.#tabs.get(ref.tabKey);
					if (tab && !conn.childTargetSessionForTab(ref.tabKey)) this.#forgetConnectionChildren(conn, tab, true);
				});
				return;
			}
			if (isTabWideSwitch(msg.method)) {
				// Every session of a tab shares one debugger attachment, so the switch is tab-wide here: one session
				// switching it off must not undo another's (a pending chooser wait, a background tab's input).
				const method = msg.method;
				await this.#serializeSwitches(ref.tabKey, method, async () => {
					const previous = ref.switches.has(method);
					if (msg.params?.enabled === true) ref.switches.add(method);
					else ref.switches.delete(method);
					const params = { ...msg.params, enabled: this.#switchWanted(ref.tabKey, method) };
					if (!(await this.#forwardToTab(conn, { ...msg, params }, ref.tabKey, undefined))) {
						if (previous) ref.switches.add(method);
						else ref.switches.delete(method);
						// Chrome may have applied it before the reply was lost with the socket.
						this.#tabs.get(ref.tabKey)?.unsettledSwitches.add(method);
					}
				});
				return;
			}
			await this.#forwardToTab(conn, msg, ref.tabKey, undefined);
			return;
		}
		// A pipelined duplicate must await the in-flight enable, never ack early:
		// the root cycle may still fail, and success must trail the context replay.
		if (ref.runtimeEnabling) {
			await this.#awaitEnable(conn, msg, ref.runtimeEnabling);
			return;
		}
		if (ref.runtimeState === "enabled") {
			this.#reply(conn, msg, {});
			return;
		}
		const enabling = this.#enableSessionRuntime(conn, sessionId, ref);
		ref.runtimeEnabling = enabling;
		try {
			await this.#awaitEnable(conn, msg, enabling);
		} finally {
			if (ref.runtimeEnabling === enabling) ref.runtimeEnabling = null;
		}
	}

	/** Reply to one `Runtime.enable` command with the shared enable's outcome. */
	async #awaitEnable(conn: CdpConnection, msg: CdpCommand, enabling: Promise<void>): Promise<void> {
		try {
			await enabling;
			this.#reply(conn, msg, {});
		} catch (err) {
			this.#replyError(conn, msg, err instanceof Error ? err.message : String(err));
		}
	}

	/**
	 * Drive the shared root `Runtime.enable` for a session and replay the live
	 * contexts to it. Rejects if the root cycle fails so every joined caller
	 * observes the failure instead of a spurious success.
	 */
	async #enableSessionRuntime(conn: CdpConnection, sessionId: string, ref: SessionRef): Promise<void> {
		const prev = ref.runtimeState;
		const epoch = ++ref.runtimeEpoch;
		ref.runtimeState = "enabled";
		const tab = this.#tabs.get(ref.tabKey);
		if (!tab) {
			ref.runtimeState = prev;
			throw new Error(`No tab ${ref.tabKey}`);
		}
		try {
			await this.#ensureRuntimeEnabled(tab);
			// A disable or newer enable may have taken ownership while the root
			// RPC was in flight; only the latest enable may replay or roll back.
			if (conn.sessions.get(sessionId) === ref && ref.runtimeEpoch === epoch && ref.runtimeState === "enabled") {
				this.#replayRuntimeContexts(conn, sessionId, ref, tab);
			}
		} catch (err) {
			if (ref.runtimeEpoch === epoch) {
				ref.runtimeState = prev;
				ref.runtimeContexts.clear();
			}
			throw err;
		}
	}

	async #ensureRuntimeEnabled(tab: TabState): Promise<void> {
		if (tab.rootRuntimeEnabled) return;
		if (tab.rootRuntimeEnabling) return await tab.rootRuntimeEnabling;

		const enabling = this.#cycleRuntime(tab);
		tab.rootRuntimeEnabling = enabling;
		const generation = tab.runtimeGeneration;
		try {
			await enabling;
			if (tab.runtimeGeneration === generation) tab.rootRuntimeEnabled = true;
		} finally {
			if (tab.rootRuntimeEnabling === enabling) tab.rootRuntimeEnabling = null;
		}
	}

	async #cycleRuntime(tab: TabState): Promise<void> {
		const inst = this.#instanceFor(tab);
		await this.#send(tab, inst, "Runtime.disable");
		await this.#send(tab, inst, "Runtime.enable");
	}

	/**
	 * Run one command on the tab's debugger attachment. One whose answer waits on the page itself (a promise it
	 * settles, a navigation it commits) gets {@link PAGE_BOUND_RPC_TIMEOUT_MS}; any other gets {@link RPC_TIMEOUT_MS}.
	 */
	async #send(
		tab: TabState,
		inst: ExtInstance,
		method: string,
		params?: Record<string, unknown>,
		sessionId?: string,
	): Promise<unknown> {
		const pageBound =
			params?.awaitPromise === true || method === "Runtime.awaitPromise" || method === "Page.navigate";
		const timeoutMs = pageBound ? PAGE_BOUND_RPC_TIMEOUT_MS : RPC_TIMEOUT_MS;
		try {
			return await this.#rpc({ op: "send", tabId: tab.tabId, sessionId, method, params }, inst, timeoutMs);
		} catch (err) {
			if (!(err instanceof RpcTimeoutError)) throw err;
			throw new Error(`${method} on tab ${tab.tabId}: Chrome sent no answer within ${timeoutMs}ms`, { cause: err });
		}
	}

	#replayRuntimeContexts(conn: CdpConnection, sessionId: string, ref: SessionRef, tab: TabState): void {
		for (const [contextId, params] of tab.runtimeContexts) {
			if (ref.runtimeContexts.has(contextId)) continue;
			ref.runtimeContexts.add(contextId);
			conn.socket.send(JSON.stringify({ sessionId, method: "Runtime.executionContextCreated", params }));
		}
	}

	/**
	 * Chrome reports a child target once, to the first auto-attach armed over it, so a connection
	 * arming later (a tab worker after the registry connection) is told here of the children already
	 * reported under `parent` (the tab's root when undefined) that it has not heard of.
	 */
	#announceChildren(conn: CdpConnection, tabKey: string, parent: string | undefined, sessionId: string): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		for (const [child, known] of tab.realSessions) {
			if (known.parent !== parent || conn.childParents.has(child)) continue;
			conn.childParents.set(child, sessionId);
			conn.socket.send(JSON.stringify({ sessionId, method: "Target.attachedToTarget", params: known.event }));
		}
	}

	/**
	 * Forward a command to the tab and reply to it; resolves whether the command succeeded.
	 * `beforeReply` runs on success ahead of the reply. Target lifecycle commands are answered by the
	 * relay's browser handlers instead, which reply (or throw to `cdpMessage`) themselves: they resolve `true`.
	 */
	async #forwardToTab(
		conn: CdpConnection,
		msg: CdpCommand,
		tabKey: string,
		realSessionId: string | undefined,
		beforeReply?: () => void,
	): Promise<boolean> {
		// Guard rail: a page session must never take the whole browser down.
		if (msg.method === "Browser.close") {
			this.#reply(conn, msg, {});
			return true;
		}
		if (
			msg.method === "Page.close" ||
			msg.method === "Page.bringToFront" ||
			msg.method === "Browser.setWindowBounds"
		) {
			this.#replyError(
				conn,
				msg,
				"Use an owned target lifecycle command; borrowed tabs cannot be closed or focused",
			);
			return false;
		}
		if (msg.method === "Browser.setDownloadBehavior" || msg.method === "Page.setDownloadBehavior") {
			this.#reply(conn, msg, {});
			return true;
		}
		// Relay-private claim the omp tab worker sends on the page it adopted. A worker of this version claims at
		// connect already (`/cdp?claim=`); one of an older version, sharing this relay, claims only here. Never
		// forwarded — real Chrome rejects the unknown method.
		if (msg.method === "OMP.claimTarget") {
			try {
				this.#claimTab(
					conn,
					tabKey,
					typeof msg.params?.label === "string" ? msg.params.label : undefined,
					msg.params?.ownsTarget === true,
				);
				this.#reply(conn, msg, {});
				return true;
			} catch (err) {
				this.#replyError(conn, msg, err instanceof Error ? err.message : String(err));
				return false;
			}
		}
		// Relay-private: what the extension hid in this tab, for the worker driving it.
		if (msg.method === "OMP.takeHiddenFrames") {
			this.#reply(conn, msg, { frames: this.#tabs.get(tabKey)?.hiddenFrames.splice(0) ?? [] });
			return true;
		}
		const tab = this.#tabs.get(tabKey);
		if (!tab) {
			this.#replyError(conn, msg, `No tab with key ${tabKey}`);
			return false;
		}
		const inst = this.#instances.get(tab.instanceId);
		if (!inst || !inst.socket) {
			this.#replyError(conn, msg, "relay extension is not connected");
			return false;
		}
		// Relay-private download tracking is unavailable in this fork.
		if (msg.method === "OMP.downloadPath") return await this.#replyDownloadPath(conn, msg);
		// Sent raw, createTarget honors `newWindow` and answers with Chrome's id, which no relay command
		// resolves; close and activate are refused ("Not allowed"). Run them in this tab's browser, where a
		// new tab lands like every relay-created tab: in that browser's current window.
		if (
			msg.method === "Target.createTarget" ||
			msg.method === "Target.closeTarget" ||
			msg.method === "Target.activateTarget"
		) {
			await this.#handleBrowserCommand(conn, msg, tab);
			return true;
		}
		if (this.#readFrontApp && canOpenWindow(msg.method, msg.params)) {
			tab.frontAtInput = Date.now() < this.#keepingFrontUntil ? null : this.#readFrontAtInput(this.#readFrontApp);
		}
		try {
			const result = await this.#send(tab, inst, msg.method, msg.params, realSessionId);
			const response = (result as Record<string, unknown> | undefined) ?? {};
			// An explicit attach grants ownership even when this connection did not arm auto-attach.
			if (msg.method === "Target.attachToTarget" && msg.sessionId && typeof response.sessionId === "string") {
				conn.childParents.set(response.sessionId, msg.sessionId);
				conn.explicitChildren.add(response.sessionId);
			}
			beforeReply?.();
			this.#reply(conn, msg, response);
			return true;
		} catch (err) {
			const message = err instanceof Error ? err.message : String(err);
			// Chrome fails the root session's command in flight before it reports the detach. Hold the failure
			// until the detach is reported, so the client gets `OMP.debuggerDetached` first and knows why.
			if (realSessionId === undefined && tab.attached && DETACHED_COMMAND_ERROR.test(message)) {
				await Promise.race([tab.chromeDetach.promise, Bun.sleep(CHROME_DETACH_REPORT_MS)]);
			}
			this.#replyError(conn, msg, message);
			return false;
		}
	}

	/**
	 * Read the app in front of the user with `read` as omp's input reaches a tab, to put it back when that input opens a
	 * window and Chrome brings itself forward to show it. Only where the relay can put it back (macOS).
	 */
	keepFrontAppWith(read: () => FrontApp | null): void {
		this.#readFrontApp = read;
	}

	/**
	 * The app in front of the user now, for omp's input to a tab. A read that throws (a stale native addon without
	 * `macOSFrontApp`) turns the reads off for good, so the input itself still goes out.
	 */
	#readFrontAtInput(read: () => FrontApp | null): { app: FrontApp; at: number } | null {
		try {
			const app = read();
			return app && { app, at: Date.now() };
		} catch (err) {
			this.#readFrontApp = undefined;
			this.#log("could not read the app in front; not holding it in front", {
				error: err instanceof Error ? err.message : String(err),
			});
			return null;
		}
	}

	/**
	 * Hold the app that was in front at omp's last input to `tab`, if that input can have opened the window the tab's
	 * page is opening: Chrome makes itself the active app to show it.
	 */
	#keepFrontApp(tab: TabState): void {
		const front = tab.frontAtInput;
		tab.frontAtInput = null;
		if (!front || Date.now() < this.#keepingFrontUntil || Date.now() - front.at > POPUP_AFTER_INPUT_MS) return;
		const until = Date.now() + KEEP_FRONT_MS;
		this.#keepingFrontUntil = until;
		front.app.keepInFront(KEEP_FRONT_MS).then(
			times => {
				if (times > 0) this.#log("put the user's app back in front", { times });
				if (this.#keepingFrontUntil === until) this.#keepingFrontUntil = 0;
			},
			err => {
				this.#log("could not keep the user's app in front", {
					error: err instanceof Error ? err.message : String(err),
				});
			},
		);
	}

	/**
	 * Record `conn` as a driver of the tab and reconcile grouping. Claims are
	 * explicit (worker adoption or tab creation) rather than inferred from
	 * command traffic: target discovery scans every page with the same
	 * commands a driver sends, so inference would sweep all tabs.
	 */
	#claimTab(conn: CdpConnection, tabKey: string, label?: string, handoff = false): TabState | undefined {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		if (tab.closing) throw new Error("Target closure is already in progress");
		for (const other of this.#conns.values()) {
			if (other.id === conn.id || !other.claims.has(tabKey)) continue;
			if (handoff && tab.provisionalClaimConnId === other.id) {
				other.claims.delete(tabKey);
				tab.provisionalClaimConnId = undefined;
				continue;
			}
			throw new Error(`Tab ${tabKey} is already driven by another omp session`);
		}
		if (!conn.claims.has(tabKey)) {
			conn.claims.add(tabKey);
			this.#log("tab claimed", { conn: conn.id, tabKey });
		}
		if (label !== undefined) {
			const normalized = label.trim().slice(0, 32).trim() || undefined;
			if (normalized !== tab.label) {
				tab.label = normalized;
				this.#ungroupForRelabel(tab);
			}
		}
		this.#syncTabGrouping(tab);
		return tab;
	}

	/** True while any downstream connection claims the tab as its drive target. */
	#claimed(tabKey: string): boolean {
		for (const conn of this.#conns.values()) {
			if (conn.claims.has(tabKey)) return true;
		}
		return false;
	}

	/** Tab pseudo-sessions only exist to satisfy puppeteer's Target hierarchy. */
	#handleTabSessionCommand(conn: CdpConnection, msg: CdpCommand, ref: SessionRef): void {
		switch (msg.method) {
			case "Target.setAutoAttach": {
				const tab = this.#tabs.get(ref.tabKey);
				if (!tab) {
					this.#replyError(conn, msg, `Tab ${ref.tabKey} is gone`);
					return;
				}
				// Emit before replying: puppeteer's TargetManager counts page
				// children attached before the setAutoAttach response resolves.
				const pageSession = this.#mintSession(conn, "page", tab);
				this.#emit(
					conn,
					"Target.attachedToTarget",
					{
						sessionId: pageSession,
						targetInfo: this.#pageInfo(tab, true),
						waitingForDebugger: false,
					},
					msg.sessionId,
				);
				this.#reply(conn, msg, {});
				return;
			}
			case "Runtime.runIfWaitingForDebugger":
				this.#reply(conn, msg, {});
				return;
			case "Target.detachFromTarget": {
				const child = typeof msg.params?.sessionId === "string" ? msg.params.sessionId : undefined;
				if (child) this.#releaseSession(conn, child, msg.sessionId);
				this.#reply(conn, msg, {});
				return;
			}
			default:
				this.#replyError(conn, msg, `'${msg.method}' is not supported on a tab target`, CDP_ERROR_METHOD_NOT_FOUND);
		}
	}

	/** `near`: the tab whose session sent the command; a tab it creates opens in that tab's browser. */
	async #handleBrowserCommand(conn: CdpConnection, msg: CdpCommand, near?: TabState): Promise<void> {
		switch (msg.method) {
			case "Browser.getVersion": {
				this.#reply(conn, msg, {
					protocolVersion: "1.3",
					product: this.#lastHello()?.info?.browserVersion ?? "Chrome/unknown",
					revision: "",
					userAgent: this.#lastHello()?.info?.userAgent ?? "",
					jsVersion: "",
				});
				return;
			}
			case "Target.getBrowserContexts":
				this.#reply(conn, msg, { browserContextIds: [] });
				return;
			case "Target.getTargets": {
				const targetInfos: TargetInfo[] = [];
				for (const tab of this.#tabs.values()) {
					if (this.#eligible(tab)) targetInfos.push(this.#pageInfo(tab, tab.attached));
				}
				this.#reply(conn, msg, { targetInfos });
				return;
			}
			case "Target.setDiscoverTargets": {
				conn.discover = true;
				for (const tab of this.#tabs.values()) {
					if (!this.#eligible(tab)) continue;
					tab.announced = true;
					this.#emit(conn, "Target.targetCreated", { targetInfo: this.#tabInfo(tab, tab.attached) });
					this.#emit(conn, "Target.targetCreated", { targetInfo: this.#pageInfo(tab, tab.attached) });
				}
				this.#reply(conn, msg, {});
				return;
			}
			case "Target.setAutoAttach": {
				conn.autoAttach = true;
				// Discarded tabs can stall debugger calls. Retract targets already
				// announced by Target.setDiscoverTargets so Puppeteer can connect().
				const tabs = [...this.#tabs.values()].filter(tab => this.#eligible(tab) && !tab.discarded);
				await Promise.all(tabs.map(tab => this.#ensureAttached(tab, { retryAfterDiscard: true })));
				for (const tab of tabs) {
					if (!tab.attached || tab.discarded || !this.#eligible(tab)) {
						// Failed or newly discarded tabs must not hold up connect().
						this.#retractTab(tab);
						this.#detachIfUnheld(tab.tabKey);
						continue;
					}
					this.#emitTabAttached(conn, tab);
				}
				for (const tab of this.#tabs.values()) {
					if (tab.announced && tab.discarded && this.#eligible(tab)) {
						this.#retractTab(tab);
						this.#detachIfUnheld(tab.tabKey);
					}
				}
				this.#reply(conn, msg, {});
				return;
			}
			case "Target.attachToTarget": {
				const parsed = typeof msg.params?.targetId === "string" ? parseTargetId(msg.params.targetId) : null;
				const tab = parsed ? this.#tabs.get(parsed.key) : undefined;
				if (!parsed || !tab) {
					this.#replyError(conn, msg, `No target with id ${String(msg.params?.targetId)}`);
					return;
				}
				if (tab.discarded) {
					this.#replyError(conn, msg, `Cannot attach to discarded tab ${tab.tabKey}`);
					return;
				}
				if (!(await this.#ensureAttached(tab))) {
					const reason = tab.refusal ? `: ${tab.refusal}` : "";
					this.#replyError(conn, msg, `Cannot attach to tab ${tab.tabKey} (${tab.url})${reason}`);
					return;
				}
				const sessionId = this.#mintSession(conn, parsed.kind, tab);
				const info = parsed.kind === "tab" ? this.#tabInfo(tab, true) : this.#pageInfo(tab, true);
				this.#emit(conn, "Target.attachedToTarget", { sessionId, targetInfo: info, waitingForDebugger: false });
				this.#reply(conn, msg, { sessionId });
				return;
			}
			case "Target.detachFromTarget": {
				const sessionId = typeof msg.params?.sessionId === "string" ? msg.params.sessionId : undefined;
				if (sessionId) this.#releaseSession(conn, sessionId, undefined);
				this.#reply(conn, msg, {});
				return;
			}
			case "Target.createTarget": {
				const url =
					typeof msg.params?.url === "string" && msg.params.url.length > 0 ? msg.params.url : "about:blank";
				// `nearTargetId` is the relay's own parameter: open in the browser of that tab.
				const affine = near ? undefined : this.#affineInstance(conn, msg.params?.nearTargetId);
				// Its extension may be reconnecting: another browser can be another profile, logged in elsewhere.
				if (affine && !affine.socket) {
					await this.#awaitReconnect(affine);
					if (this.#conns.get(conn.id) !== conn) return;
				}
				const inst = near ? this.#instances.get(near.instanceId) : this.#instanceForNewTab(affine);
				if (!inst || !inst.socket) {
					this.#replyError(conn, msg, "relay extension is not connected");
					return;
				}
				// Fork-created tabs never select a window implicitly; explicit owner focus is a separate command.
				const active = false;
				const creationCode = inst.code;
				// Chrome can still create the tab after the RPC timed out: close it then, since nobody learns its id.
				const result = (await this.#rpc({ op: "createTab", url, active }, inst, RPC_TIMEOUT_MS, late => {
					if (inst.code !== creationCode || this.#instances.get(inst.instanceId) !== inst) return;
					const snapshot = (late as { tab?: TabSnapshot })?.tab;
					if (!snapshot || !Number.isInteger(snapshot.tabId)) return;
					const tabId = snapshot.tabId;
					this.#onTabUpsert(snapshot, inst.instanceId);
					const lateTab = this.#tabs.get(tabKeyOf(creationCode, tabId));
					if (!lateTab || this.#claimed(lateTab.tabKey)) return;
					lateTab.ompCreated = true;
					this.#closeTab(tabKeyOf(inst.code, tabId), tabId, inst).catch(err => {
						this.#log("late relay tab close waits for the next hello", {
							tabId,
							error: err instanceof Error ? err.message : String(err),
						});
					});
				})) as { tab: TabSnapshot };
				if (inst.code !== creationCode || this.#instances.get(inst.instanceId) !== inst) {
					this.#replyError(conn, msg, "Browser restarted while creating the target");
					return;
				}
				this.#onTabUpsert(result.tab, inst.instanceId);
				const createdProof = this.#tabs.get(tabKeyOf(creationCode, result.tab.tabId));
				if (createdProof) createdProof.ompCreated = true;
				// The client left while Chrome created the tab (omp gave up on a slow open), so nobody
				// can learn its id to close it later: close it now instead of leaving it in the user's browser.
				if (this.#conns.get(conn.id) !== conn) {
					await this.#closeTab(tabKeyOf(inst.code, result.tab.tabId), result.tab.tabId, inst);
					return;
				}
				// Creating a tab is an explicit act of driving it.
				const createdKey = tabKeyOf(inst.code, result.tab.tabId);
				const createdTab = this.#claimTab(conn, createdKey);
				if (createdTab) {
					createdTab.provisionalClaimConnId = conn.id;
					createdTab.ompCreated = true;
				}
				// Puppeteer waits for the new page's auto-attach. Answer once it settled: a tab Chrome refuses (an
				// extension debugger policy refuses every tab) would otherwise hold the open for its whole timeout.
				const created = this.#tabs.get(createdKey);
				if (conn.autoAttach && created && !(await this.#ensureAttached(created)) && created.refusal) {
					const refusal = created.refusal;
					await this.#closeTab(createdKey, created.tabId, inst).catch(() => undefined);
					this.#replyError(conn, msg, `Chrome refused to attach to the new tab: ${refusal}`);
					return;
				}
				this.#reply(conn, msg, { targetId: pageTargetIdFromKey(createdKey) });
				return;
			}
			case "Target.closeTarget": {
				const parsed = typeof msg.params?.targetId === "string" ? parseTargetId(msg.params.targetId) : null;
				if (!parsed) {
					this.#replyError(conn, msg, `No target with id ${String(msg.params?.targetId)}`);
					return;
				}
				const removedTab = this.#tabs.get(parsed.key);
				if (!removedTab) {
					this.#replyError(conn, msg, `No target with id ${String(msg.params?.targetId)}`);
					return;
				}
				if (!removedTab.ompCreated || !conn.claims.has(parsed.key)) {
					this.#replyError(conn, msg, "Only the owner may close an omp-created target");
					return;
				}
				await this.#closeTab(parsed.key, removedTab.tabId, this.#instanceFor(removedTab));
				this.#reply(conn, msg, { success: true });
				return;
			}
			case "Target.activateTarget": {
				const parsed = typeof msg.params?.targetId === "string" ? parseTargetId(msg.params.targetId) : null;
				const activatedTab = parsed ? this.#tabs.get(parsed.key) : undefined;
				if (parsed && activatedTab) {
					if (!activatedTab.ompCreated || !conn.claims.has(parsed.key)) {
						this.#replyError(conn, msg, "Only the owner may focus an omp-created target");
						return;
					}
					await this.#rpc({ op: "activateTab", tabId: activatedTab.tabId }, this.#instanceFor(activatedTab));
				} else if (near) {
					// Raw, a page session's activate failed; don't turn an unknown id into success there.
					this.#replyError(conn, msg, `No target with id ${String(msg.params?.targetId)}`);
					return;
				}
				this.#reply(conn, msg, {});
				return;
			}
			case "Target.getTargetInfo": {
				const raw = typeof msg.params?.targetId === "string" ? msg.params.targetId : undefined;
				const parsed = raw ? parseTargetId(raw) : null;
				const tab = parsed ? this.#tabs.get(parsed.key) : undefined;
				if (parsed && tab) {
					const info =
						parsed.kind === "tab" ? this.#tabInfo(tab, tab.attached) : this.#pageInfo(tab, tab.attached);
					// Relay-private beside the result: why the tab is withheld, so a client that cannot find it can say.
					this.#reply(conn, msg, tab.refusal ? { targetInfo: info, refusal: tab.refusal } : { targetInfo: info });
					return;
				}
				this.#reply(conn, msg, {
					targetInfo: {
						targetId: "relay-browser",
						type: "browser",
						title: "",
						url: "",
						attached: true,
						canAccessOpener: false,
					} satisfies TargetInfo,
				});
				return;
			}
			case "Browser.close":
				// Never close the user's browser; acknowledge and ignore.
				this.#log("refusing Browser.close from downstream client", { conn: conn.id });
				this.#reply(conn, msg, {});
				return;
			case "Browser.setDownloadBehavior":
				this.#reply(conn, msg, {});
				return;
			case "OMP.closeOwnedTarget": {
				// Relay-private orphan reaper close. `closed: false` means the record
				// is stale (tab gone, not omp-created in this browser session, or
				// no longer owned) and must be dropped; a live claim is an error that retains the receipt.
				const parsed = typeof msg.params?.targetId === "string" ? parseTargetId(msg.params.targetId) : null;
				if (!parsed) {
					this.#reply(conn, msg, { closed: false, resolved: true });
					return;
				}
				const code = parsed.key.slice(0, parsed.key.lastIndexOf(":"));
				const inst = [...this.#instances.values()].find(candidate => candidate.code === code);
				if (!inst && this.#retiredCodes.has(code)) {
					this.#reply(conn, msg, { closed: false, resolved: true });
					return;
				}
				if (!inst?.socket) {
					// Its browser is not connected: the tab may still exist, keep the record.
					this.#replyError(conn, msg, "relay extension for this target is not connected");
					return;
				}
				const owned = this.#tabs.get(parsed.key);
				if (owned?.ompCreated && this.#claimed(parsed.key)) {
					this.#replyError(conn, msg, "Target is still claimed by a live owner");
					return;
				}
				if (owned && !owned.ompCreated && !inst.info?.ownershipReported) {
					this.#replyError(conn, msg, "Relay extension did not report ownership for this target");
					return;
				}
				if (!owned?.ompCreated) {
					this.#reply(conn, msg, { closed: false, resolved: true });
					return;
				}
				await this.#closeTab(parsed.key, owned.tabId, inst);
				this.#reply(conn, msg, { closed: true, resolved: true });
				return;
			}
			case "Target.createBrowserContext":
				this.#replyError(conn, msg, "Browser contexts are not supported by the omp browser relay");
				return;
			default:
				this.#replyError(conn, msg, `'${msg.method}' wasn't found`, CDP_ERROR_METHOD_NOT_FOUND);
		}
	}

	// ---- extension events -------------------------------------------------------

	#onCdpEvent(
		tabKey: string,
		sourceSessionId: string | undefined,
		method: string,
		params?: Record<string, unknown>,
	): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		// The page (or a frame in it, on a child session) is opening a tab or window; Chrome brings itself forward
		// to show it.
		if (method === "Page.windowOpen") this.#keepFrontApp(tab);
		// Track real child sessions so downstream commands can route back.
		if (method === "Target.attachedToTarget") {
			const child = params?.sessionId;
			if (typeof child === "string" && params) {
				tab.realSessions.set(child, { parent: sourceSessionId, event: params });
				this.#realSessionTabs.set(child, tabKey);
			}
		} else if (method === "Target.detachedFromTarget") {
			const child = params?.sessionId;
			if (typeof child === "string") {
				tab.realSessions.delete(child);
				this.#realSessionTabs.delete(child);
			}
		}
		if (sourceSessionId) {
			// Event from a real child session: pass through verbatim to every
			// connection that was told about the child, tracking nested children.
			const nested = typeof params?.sessionId === "string" ? params.sessionId : undefined;
			const payload = JSON.stringify({ sessionId: sourceSessionId, method, params });
			for (const conn of this.#conns.values()) {
				if (!conn.childParents.has(sourceSessionId)) continue;
				conn.socket.send(payload);
				if (nested && method === "Target.attachedToTarget" && !conn.childParents.has(nested))
					conn.childParents.set(nested, sourceSessionId);
				else if (nested && method === "Target.detachedFromTarget") {
					conn.childParents.delete(nested);
					conn.explicitChildren.delete(nested);
				}
			}
			return;
		}
		if (method.startsWith("Runtime.")) {
			const createdContext = method === "Runtime.executionContextCreated" ? params?.context : undefined;
			const createdContextId =
				createdContext &&
				typeof createdContext === "object" &&
				"id" in createdContext &&
				typeof createdContext.id === "number"
					? createdContext.id
					: undefined;
			const destroyedContextId =
				method === "Runtime.executionContextDestroyed" && typeof params?.executionContextId === "number"
					? params.executionContextId
					: undefined;
			if (createdContextId !== undefined && params) tab.runtimeContexts.set(createdContextId, params);
			if (destroyedContextId !== undefined) tab.runtimeContexts.delete(destroyedContextId);
			if (method === "Runtime.executionContextsCleared") tab.runtimeContexts.clear();

			for (const conn of this.#conns.values()) {
				for (const [pageSession, ref] of conn.sessions) {
					if (ref.kind !== "page" || ref.tabKey !== tabKey) continue;
					if (destroyedContextId !== undefined) ref.runtimeContexts.delete(destroyedContextId);
					if (method === "Runtime.executionContextsCleared") ref.runtimeContexts.clear();
					// `default` sessions never enabled Runtime but still get the
					// legacy fan-out; only an explicit `Runtime.disable` silences one.
					if (ref.runtimeState === "disabled") continue;
					if (createdContextId !== undefined) {
						if (ref.runtimeContexts.has(createdContextId)) continue;
						ref.runtimeContexts.add(createdContextId);
					}
					conn.socket.send(JSON.stringify({ sessionId: pageSession, method, params }));
				}
			}
			return;
		}
		// Other root-session events fan out once per minted page session. A real
		// child is announced once per connection, on a session that armed
		// auto-attach, and its detach goes to that same session.
		if (method === "Target.attachedToTarget" || method === "Target.detachedFromTarget") {
			const child = params?.sessionId;
			if (typeof child !== "string") return;
			for (const conn of this.#conns.values()) {
				let parent: string | undefined;
				if (method === "Target.attachedToTarget") {
					parent = conn.childTargetSessionForTab(tabKey);
					if (parent && !conn.childParents.has(child)) conn.childParents.set(child, parent);
				} else {
					parent = conn.childParents.get(child);
					conn.childParents.delete(child);
					conn.explicitChildren.delete(child);
				}
				if (parent) conn.socket.send(JSON.stringify({ sessionId: parent, method, params }));
			}
			return;
		}
		for (const conn of this.#conns.values()) {
			for (const pageSession of conn.sessionsForTab(tabKey, "page")) {
				conn.socket.send(JSON.stringify({ sessionId: pageSession, method, params }));
			}
		}
	}

	/**
	 * The extension emptied and hid other extensions' frames in a tab omp drives. They wait on the tab for a worker to
	 * take them; one driving the attached tab now is told to, and the next one takes them when it adopts the tab.
	 */
	#onFramesHidden(tabKey: string, frames: unknown): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab || !Array.isArray(frames)) return;
		// The report comes off a socket and its title is another extension's text: keep well-formed, single-line
		// entries, once each, and only the latest few while no worker takes them.
		for (const frame of frames) {
			if (!isHiddenFrame(frame)) continue;
			const clean = {
				extensionId: singleLine(frame.extensionId, HIDDEN_FRAME_FIELD_MAX),
				path: singleLine(frame.path, HIDDEN_FRAME_FIELD_MAX),
				...(frame.title ? { title: singleLine(frame.title, HIDDEN_FRAME_FIELD_MAX) } : {}),
			};
			const held = tab.hiddenFrames.findIndex(
				entry => entry.extensionId === clean.extensionId && entry.path === clean.path,
			);
			if (held !== -1) tab.hiddenFrames.splice(held, 1);
			tab.hiddenFrames.push(clean);
		}
		if (tab.hiddenFrames.length > MAX_HIDDEN_FRAMES)
			tab.hiddenFrames.splice(0, tab.hiddenFrames.length - MAX_HIDDEN_FRAMES);
		for (const conn of this.#conns.values()) {
			if (!conn.claims.has(tabKey)) continue;
			for (const pageSession of conn.sessionsForTab(tabKey, "page")) {
				this.#emit(conn, "OMP.foreignFramesHidden", {}, pageSession);
			}
		}
	}

	#onTabDetached(tabKey: string, reason: string, relayInitiated: boolean): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		// Explicit source attribution comes from the extension that executed
		// chrome.debugger.detach, so socket replacement cannot confuse this
		// with a user cancellation or mutate an unrelated attach promise.
		if (relayInitiated) {
			// A replacement hello can observe the old attachment before the
			// pending detach completes. Reconcile that stale snapshot unless a
			// later attach has already superseded this detach.
			if (!tab.reattachedAfterDetach) tab.attached = false;
			return;
		}
		this.#log("tab detached", { tabKey, reason });
		tab.attached = false;
		tab.attaching = null;
		this.#resetRuntime(tab);
		// Only the user pressing Cancel on Chrome's debugging bar is a refusal. Chrome also detaches when
		// another extension's frame (a password manager's inline menu) starts loading in the tab: that tab
		// stays adoptable and is announced again at once; an attach Chrome refuses still bans it (#ensureAttached).
		const cancelledByUser = reason === "canceled_by_user";
		if (cancelledByUser) tab.refusal = "the user cancelled Chrome's debugging bar";
		// A user cancel releases the tab's omp-group membership; any other detach keeps it.
		this.#syncTabGrouping(tab);
		// Relay-private event, ahead of the sessions' detach: a client driving the tab learns that Chrome
		// ended the attachment, not the page, and can re-adopt it instead of waiting on a dead session. A tab
		// the relay is closing detaches on its way out (Chrome may report that before the removal): not re-adoptable.
		if (!tab.closing) {
			for (const conn of this.#conns.values()) {
				for (const pageSession of conn.sessionsForTab(tabKey, "page")) {
					this.#emit(conn, "OMP.debuggerDetached", { reason }, pageSession);
				}
			}
		}
		// Failures of commands that were in flight are released behind the event (#forwardToTab).
		tab.chromeDetach.resolve();
		tab.chromeDetach = Promise.withResolvers<void>();
		this.#retractTab(tab);
		if (!cancelledByUser && !tab.closing && this.#eligible(tab) && !tab.discarded) this.#announceTab(tab);
	}

	#onTabRemoved(tabKey: string): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		this.#retractTab(tab);
		this.#tabs.delete(tabKey);
		for (const conn of this.#conns.values()) conn.claims.delete(tabKey);
	}

	#onTabUpsert(snap: TabSnapshot, instanceId: string, opts: { silent?: boolean } = {}): void {
		const inst = this.#instances.get(instanceId);
		if (!inst) return;
		const key = tabKeyOf(inst.code, snap.tabId);
		let tab = this.#tabs.get(key);
		const becameActive = snap.active && (!tab || !tab.active || tab.windowId !== snap.windowId);
		if (!tab) {
			tab = new TabState(instanceId, inst.code, snap.tabId, snap);
			this.#tabs.set(key, tab);
		} else {
			if (tab.url !== snap.url) tab.refusal = undefined;
			// The user dragging a tab out of the omp group is an opt-out; the
			// relay never fights the user over grouping.
			if (tab.grouped && tab.ompGroupId !== undefined && snap.groupId !== tab.ompGroupId) {
				tab.grouped = false;
				tab.groupOptOut = true;
			}
			tab.update(snap);
			if (tab.discarded && tab.attaching && !tab.attachCancelled) {
				tab.attachGeneration++;
				tab.attachCancelled = true;
				tab.cancelAttach?.();
			}
		}
		if (becameActive) {
			for (const other of this.#tabs.values()) {
				if (other !== tab && other.instanceId === instanceId && other.windowId === snap.windowId)
					other.active = false;
			}
		}
		if (opts.silent) return;
		const eligible = this.#eligible(tab);
		this.#syncTabGrouping(tab);
		if (eligible && !tab.announced && !tab.discarded) {
			this.#announceTab(tab);
			return;
		}
		if ((!eligible || tab.discarded) && tab.announced) {
			// Puppeteer waits for attachments to announced targets.
			this.#retractTab(tab);
			this.#detachIfUnheld(tab.tabKey);
			return;
		}
		if (eligible && tab.announced) {
			for (const conn of this.#conns.values()) {
				if (!conn.discover) continue;
				this.#emit(conn, "Target.targetInfoChanged", { targetInfo: this.#tabInfo(tab, tab.attached) });
				this.#emit(conn, "Target.targetInfoChanged", { targetInfo: this.#pageInfo(tab, tab.attached) });
			}
		}
	}

	/** Announce an unannounced tab to discovering connections and attach it for auto-attaching ones. */
	#announceTab(tab: TabState): void {
		tab.announced = true;
		for (const conn of this.#conns.values()) {
			if (!conn.discover) continue;
			this.#emit(conn, "Target.targetCreated", { targetInfo: this.#tabInfo(tab, tab.attached) });
			this.#emit(conn, "Target.targetCreated", { targetInfo: this.#pageInfo(tab, tab.attached) });
		}
		this.#attachForAutoAttach(tab);
	}

	#attachForAutoAttach(tab: TabState): void {
		let hasAutoAttach = false;
		for (const conn of this.#conns.values()) {
			if (conn.autoAttach) {
				hasAutoAttach = true;
				break;
			}
		}
		if (!hasAutoAttach) return;
		void this.#ensureAttached(tab, { retryAfterDiscard: true }).then(ok => {
			if (!ok) {
				// A refused attach bars the tab until its URL changes. Withdraw the announcement too, or the URL change
				// finds the tab already announced and neither announces nor attaches it again.
				if (tab.refusal && tab.announced && this.#tabs.get(tab.tabKey) === tab) this.#retractTab(tab);
				return;
			}
			if (tab.discarded || !this.#eligible(tab) || this.#tabs.get(tab.tabKey) !== tab) {
				this.#retractTab(tab);
				this.#detachIfUnheld(tab.tabKey);
				return;
			}
			for (const conn of this.#conns.values()) {
				if (conn.autoAttach) this.#emitTabAttached(conn, tab);
			}
		});
	}

	// ---- tab grouping -----------------------------------------------------------

	/** Group a claimed, eligible, unpinned tab unless the user grouped or opted it out. */
	#groupWorthy(tab: TabState): boolean {
		if (!this.#claimed(tab.tabKey) || !this.#eligible(tab) || tab.pinned || tab.groupOptOut) return false;
		return tab.grouped || tab.groupId === -1;
	}

	/** Re-group every claimed tab (extension hello / reconnect). */
	#syncGrouping(): void {
		if (!this.#group) return;
		const worthy = [...this.#tabs.values()].filter(tab => this.#groupWorthy(tab) && !tab.grouped && !tab.grouping);
		if (worthy.length > 0) this.#requestGroup(worthy);
	}

	/** Reconcile one tab's group membership after a lifecycle event. */
	#syncTabGrouping(tab: TabState): void {
		if (!this.#group) return;
		if (this.#groupWorthy(tab)) {
			if (!tab.grouped && !tab.grouping) this.#requestGroup([tab]);
			return;
		}
		if (tab.grouped) {
			tab.grouped = false;
			tab.ompGroupId = undefined;
			void this.#rpc({ op: "ungroup", tabIds: [tab.tabId] }, this.#instanceFor(tab)).catch(() => {});
		}
	}

	/** Move an omp-owned tab out of its previous session group before re-grouping. */
	#ungroupForRelabel(tab: TabState): void {
		if (!tab.grouped) return;
		tab.grouped = false;
		tab.ompGroupId = undefined;
		// The old group was ours, not a user group; keep it eligible while ungroup runs.
		tab.groupId = -1;
		void this.#rpc({ op: "ungroup", tabIds: [tab.tabId] }, this.#instanceFor(tab)).catch(() => {});
	}

	/**
	 * Queue tabs for grouping and drain serially. Overlapping group RPCs race
	 * the extension's non-atomic query→create→set-title sequence and mint
	 * duplicate omp groups, so at most one group RPC is ever in flight.
	 */
	#requestGroup(tabs: TabState[]): void {
		if (!this.#group) return;
		for (const tab of tabs) {
			tab.grouping = true;
			this.#groupQueue.push(tab);
		}
		if (!this.#groupDraining) void this.#drainGroupQueue();
	}

	async #drainGroupQueue(): Promise<void> {
		const group = this.#group;
		if (!group) return;
		this.#groupDraining = true;
		try {
			while (this.#groupQueue.length > 0) {
				const batch = this.#groupQueue.splice(0);
				// A group RPC addresses one browser instance and one session label.
				const byGroup = new Map<string, { instanceId: string; label?: string; tabs: TabState[] }>();
				for (const tab of batch) {
					const key = `${tab.instanceId}\u0000${tab.label ?? ""}`;
					const entry = byGroup.get(key);
					if (entry) entry.tabs.push(tab);
					else byGroup.set(key, { instanceId: tab.instanceId, label: tab.label, tabs: [tab] });
				}
				for (const { instanceId, label, tabs } of byGroup.values()) {
					const inst = this.#instances.get(instanceId);
					if (!inst?.socket) {
						for (const tab of tabs) tab.grouping = false;
						continue;
					}
					const tabIds = tabs.map(tab => tab.tabId);
					try {
						const result = await this.#rpc(
							{ op: "group", tabIds, title: label ? `omp/${label}` : group.title, color: group.color },
							inst,
						);
						// Extension replies { grouped: { [tabId]: groupId } }; validate per entry.
						const grouped: Record<string, unknown> =
							result &&
							typeof result === "object" &&
							"grouped" in result &&
							result.grouped &&
							typeof result.grouped === "object"
								? (result.grouped as Record<string, unknown>)
								: {};
						for (const tab of tabs) {
							const groupId = grouped[String(tab.tabId)];
							if (typeof groupId !== "number") continue;
							tab.grouped = true;
							tab.ompGroupId = groupId;
						}
						this.#log("grouped tabs", { instanceId, tabIds, grouped });
					} catch (err) {
						this.#log("tab grouping failed", { error: err instanceof Error ? err.message : String(err) });
					} finally {
						for (const tab of tabs) {
							tab.grouping = false;
							if (tab.label !== label) {
								this.#ungroupForRelabel(tab);
								this.#syncTabGrouping(tab);
							}
							// The claim may have gone while the RPC was in flight (its client closed): undo the grouping.
							if (tab.grouped && !this.#groupWorthy(tab)) this.#syncTabGrouping(tab);
						}
					}
				}
			}
		} finally {
			this.#groupDraining = false;
		}
	}

	/** Tear a tab out of every downstream connection (closed, detached, or now ineligible). */
	#retractTab(tab: TabState): void {
		this.#forgetChildren(tab);
		for (const conn of this.#conns.values()) {
			const tabSessions = conn.sessionsForTab(tab.tabKey, "tab");
			for (const pageSession of conn.sessionsForTab(tab.tabKey, "page")) {
				conn.sessions.delete(pageSession);
				this.#emit(
					conn,
					"Target.detachedFromTarget",
					{ sessionId: pageSession, targetId: pageTargetIdFromKey(tab.tabKey) },
					tabSessions[0],
				);
			}
			for (const tabSession of tabSessions) {
				conn.sessions.delete(tabSession);
				this.#emit(conn, "Target.detachedFromTarget", {
					sessionId: tabSession,
					targetId: tabTargetIdFromKey(tab.tabKey),
				});
			}
			if (conn.discover && tab.announced) {
				this.#emit(conn, "Target.targetDestroyed", { targetId: pageTargetIdFromKey(tab.tabKey) });
				this.#emit(conn, "Target.targetDestroyed", { targetId: tabTargetIdFromKey(tab.tabKey) });
			}
		}
		tab.announced = false;
	}

	// ---- session + attach bookkeeping --------------------------------------------

	#mintSession(conn: CdpConnection, kind: "tab" | "page", tab: TabState): string {
		const sessionId = `S${kind === "tab" ? "T" : "P"}${tab.tabId}.${conn.id}.${++this.#sessionSeq}`;
		conn.sessions.set(sessionId, {
			kind,
			tabKey: tab.tabKey,
			tabId: tab.tabId,
			runtimeState: "default",
			runtimeContexts: new Set(),
			runtimeEnabling: null,
			runtimeEpoch: 0,
			autoAttach: false,
			switches: new Set(),
		});
		return sessionId;
	}

	#releaseSession(conn: CdpConnection, sessionId: string, parentSessionId: string | undefined): void {
		const ref = conn.sessions.get(sessionId);
		if (!ref) return;
		conn.sessions.delete(sessionId);
		this.#releaseSwitches(ref);
		if (ref.autoAttach) this.#releaseAutoAttach(ref.tabKey);
		if (ref.kind === "page" && !conn.childTargetSessionForTab(ref.tabKey)) {
			const tab = this.#tabs.get(ref.tabKey);
			if (tab) this.#forgetConnectionChildren(conn, tab, true);
		}
		const targetId = ref.kind === "tab" ? tabTargetIdFromKey(ref.tabKey) : pageTargetIdFromKey(ref.tabKey);
		this.#emit(conn, "Target.detachedFromTarget", { sessionId, targetId }, parentSessionId);
		// An explicit release of the last session must drop the attachment too,
		// or it outlives every downstream session: the infobar stays up, and
		// dismissing it bans the tab for the rest of the epoch.
		this.#detachIfUnheld(ref.tabKey);
	}

	/**
	 * Release the tab's chrome.debugger attachment once no downstream session
	 * holds it. Inert while the long-lived registry connection still holds one.
	 */
	#detachIfUnheld(tabKey: string): void {
		if (this.#sessionHolders(tabKey).length > 0) return;
		const tab = this.#tabs.get(tabKey);
		if (!tab?.attached) return;
		tab.attached = false;
		this.#resetRuntime(tab);
		this.#forgetChildren(tab);
		tab.reattachedAfterDetach = false;
		// In a real Chrome CDP session, detaching during a focus-emulation reset can strand the next session.
		// Wait for in-flight tab-wide switches (bounded by their RPC timeout) before ending the attachment.
		const transitions = TAB_WIDE_SWITCHES.map(method => this.#switchTransitions.get(`${tabKey} ${method}`)).filter(
			pending => pending !== undefined,
		);
		const done = (async () => {
			if (transitions.length > 0) await Promise.all(transitions);
			await this.#rpc({ op: "detach", tabId: tab.tabId }, this.#instanceFor(tab));
		})()
			.catch(() => {})
			.finally(() => {
				if (tab.detaching === done) tab.detaching = null;
			});
		tab.detaching = done;
	}

	#resetRuntime(tab: TabState): void {
		tab.runtimeContexts.clear();
		tab.rootRuntimeEnabled = false;
		tab.rootRuntimeEnabling = null;
		tab.runtimeGeneration++;
	}

	/**
	 * Drop the tab's real child sessions, which end with its debugger attachment, and send each
	 * connection told of one its detach; nested children go first, while their parent is still known.
	 */
	#forgetChildren(tab: TabState): void {
		for (const conn of this.#conns.values()) this.#forgetConnectionChildren(conn, tab);
		for (const child of tab.realSessions.keys()) this.#realSessionTabs.delete(child);
		tab.realSessions.clear();
	}

	/** Connections currently holding any session on a tab. */
	#sessionHolders(tabKey: string): CdpConnection[] {
		const out: CdpConnection[] = [];
		for (const conn of this.#conns.values()) {
			if (conn.sessionsForTab(tabKey).length > 0) out.push(conn);
		}
		return out;
	}
	#autoAttaches(tabKey: string): boolean {
		for (const conn of this.#conns.values()) {
			if (conn.childTargetSessionForTab(tabKey)) return true;
		}
		return false;
	}

	#forgetConnectionChildren(conn: CdpConnection, tab: TabState, automaticOnly = false): void {
		for (const child of [...tab.realSessions.keys()].reverse()) {
			const parent = conn.childParents.get(child);
			if (!parent) continue;
			if (automaticOnly) {
				let ancestor = child;
				while (!conn.explicitChildren.has(ancestor)) {
					const next = conn.childParents.get(ancestor);
					if (!next) break;
					ancestor = next;
				}
				if (conn.explicitChildren.has(ancestor)) continue;
			}
			conn.childParents.delete(child);
			conn.explicitChildren.delete(child);
			this.#emit(conn, "Target.detachedFromTarget", { sessionId: child }, parent);
		}
	}

	/** A departed holder must not leave auto-attach enabled on a registry-held tab. */
	#releaseAutoAttach(tabKey: string): void {
		void this.#serializeSwitches(tabKey, "Target.setAutoAttach", async () => {
			if (this.#autoAttaches(tabKey)) return;
			const tab = this.#tabs.get(tabKey);
			const inst = tab?.attached ? this.#instances.get(tab.instanceId) : undefined;
			if (!tab || !inst) return;
			await this.#send(tab, inst, "Target.setAutoAttach", {
				autoAttach: false,
				waitForDebuggerOnStart: false,
				flatten: true,
			}).catch(() => {});
		});
	}

	/** Whether any live session on a tab, across connections, has `method` switched on. */
	#switchWanted(tabKey: string, method: TabWideSwitch): boolean {
		for (const conn of this.#conns.values()) {
			for (const ref of conn.sessions.values()) {
				if (ref.tabKey === tabKey && ref.switches.has(method)) return true;
			}
		}
		return false;
	}

	/**
	 * Switch off what a departed session left on, unless another live session of the tab still wants it: a session
	 * that went away without turning it off (a killed worker) would otherwise leave it on for as long as the attachment
	 * lasts, swallowing every chooser or keeping a background tab visible.
	 */
	#releaseSwitches(ref: SessionRef): void {
		for (const method of ref.switches) this.#sendSwitch(ref.tabKey, method, false);
	}

	/**
	 * Send `method` as `enabled` once the tab's earlier transitions settle, unless live sessions want otherwise by
	 * then: a release must not switch off what another session has since asked for.
	 */
	#sendSwitch(tabKey: string, method: TabWideSwitch, enabled: boolean): void {
		void this.#serializeSwitches(tabKey, method, async () => {
			if (this.#switchWanted(tabKey, method) !== enabled) return;
			const tab = this.#tabs.get(tabKey);
			if (!tab) return;
			const inst = tab.attached ? this.#instances.get(tab.instanceId) : undefined;
			if (!inst?.socket) {
				tab.unsettledSwitches.add(method);
				return;
			}
			await this.#rpc({ op: "send", tabId: tab.tabId, method, params: { enabled } }, inst).catch(() => {
				tab.unsettledSwitches.add(method);
			});
		});
	}

	/**
	 * Run one tab switch's transitions one at a time, each sending the tab-wide state as it stands when it runs.
	 * The extension starts RPCs independently, so overlapping transitions could settle out of order; a failed one's
	 * rollback would then restore a state another transition had already changed on the tab.
	 */
	#serializeSwitches(
		tabKey: string,
		method: TabWideSwitch | "Target.setAutoAttach",
		run: () => Promise<void>,
	): Promise<void> {
		const key = `${tabKey} ${method}`;
		const pending = this.#switchTransitions.get(key);
		const result = pending ? pending.then(run) : run();
		const tail = result.catch(() => {});
		this.#switchTransitions.set(key, tail);
		void tail.then(() => {
			if (this.#switchTransitions.get(key) === tail) this.#switchTransitions.delete(key);
		});
		return result;
	}

	#emitTabAttached(conn: CdpConnection, tab: TabState): void {
		if (conn.sessionsForTab(tab.tabKey, "tab").length > 0) return;
		const sessionId = this.#mintSession(conn, "tab", tab);
		this.#emit(conn, "Target.attachedToTarget", {
			sessionId,
			targetInfo: this.#tabInfo(tab, true),
			waitingForDebugger: false,
		});
	}

	async #ensureAttached(tab: TabState, opts: { retryAfterDiscard?: boolean } = {}): Promise<boolean> {
		if (tab.discarded) return false;
		// The extension emits the detach echo before resolving the RPC. Awaiting
		// prevents a replacement attach racing either operation.
		while (tab.detaching) await tab.detaching;
		if (tab.discarded) return false;
		if (tab.attached) return true;
		if (!this.#eligible(tab)) return false;
		const inst = this.#instances.get(tab.instanceId);
		if (!inst?.socket) return false;
		if (tab.attaching) {
			if (tab.attachCancelled && opts.retryAfterDiscard) tab.retryAttachAfterDiscard = true;
			return await tab.attaching;
		}
		const generation = tab.attachGeneration;
		const cancelled = Promise.withResolvers<boolean>();
		const request = this.#rpc({ op: "attach", tabId: tab.tabId }, inst)
			.then(() => {
				tab.attached = true;
				tab.reattachedAfterDetach = true;
				if (tab.discarded) this.#detachIfUnheld(tab.tabKey);
				return !tab.discarded;
			})
			.catch(err => {
				const error = err instanceof Error ? err.message : String(err);
				this.#log("attach failed", { tabKey: tab.tabKey, url: tab.url, error });
				if (
					!(err instanceof ExtensionReplacedError) &&
					!(err instanceof RpcTimeoutError) &&
					generation === tab.attachGeneration &&
					!/busy|not ready|settling|temporar|rpc failed|reattach failed|^debugger unavailable$/i.test(error)
				) {
					tab.refusal = error || "Chrome refused the attach";
				}
				return false;
			})
			.finally(() => {
				if (tab.attaching === attempt) {
					tab.attaching = null;
					tab.cancelAttach = null;
					tab.attachCancelled = false;
				}
				const retry = tab.retryAttachAfterDiscard;
				tab.retryAttachAfterDiscard = false;
				if (retry && !tab.discarded) this.#attachForAutoAttach(tab);
				// Every client left while Chrome attached: nobody can take a session on the tab, so release it.
				if (this.#conns.size === 0) this.#detachIfUnheld(tab.tabKey);
			});
		// Stop waiting for discarded tabs without dropping the extension RPC's late result.
		const attempt = Promise.race([request, cancelled.promise]);
		tab.attaching = attempt;
		tab.cancelAttach = () => cancelled.resolve(false);
		return await attempt;
	}

	#eligible(tab: TabState): boolean {
		if (tab.refusal) return false;
		const instance = this.#instances.get(tab.instanceId);
		if (!instance?.socket || instance.info?.discardedTabsProtocol !== DISCARDED_TABS_PROTOCOL_VERSION) return false;
		if (!tab.url) return true;
		return !INELIGIBLE_URL.test(tab.url);
	}

	#tabInfo(tab: TabState, attached: boolean): TargetInfo {
		return {
			targetId: tabTargetIdFromKey(tab.tabKey),
			type: "tab",
			title: tab.title,
			url: tab.url || "about:blank",
			attached,
			canAccessOpener: false,
		};
	}

	#pageInfo(tab: TabState, attached: boolean): TargetInfo {
		return {
			targetId: pageTargetIdFromKey(tab.tabKey),
			type: "page",
			title: tab.title,
			url: tab.url || "about:blank",
			attached,
			canAccessOpener: false,
		};
	}

	// ---- plumbing ---------------------------------------------------------------

	#reply(conn: CdpConnection, msg: CdpCommand, result: Record<string, unknown>): void {
		conn.socket.send(JSON.stringify({ id: msg.id, sessionId: msg.sessionId, result }));
	}

	#replyError(conn: CdpConnection, msg: CdpCommand, message: string, code = CDP_ERROR_SERVER): void {
		conn.socket.send(JSON.stringify({ id: msg.id, sessionId: msg.sessionId, error: { code, message } }));
	}

	#emit(conn: CdpConnection, method: string, params: Record<string, unknown>, sessionId?: string): void {
		conn.socket.send(JSON.stringify({ sessionId, method, params }));
	}

	/** The extension instance a tab belongs to; throws if the browser vanished. */
	#instanceFor(tab: TabState): ExtInstance {
		const inst = this.#instances.get(tab.instanceId);
		if (!inst) throw new Error("relay extension is not connected");
		return inst;
	}

	/** Download tracking is outside this fork's extension permission scope. */
	async #replyDownloadPath(conn: CdpConnection, msg: CdpCommand): Promise<boolean> {
		this.#replyError(conn, msg, "Download tracking is unavailable in this extension");
		return false;
	}

	#rpc(
		req: RelayRpcRequest,
		inst: ExtInstance,
		timeoutMs = RPC_TIMEOUT_MS,
		onLateResult?: (result: unknown) => void,
	): Promise<unknown> {
		if (!inst.socket) return Promise.reject(new Error("relay extension is not connected"));
		const id = ++this.#rpcSeq;
		const { promise, resolve, reject } = Promise.withResolvers<unknown>();
		const timer = setTimeout(() => {
			const key = `${inst.instanceId}:${id}`;
			this.#pendingRpc.delete(key);
			if (onLateResult) {
				const expiry = setTimeout(() => {
					this.#lateRpc.delete(key);
					if (this.#conns.size === 0) void this.#updateIdleExtensions();
				}, LATE_RPC_KEEP_MS);
				expiry.unref?.();
				this.#lateRpc.set(key, { onResult: onLateResult, timer: expiry });
			}
			const operation = req.op === "send" ? `${req.op} ${req.method}` : req.op;
			reject(new RpcTimeoutError(`extension rpc '${operation}' timed out after ${timeoutMs}ms`));
		}, timeoutMs);
		this.#pendingRpc.set(`${inst.instanceId}:${id}`, { resolve, reject, timer });
		// Claiming a tab does not grant authority to modify another extension's frames.
		const sent = req.op === "attach" || req.op === "send" ? { ...req, clearForeignFrames: false } : req;
		inst.socket.send(JSON.stringify({ t: "rpc", id, ...sent } satisfies RelayToExtMessage));
		// A pending call defers an extension update (see #reloadBlocker): retry it once the call and its cleanup settle.
		void promise
			.catch(() => undefined)
			.then(() => {
				if (this.#conns.size === 0) void this.#updateIdleExtensions();
			});
		return promise;
	}

	/**
	 * Close a tab omp opened. The extension retries a close Chrome refuses before answering, so the caller holds
	 * its relay lease through the retry. One whose close still fails (its browser offline, the socket dropping
	 * mid-call, or Chrome refusing every try) is closed at that browser's next hello, unless the user closed it.
	 */
	async #closeTab(key: string, tabId: number, inst: ExtInstance): Promise<void> {
		const tab = this.#tabs.get(key);
		if (!key.startsWith(`${inst.code}:`) || !tab?.ompCreated)
			throw new Error("Target ownership is no longer current");
		if (tab.closeAttempt) return await tab.closeAttempt;
		tab.closing = true;
		const close = this.#rpc({ op: "removeTab", tabId }, inst)
			.then(result => {
				if (!result || typeof result !== "object" || !("closed" in result) || result.closed !== true)
					throw new Error("Extension did not confirm target closure");
			})
			.catch(err => {
				tab.closing = false;
				tab.closeAttempt = null;
				if (key.startsWith(`${inst.code}:`) && this.#tabs.get(key) === tab && tab.ompCreated)
					this.#closeOnHello.set(key, tab.url);
				throw err;
			});
		tab.closeAttempt = close;
		await close;
	}
}

/** Most hidden frames a tab holds for its next worker; older reports give way to newer ones. */
const MAX_HIDDEN_FRAMES = 16;
/** Longest extension id, path or title a hidden-frame report keeps. */
const HIDDEN_FRAME_FIELD_MAX = 100;

/** `text` on one line, without control, format or line/paragraph separator characters, at most `max` characters. */
function singleLine(text: string, max: number): string {
	return text
		.replace(/[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]+/gu, " ")
		.trim()
		.slice(0, max);
}

/**
 * Daemon-supervised browser relay.
 *
 * The MV3 extension can only dial OUT (service workers cannot listen on
 * sockets), so a native process must own the relay port. Instead of making
 * the user run `omp browser-relay` by hand, the relay kind lazily starts one
 * as a global `proc` unit of the omp daemon. Every relay consumer holds a
 * lease on it, so one project exiting cannot tear down the fixed-port
 * singleton while another project still uses it; it runs detached from the
 * daemon, so a daemon crash or upgrade keeps it.
 *
 * A manually started relay may already own the port; consumers adopt that
 * external server without attempting another bind (and hold no lease).
 */
import * as os from "node:os";
import type { UnitPolicy, UnitSnapshot } from "@oh-my-pi/pi-tui/tools/daemon";
import { logger } from "@oh-my-pi/pi-utils";
import { VERSION } from "@oh-my-pi/pi-utils/dirs";
import { daemonClient } from "../../../daemon/client";
import { type DaemonClient, GLOBAL_SCOPE, type OpenRequest } from "../../../daemon/protocol";
import { resolveWorkerSpawnCmd, workerEnvFromParent } from "../../../subprocess/worker-client";
import { throwIfAborted } from "../../tool-errors";
import { probeCdpResponse, probeCdpStatus } from "../attach";
import { describeUnit, isLiveUnit, type UnitIdentity, UnitLease } from "../unit-lease";
import { DEFAULT_RELAY_URL } from "./kind";
import { relayCdpClientsOf, relayVersionOf } from "./probe";
import { isOlderOmpVersion } from "./protocol";

const DEFAULT_RELAY_PORT = new URL(DEFAULT_RELAY_URL).port;

/** Unit key of the relay on `port`; one per port, so relays on different ports never replace each other. */
function relayUnitIdentity(port: string): UnitIdentity {
	return {
		kind: "proc",
		scope: GLOBAL_SCOPE,
		key: port === DEFAULT_RELAY_PORT ? "omp.browser.relay" : `omp.browser.relay.${port}`,
	};
}

function relayPort(cdpUrl: string): string | null {
	try {
		return String(new URL(cdpUrl).port || 80);
	} catch {
		return null;
	}
}

/** Matches the serve banner (`omp browser relay listening on http://…`). */
const READY_LOG_PATTERN = String.raw`browser relay listening on http://\S+`;
const READY_TIMEOUT_MS = 15_000;
const PROBE_TIMEOUT_MS = 1_500;
const STOP_TIMEOUT_MS = 5_000;
/**
 * The relay dies shortly after its last consumer lets go (`hold: "leases"`).
 * It runs in its own session with output to its unit log (`survive:
 * "detached"`), so a daemon crash or upgrade leaves it serving: the next daemon
 * re-adopts it and stops it once no returning consumer retakes a lease within
 * the reconnect grace.
 */
const RELAY_POLICY: Partial<UnitPolicy> = {
	hold: "leases",
	idleMs: 3_000,
	onIdle: "stop",
	restart: "no",
	survive: "detached",
};

/** True when the relay HTTP server answers /json/version at all (200 = extension connected, 503 = waiting for it). */
export async function probeRelayServer(cdpUrl: string): Promise<boolean> {
	const status = await probeCdpStatus(`${cdpUrl}/json/version`, { timeoutMs: PROBE_TIMEOUT_MS });
	return status === 503 || (status !== null && status >= 200 && status < 300);
}

/** Auto-start is only safe for endpoints this machine can own. */
export function isLoopbackRelayUrl(cdpUrl: string): boolean {
	try {
		const { hostname } = new URL(cdpUrl);
		return hostname === "127.0.0.1" || hostname === "localhost" || hostname === "[::1]" || hostname === "::1";
	} catch {
		return false;
	}
}

function relayOpenRequest(port: string): OpenRequest {
	const spawn = resolveWorkerSpawnCmd("browser-relay");
	return {
		...relayUnitIdentity(port),
		label: `Browser relay :${port}`,
		proc: {
			application: spawn.cmd[0]!,
			args: [...spawn.cmd.slice(1), "--port", port],
			env: workerEnvFromParent(),
			cwd: spawn.cwd ?? os.homedir(),
			pty: false,
			ready: { log: READY_LOG_PATTERN, timeoutMs: READY_TIMEOUT_MS },
		},
		policy: RELAY_POLICY,
	};
}

/** Open the relay unit and keep its lease when it serves `cdpUrl`; otherwise drop the lease and resolve null. */
async function openRelay(
	client: DaemonClient,
	request: OpenRequest,
	cdpUrl: string,
	replace: boolean,
	signal?: AbortSignal,
): Promise<UnitLease | null> {
	let lease: UnitLease;
	try {
		lease = new UnitLease(client, request, await client.open({ ...request, replace }, signal));
	} catch (error) {
		throwIfAborted(signal);
		logger.debug("Browser relay open failed", {
			key: request.key,
			error: error instanceof Error ? error.message : String(error),
		});
		return null;
	}
	if (await probeRelayServer(cdpUrl)) return lease;
	await lease.release();
	return null;
}

/**
 * Ensure a relay server answers at `cdpUrl`, starting the daemon-supervised
 * relay when nothing is serving, and lease it. The extension handshake
 * (503 → 200) is the caller's wait. Resolves the lease the caller holds while
 * it uses the relay, or null when a relay the daemon does not run serves
 * there, or when the relay could not be started (the caller's wait then
 * reports it unreachable). A live relay unit that does not answer is
 * replaced once.
 */
export async function ensureRelayDaemon(opts: { cdpUrl: string; signal?: AbortSignal }): Promise<UnitLease | null> {
	const port = relayPort(opts.cdpUrl);
	if (port === null) return null;
	const client = await daemonClient();
	throwIfAborted(opts.signal);
	const request = relayOpenRequest(port);
	if (await probeRelayServer(opts.cdpUrl)) {
		// Serving: lease our own unit, but never start one against a manual relay.
		const existing = await describeUnit(client, relayUnitIdentity(port), opts.signal);
		return isLiveUnit(existing) ? openRelay(client, request, opts.cdpUrl, false, opts.signal) : null;
	}
	const opened = await openRelay(client, request, opts.cdpUrl, false, opts.signal);
	if (opened) return opened;
	// A manual serve may have won the port meanwhile (ours then failed to bind); adopt it.
	if (await probeRelayServer(opts.cdpUrl)) return null;
	// Live unit but nothing listening: replace the wedged relay.
	return openRelay(client, request, opts.cdpUrl, true, opts.signal);
}

/** Outcome of {@link restartRelayDaemon}. */
export interface RelayRestart {
	/** The outdated relay stopped, or another process already replaced it. */
	restarted: boolean;
	/** The lease the caller holds from now on; the old one was released when this differs from it. */
	lease: UnitLease | null;
}

/**
 * Replace the daemon-supervised relay at `cdpUrl` with one from this OMP
 * version when it comes from an older one; with `idleOnly`, only while it
 * reports no CDP client connected. `restarted` is true once the old relay has
 * stopped (the caller's wait reports whether the new one serves) or another
 * process already replaced it or stopped it to replace it. False when a relay
 * the daemon does not run serves there (a manually started relay is left
 * alone), the relay comes from a newer OMP (a concurrently running newer omp
 * owns it), an `idleOnly` relay has a client or does not report its clients,
 * or the old relay did not stop.
 */
export async function restartRelayDaemon(opts: {
	cdpUrl: string;
	lease: UnitLease | null;
	signal?: AbortSignal;
	idleOnly?: boolean;
}): Promise<RelayRestart> {
	const kept: RelayRestart = { restarted: false, lease: opts.lease };
	const port = relayPort(opts.cdpUrl);
	if (port === null) return kept;
	const client = await daemonClient();
	const identity = relayUnitIdentity(port);
	const existing = await describeUnit(client, identity, opts.signal);
	if (!existing || !isLiveUnit(existing)) {
		// Another omp may have stopped the old relay and not yet registered its
		// replacement; start or adopt it unless a relay the daemon does not run serves.
		const serving = await probeRelayServer(opts.cdpUrl);
		throwIfAborted(opts.signal);
		if (serving) return { ...kept, restarted: (await relayStatusAt(opts.cdpUrl, opts.signal))?.version === VERSION };
		// Restarted even if the start fails: the caller's next wait then reports
		// the relay unreachable, which is accurate, rather than out of date.
		return { restarted: true, lease: await swapLease(opts.lease, await ensureRelayDaemon(opts)) };
	}
	// Another omp of this version may have replaced it since the caller's probe,
	// possibly with a relay that has not printed its ready line yet.
	if (existing.state === "starting") await waitRelayReady(client, existing, opts.signal);
	const status = await relayStatusAt(opts.cdpUrl, opts.signal);
	if (status?.version === VERSION) {
		// Possibly another omp's replacement: move the lease onto it.
		const lease =
			opts.lease?.unit.generation === existing.generation
				? opts.lease
				: await swapLease(opts.lease, await ensureRelayDaemon(opts));
		return { restarted: true, lease };
	}
	// A newer omp running alongside this one owns a newer relay; replacing it
	// would only make the two versions take turns killing each other's relay.
	if (status !== null && !isOlderOmpVersion(status.version, VERSION)) return kept;
	// The last read before the stop: a client that connected since the caller's
	// probe keeps the relay. One connecting during the stop request itself loses
	// its connection, as on any relay restart.
	if (opts.idleOnly && status?.cdpClients !== 0) return kept;
	// Stops only the generation judged outdated, not one another omp started since.
	const stopped = await stopRelay(client, existing, opts.signal);
	if (stopped && !isLiveUnit(stopped)) {
		// As above: a failed start surfaces as unreachable on the caller's wait.
		return { restarted: true, lease: await swapLease(opts.lease, await ensureRelayDaemon(opts)) };
	}
	if (stopped === undefined || stopped.generation === existing.generation) return kept;
	// Another omp replaced it meanwhile: lease the replacement.
	if (stopped.state === "starting") await waitRelayReady(client, stopped, opts.signal);
	return { restarted: true, lease: await swapLease(opts.lease, await ensureRelayDaemon(opts)) };
}

/** Release `previous` in favour of `next` (which may be the same lease or null). */
async function swapLease(previous: UnitLease | null, next: UnitLease | null): Promise<UnitLease | null> {
	if (previous && previous !== next) await previous.release();
	return next;
}

async function waitRelayReady(client: DaemonClient, unit: UnitSnapshot, signal?: AbortSignal): Promise<void> {
	try {
		await client.request({ op: "wait", unit: unit.id, for: "ready", timeoutMs: READY_TIMEOUT_MS }, signal);
	} catch (error) {
		throwIfAborted(signal);
		logger.debug("Browser relay ready wait failed", {
			key: unit.key,
			error: error instanceof Error ? error.message : String(error),
		});
	}
}

async function stopRelay(
	client: DaemonClient,
	unit: UnitSnapshot,
	signal?: AbortSignal,
): Promise<UnitSnapshot | undefined> {
	try {
		return (
			await client.request(
				{ op: "stop", unit: unit.id, timeoutMs: STOP_TIMEOUT_MS, generation: unit.generation },
				signal,
			)
		).unit;
	} catch (error) {
		throwIfAborted(signal);
		logger.debug("Browser relay stop failed", {
			key: unit.key,
			error: error instanceof Error ? error.message : String(error),
		});
		return undefined;
	}
}

/**
 * The OMP version (empty for a relay too old to report one) and connected CDP
 * client count the relay at `cdpUrl` reports on `/json/version`, ready or
 * waiting for its extension; null when nothing parseable answers.
 */
async function relayStatusAt(
	cdpUrl: string,
	signal: AbortSignal | undefined,
): Promise<{ version: string; cdpClients: number | null } | null> {
	const response = await probeCdpResponse(`${cdpUrl}/json/version`, { timeoutMs: PROBE_TIMEOUT_MS, signal });
	throwIfAborted(signal);
	if (!response) return null;
	try {
		const parsed: unknown = JSON.parse(response.body);
		return typeof parsed === "object" && parsed !== null
			? { version: relayVersionOf(parsed), cdpClients: relayCdpClientsOf(parsed) }
			: null;
	} catch {
		return null;
	}
}

