		await flush();
		bridge.extMessage(ext, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 9, groupId: 43 }) }));
		bridge.cdpMessage(
			connId,
			JSON.stringify({
				id: ++msgSeq,
