		await armAutoAttach(bridge, ext, first, session);
		const secondCdp = new FakeCdpSocket();
		const second = bridge.cdpConnected(secondCdp);
		const other = await attachPage(bridge, ext, secondCdp, second, 1);
		bridge.cdpMessage(
			second,
			JSON.stringify({
